// Existing bridge controls have no unresolved loop dependency. Production has
// no scope-free entry point; tests retain the old convenience signature only.
fn bridge_v1_ay_proofs_into_native_results(
    timeout: u64,
    deadline: Option<std::time::Instant>,
    solver_vcs: &[VerificationCondition],
    bindings: &mut [Option<ResultObligationBinding>],
    stamp: bool,
    results: Vec<(VerificationCondition, VerificationResult)>,
) -> (
    Vec<(VerificationCondition, VerificationResult)>,
    u32,
    u32,
    Vec<Option<SolverRevalidationEligibility>>,
) {
    bridge_v1_ay_proofs_into_native_results_recording_clock_stops(
        timeout,
        deadline,
        solver_vcs,
        bindings,
        &mut ClockStops::default(),
        stamp,
        results,
    )
}

// The same, keeping the rows a clock cut (determinism plan §3.7).
fn bridge_v1_ay_proofs_into_native_results_recording_clock_stops(
    timeout: u64,
    deadline: Option<std::time::Instant>,
    solver_vcs: &[VerificationCondition],
    bindings: &mut [Option<ResultObligationBinding>],
    clock_stops: &mut ClockStops,
    stamp: bool,
    results: Vec<(VerificationCondition, VerificationResult)>,
) -> (
    Vec<(VerificationCondition, VerificationResult)>,
    u32,
    u32,
    Vec<Option<SolverRevalidationEligibility>>,
) {
    let function = bridge_test_function();
    let scope = trust_vcgen::GenericRefutationScope::for_function(&function, &[], &[]);
    super::bridge_v1_ay_proofs_into_native_results_with_scope(
        &scope,
        timeout,
        trust_types::determinism::EffortScale::BUILTIN,
        deadline,
        solver_vcs,
        bindings,
        clock_stops,
        stamp,
        results,
        None,
    )
}

// The empty function the bridge controls are scoped to.
fn bridge_test_function() -> trust_types::VerifiableFunction {
    trust_types::VerifiableFunction {
        name: "bridge-test".into(),
        def_path: "bridge-test".into(),
        span: SourceSpan::default(),
        body: trust_types::VerifiableBody {
            locals: vec![],
            blocks: vec![],
            arg_count: 0,
            return_ty: trust_types::Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

fn bridge_replay_test_vc() -> VerificationCondition {
    let mut vc = test_vc(446);
    vc.function = "bridge-test".into();
    vc.kind = VcKind::SliceBoundsCheck;
    let x = || Formula::Var("bridge_replay_x".into(), Sort::Int);
    vc.formula = Formula::And(vec![
        Formula::Lt(Box::new(x()), Box::new(Formula::Int(0))),
        Formula::Lt(Box::new(Formula::Int(0)), Box::new(x())),
    ]);
    vc
}

#[test]
fn v1_bridge_replay_child() {
    let Some(mode) = std::env::var_os("TRUST_TEST_BRIDGE_REPLAY_MODE") else { return };
    let root = std::path::PathBuf::from(std::env::var_os("TRUST_TEST_BRIDGE_REPLAY_ROOT").unwrap());
    let mut vc = bridge_replay_test_vc();
    if mode == "changed" {
        vc.formula = Formula::Lt(
            Box::new(Formula::Var("bridge_replay_x".into(), Sort::Int)),
            Box::new(Formula::Int(0)),
        );
    }
    let function = bridge_test_function();
    let scope = trust_vcgen::GenericRefutationScope::for_function(&function, &[], &[]);
    let obligation = authority_test_native_obligation("bridge:replay", 446, 446);
    let mut bindings = vec![test_binding_for_obligation(0, &vc, &obligation)];
    assert!(bindings[0].is_some());
    let (results, proved, failed, eligibility) = bridge_v1_ay_proofs_into_native_results_with_scope(
        &scope,
        5000,
        trust_types::determinism::EffortScale::BUILTIN,
        Some(std::time::Instant::now() + std::time::Duration::from_secs(15)),
        std::slice::from_ref(&vc),
        &mut bindings,
        &mut ClockStops::default(),
        true,
        vec![(vc.clone(), bridge_test_unknown())],
        (mode != "cold").then_some(root.as_path()),
    );
    assert_eq!(results.len(), 1);
    if mode == "changed" {
        assert_eq!((proved, failed), (0, 1));
    } else {
        assert_eq!((proved, failed), (1, 0));
        if mode == "warm" {
            assert!(eligibility[0].is_none(), "a replay must not claim an AY producer receipt");
            assert!(matches!(&results[0].1, VerificationResult::Proved { solver, .. }
                if solver.as_str() == "clean-kernel-certified"));
        }
    }
}

#[test]
fn v1_bridge_replays_before_ay_dispatch() {
    struct Scratch(std::path::PathBuf);
    impl Drop for Scratch {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let requested = std::env::temp_dir().join(format!(
        "trust-bridge-replay-{}-{}",
        std::process::id(),
        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),
    ));
    std::fs::create_dir(&requested).unwrap();
    // Trust: the session root is the canonical spelling, as targo's
    // `VerificationSession::create` passes it. macOS `temp_dir()` sits under
    // the `/var` -> `/private/var` alias, and the lazy import's work lock
    // refuses a non-canonical token parent, so the warm child silently missed
    // the published proof and dispatched AY (BRIDGE-REPLAY-CANONICAL-ROOT-1).
    let root = Scratch(requested.canonicalize().unwrap());
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&root.0, std::fs::Permissions::from_mode(0o700)).unwrap();
    }
    let store = trust_certify::proof_artifacts::ProofArtifactStore::open(&root.0).unwrap();
    assert!(
        trust_certify::proof_artifacts::certify_vc_with_artifacts(
            &bridge_replay_test_vc(),
            &root.0,
        )
        .is_some()
    );
    assert_eq!(store.publish_session(&root.0).unwrap(), 1);
    // Trust: preparation configures exact-key lazy import, without eagerly
    // copying the pool. The warm child below must actually replay the proof
    // in the current kernel while dispatching no AY query.
    store.prepare_session(&root.0).unwrap();
    let mut counts = Vec::new();
    for mode in ["cold", "warm", "changed"] {
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args(["--exact", "trust_verify::tests::v1_bridge_replay_child", "--nocapture"])
            .env("TRUST_TEST_BRIDGE_REPLAY_MODE", mode)
            .env("TRUST_TEST_BRIDGE_REPLAY_ROOT", &root.0)
            .env("TRUST_AY_SMT_TRACE", "1")
            .output()
            .unwrap();
        assert!(output.status.success(), "{mode}: {output:?}");
        let stderr = String::from_utf8_lossy(&output.stderr);
        let count = stderr.matches("[aysmt] ---- program handed to ay ----").count();
        if mode == "warm" {
            assert_eq!(count, 0, "{stderr}");
        } else {
            assert!(count > 0, "{mode} must actually reach AY: {stderr}");
        }
        counts.push((mode, count));
    }
    eprintln!("native bridge AY dispatches: {counts:?}");
}

fn unresolved_loop_bridge_fixture() -> (trust_types::VerifiableFunction, VerificationCondition) {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty,
    };
    let assign = |destination, source| Statement::Assign {
        place: Place::local(destination),
        rvalue: Rvalue::Use(Operand::Copy(Place::local(source))),
        span: SourceSpan::default(),
    };
    let function = trust_types::VerifiableFunction {
        name: "test::f".into(),
        def_path: "test::f".into(),
        span: SourceSpan::default(),
        body: trust_types::VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: Ty::usize(), name: Some("len".into()) },
                LocalDecl { index: 2, ty: Ty::usize(), name: Some("hi".into()) },
                LocalDecl { index: 3, ty: Ty::usize(), name: Some("index".into()) },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![assign(2, 1)],
                    terminator: Terminator::Goto(BlockId(1)),
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![assign(3, 2)],
                    terminator: Terminator::Goto(BlockId(2)),
                },
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![assign(2, 2)],
                    terminator: Terminator::Goto(BlockId(1)),
                },
            ],
            arg_count: 1,
            return_ty: Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: vec![],
        preconditions: vec![],
        postconditions: vec![],
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let mut gap = test_vc(440);
    gap.kind = VcKind::UnsupportedMir {
        kind: "UserLoopContractUnsupported".into(),
        detail: "e4.machine.mixed-domain".into(),
    };
    (function, gap)
}

fn loop_bridge_query(raw: Formula, facts: Vec<Formula>) -> VerificationCondition {
    let mut vc = test_vc(441);
    vc.kind = VcKind::SliceBoundsCheck;
    vc.formula = Formula::And(facts.iter().cloned().chain(std::iter::once(raw.clone())).collect());
    vc.obligation = Some(trust_types::ObligationRecord {
        body: raw,
        wrappers: vec![trust_types::ObligationWrapper::ConjoinFactsLast { facts }],
        subject: None,
        width: None,
    });
    vc
}

#[test]
fn v1_bridge_unresolved_loop_sat_is_held_before_substitution_and_stays_strict() {
    let (function, gap) = unresolved_loop_bridge_fixture();
    let var = |name: &str| Formula::Var(name.into(), Sort::Int);
    let vc = loop_bridge_query(
        Formula::Ge(Box::new(var("index")), Box::new(var("len"))),
        vec![
            Formula::Eq(Box::new(var("index")), Box::new(var("hi#s0_0_s2_0"))),
            Formula::Eq(Box::new(var("hi#s0_0_s2_0")), Box::new(Formula::Int(1))),
            Formula::Eq(Box::new(var("len")), Box::new(Formula::Int(0))),
        ],
    );
    let obligation = authority_test_native_obligation("bridge:loop-gap", 441, 441);
    let mut baseline_bindings = vec![test_binding_for_obligation(0, &vc, &obligation)];
    let (_, _, baseline_failed, _) = bridge_v1_ay_proofs_into_native_results(
        5000,
        None,
        std::slice::from_ref(&vc),
        &mut baseline_bindings,
        true,
        vec![(vc.clone(), bridge_test_unknown())],
    );
    assert_eq!(baseline_failed, 1, "the unprotected generic bridge really credits this SAT query");
    // Production preclassifies UnsupportedMir as Unknown in the second
    // carrier. The solver slice has no gap row; both carriers are required.
    let inventory = vec![vc.clone()];
    let classified = vec![(gap.clone(), bridge_test_unknown())];
    let scope =
        trust_vcgen::GenericRefutationScope::for_function(&function, &inventory, &classified);
    let mut bindings = vec![test_binding_for_obligation(0, &vc, &obligation), None];
    let original = serde_json::to_value(&vc).unwrap();
    let original_gap = serde_json::to_value(&classified[0]).unwrap();
    let (results, proved, failed, eligible) =
        super::bridge_v1_ay_proofs_into_native_results_with_scope(
            &scope,
            5000,
            trust_types::determinism::EffortScale::BUILTIN,
            None,
            &inventory,
            &mut bindings,
            &mut ClockStops::default(),
            true,
            vec![(vc.clone(), bridge_test_unknown()), classified[0].clone()],
            None,
        );
    assert_eq!((proved, failed, results.len()), (0, 0, 2));
    assert_eq!(serde_json::to_value(&results[0].0).unwrap(), original);
    assert_eq!(serde_json::to_value(&results[1]).unwrap(), original_gap);
    assert!(matches!(&results[0].1, VerificationResult::Unknown { reason, .. }
        if reason.starts_with(trust_vcgen::GENERIC_REFUTATION_HELD_PREFIX)));
    assert!(eligible.iter().all(Option::is_none));
    assert!(result_is_held_assert_refutation(&results[0].1), "no runtime-check tolerance");
    assert!(
        strict_l0_verification_failure(
            true,
            &results,
            &bindings,
            &[],
            None,
            &OpenDispatchRefutationWitnesses::default()
        )
        .is_some(),
        "original strict refusal remains"
    );
}

#[test]
fn v1_bridge_generic_hold_preserves_native_stops_and_strict_refusal() {
    use trust_types::determinism::StopCause;
    let (function, gap) = unresolved_loop_bridge_fixture();
    let var = |name: &str| Formula::Var(name.into(), Sort::Int);
    let vc = loop_bridge_query(
        Formula::Ge(Box::new(var("index")), Box::new(var("len"))),
        vec![
            Formula::Eq(Box::new(var("index")), Box::new(var("hi#s0_0_s2_0"))),
            Formula::Eq(Box::new(var("hi#s0_0_s2_0")), Box::new(Formula::Int(1))),
            Formula::Eq(Box::new(var("len")), Box::new(Formula::Int(0))),
        ],
    );
    let inventory = vec![vc.clone()];
    let classified = vec![(gap, bridge_test_unknown())];
    let scope =
        trust_vcgen::GenericRefutationScope::for_function(&function, &inventory, &classified);
    let obligation = authority_test_native_obligation("bridge:held-stop", 441, 441);
    let mut previous = StopCause::ALL
        .into_iter()
        .map(|cause| cause.unknown_result("native-held-stop", 17, "native search retained"))
        .collect::<Vec<_>>();
    previous.push(VerificationResult::Unknown {
        solver: "native-bare".into(),
        time_ms: 19,
        reason: "native cause unavailable".into(),
    });
    previous.push(VerificationResult::Timeout { solver: "native-timeout".into(), timeout_ms: 77 });
    for prior in previous {
        let cause = StopCause::of_result(&prior);
        let mut bindings = vec![test_binding_for_obligation(0, &vc, &obligation), None];
        let before = serde_json::to_value(&vc).unwrap();
        let (results, proved, failed, eligible) =
            bridge_v1_ay_proofs_into_native_results_with_scope(
                &scope,
                5000,
                trust_types::determinism::EffortScale::BUILTIN,
                None,
                &inventory,
                &mut bindings,
                &mut ClockStops::default(),
                true,
                vec![(vc.clone(), prior), classified[0].clone()],
                None,
            );
        assert_eq!((proved, failed), (0, 0));
        assert_eq!(serde_json::to_value(&results[0].0).unwrap(), before);
        assert_eq!(StopCause::of_result(&results[0].1), cause);
        assert!(result_is_held_assert_refutation(&results[0].1));
        assert!(result_is_held_generic_refutation(&results[0].1));
        assert!(eligible.iter().all(Option::is_none));
        assert!(
            strict_l0_verification_failure(
                true,
                &results,
                &bindings,
                &[],
                None,
                &OpenDispatchRefutationWitnesses::default()
            )
            .is_some()
        );
    }
}

#[test]
fn v1_bridge_unresolved_loop_scope_preserves_independent_sat_and_unsat() {
    let (function, gap) = unresolved_loop_bridge_fixture();
    let var = |name: &str| Formula::Var(name.into(), Sort::Int);
    for (query, expected_failed, expected_proved) in [
        (loop_bridge_query(Formula::Ge(Box::new(var("len")), Box::new(var("len"))), vec![]), 1, 0),
        (
            loop_bridge_query(
                Formula::Ge(Box::new(var("index")), Box::new(var("len"))),
                vec![
                    Formula::Eq(Box::new(var("index")), Box::new(Formula::Int(0))),
                    Formula::Eq(Box::new(var("len")), Box::new(Formula::Int(1))),
                ],
            ),
            0,
            1,
        ),
    ] {
        let inventory = vec![query.clone()];
        let classified = vec![(gap.clone(), bridge_test_unknown())];
        let scope =
            trust_vcgen::GenericRefutationScope::for_function(&function, &inventory, &classified);
        let obligation = authority_test_native_obligation("bridge:loop-control", 441, 441);
        let mut bindings = vec![test_binding_for_obligation(0, &query, &obligation), None];
        let original_gap = serde_json::to_value(&classified[0]).unwrap();
        let (results, proved, failed, _) =
            super::bridge_v1_ay_proofs_into_native_results_with_scope(
                &scope,
                5000,
                trust_types::determinism::EffortScale::BUILTIN,
                None,
                &inventory,
                &mut bindings,
                &mut ClockStops::default(),
                true,
                vec![(query.clone(), bridge_test_unknown()), classified[0].clone()],
                None,
            );
        assert_eq!((failed, proved), (expected_failed, expected_proved));
        assert_eq!(results.len(), 2);
        assert_eq!(serde_json::to_value(&results[1]).unwrap(), original_gap);
        assert_eq!(
            serde_json::to_value(&results[0].0).unwrap(),
            serde_json::to_value(&query).unwrap()
        );
    }
}

/// Trust: the value a DEFAULT session would hand
/// `verify_full_bundle_with_live_receipts` — `-Ztrust-verify-timeout-ms`'s
/// default (compiler/rustc_session/src/options.rs:3378), which production reaches
/// through `vc_timeout_ms(tcx.sess)`. The tests below assert DISPATCH and RECEIPT
/// behaviour, not timeout behaviour, so they take the default rather than inventing
/// a number: a test-only timeout that drifts from the shipped default would quietly
/// stop exercising the configuration users actually run.
const SESSION_DEFAULT_VC_TIMEOUT_MS: u64 = 5_000;

/// These carrier fixtures have no compiler `Session`, and therefore no
/// session-owned panic-freedom grounding inventory. Keep that absence explicit
/// while exercising the same validation core as production.
fn native_proved_authority_validation_failures(
    result: Option<&trust_verifier_api::VerificationRunResult>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Vec<String> {
    native_proved_authority_validation_failures_with_grounding_lookup(
        result,
        results,
        result_bindings,
        proof_authorities,
        |_| None,
    )
}

#[test]
fn native_authority_integrity_refusal_preserves_the_validator_defect() {
    let obligation = authority_test_native_obligation("authority:integrity-diagnostic", 64, 64);
    let mut run = authority_test_strict_native_run(obligation);
    run.validate_derived_state().expect("the unmodified fixture is canonical");
    run.summary.proved += 1;
    let defect = run.validate_derived_state().expect_err("the forged count must be rejected");
    assert!(defect.contains("summary"));

    let failures = native_proved_authority_validation_failures(Some(&run), &[], &[], &[]);
    assert_eq!(failures.len(), 1);
    assert!(failures[0].starts_with("native run derived state is invalid: "));
    assert!(failures[0].contains(&defect), "the compiler must preserve the validator's reason");
}

#[test]
fn native_authority_carrier_refusal_identifies_the_skewed_inventory() {
    let obligation = authority_test_native_obligation("authority:carrier-diagnostic", 65, 65);
    let run = authority_test_strict_native_run(obligation);
    run.validate_derived_state().expect("the native run is canonical");
    let results = vec![(test_vc(65), authority_test_proved())];

    for (binding_count, authority_count) in [(0, 1), (1, 0), (2, 1)] {
        let bindings = std::iter::repeat_with(|| None).take(binding_count).collect::<Vec<_>>();
        let authorities = std::iter::repeat_with(|| None).take(authority_count).collect::<Vec<_>>();
        let failures = native_proved_authority_validation_failures(
            Some(&run),
            &results,
            &bindings,
            &authorities,
        );
        assert_eq!(failures.len(), 1);
        assert!(failures[0].contains("not row-aligned"));
        assert!(failures[0].contains("results=1"));
        assert!(failures[0].contains(&format!("bindings={binding_count}")));
        assert!(failures[0].contains(&format!("authorities={authority_count}")));
    }
}

#[test]
fn r1_synthetic_substitution_resolves_exact_acyclic_chain() {
    let substitutions = vec![
        (
            "_3".to_string(),
            Formula::Add(
                Box::new(Formula::Var("_4".to_string(), Sort::Int)),
                Box::new(Formula::Int(1)),
            ),
        ),
        ("_4".to_string(), Formula::Var("x".to_string(), Sort::Int)),
    ];
    let input =
        Formula::Eq(Box::new(Formula::Var("_3".to_string(), Sort::Int)), Box::new(Formula::Int(2)));
    let expected = Formula::Eq(
        Box::new(Formula::Add(
            Box::new(Formula::Var("x".to_string(), Sort::Int)),
            Box::new(Formula::Int(1)),
        )),
        Box::new(Formula::Int(2)),
    );

    assert_eq!(resolve_r1_synthetic_substitutions(&input, &substitutions), Some(expected));
}

#[test]
fn r1_synthetic_substitution_consumers_preserve_valid_formula_parity() {
    let int_var = |name: &str| Formula::Var(name.to_string(), Sort::Int);
    let violation = Formula::And(vec![
        Formula::Eq(Box::new(int_var("_3")), Box::new(int_var("i"))),
        Formula::Lt(Box::new(int_var("_3")), Box::new(int_var("n"))),
        Formula::Ge(Box::new(int_var("_3")), Box::new(int_var("arr__slice_len"))),
    ]);

    assert_eq!(
        simplify_violation_negation(&violation),
        Some(Formula::Or(vec![
            Formula::Ge(Box::new(int_var("i")), Box::new(int_var("n"))),
            Formula::Lt(Box::new(int_var("i")), Box::new(int_var("arr__slice_len")),),
        ])),
    );
    assert_eq!(
        synthesize_loop_bound_precondition(&violation),
        Some(Formula::Le(Box::new(int_var("n")), Box::new(int_var("arr__slice_len")),)),
    );
}

#[test]
fn r1_synthetic_substitution_cycle_fails_closed_in_both_consumers() {
    let mut conjuncts = vec![
        Formula::Eq(
            Box::new(Formula::Var("_3".to_string(), Sort::Int)),
            Box::new(Formula::Add(
                Box::new(Formula::Var("_4".to_string(), Sort::Int)),
                Box::new(Formula::Var("_4".to_string(), Sort::Int)),
            )),
        ),
        Formula::Eq(
            Box::new(Formula::Var("_4".to_string(), Sort::Int)),
            Box::new(Formula::Add(
                Box::new(Formula::Var("_3".to_string(), Sort::Int)),
                Box::new(Formula::Var("_3".to_string(), Sort::Int)),
            )),
        ),
        Formula::Lt(
            Box::new(Formula::Var("_3".to_string(), Sort::Int)),
            Box::new(Formula::Var("n".to_string(), Sort::Int)),
        ),
        Formula::Ge(
            Box::new(Formula::Var("_3".to_string(), Sort::Int)),
            Box::new(Formula::Var("arr__slice_len".to_string(), Sort::Int)),
        ),
    ];
    // The former fixed-point loop used the total binding count as its round
    // count, so irrelevant bindings made the two-node cycle expand until OOM.
    for index in 0..128 {
        conjuncts.push(Formula::Eq(
            Box::new(Formula::Var(format!("_irrelevant_{index}"), Sort::Int)),
            Box::new(Formula::Int(index)),
        ));
    }
    let violation = Formula::And(conjuncts);

    assert_eq!(simplify_violation_negation(&violation), None);
    assert_eq!(synthesize_loop_bound_precondition(&violation), None);
}

#[test]
fn r1_synthetic_substitution_direct_cycle_and_irrelevant_cycle_are_distinct() {
    let self_cycle = vec![("_0".to_string(), Formula::Var("_0".to_string(), Sort::Int))];
    assert_eq!(
        resolve_r1_synthetic_substitutions(&Formula::Var("_0".to_string(), Sort::Int), &self_cycle,),
        None,
    );

    assert_eq!(
        resolve_r1_synthetic_substitutions(&Formula::Var("x".to_string(), Sort::Int), &self_cycle,),
        Some(Formula::Var("x".to_string(), Sort::Int)),
        "an unreachable cycle must not poison an unrelated core formula",
    );
}

#[test]
fn r1_synthetic_substitution_duplicate_binding_keeps_first() {
    let substitutions =
        vec![("_0".to_string(), Formula::Int(1)), ("_0".to_string(), Formula::Int(2))];
    assert_eq!(
        resolve_r1_synthetic_substitutions(
            &Formula::Var("_0".to_string(), Sort::Int),
            &substitutions,
        ),
        Some(Formula::Int(1)),
    );
}

#[test]
fn r1_synthetic_substitution_depth_boundary_is_exact() {
    fn chain(last: usize) -> Vec<(String, Formula)> {
        let mut substitutions = (0..last)
            .map(|index| (format!("_{index}"), Formula::Var(format!("_{}", index + 1), Sort::Int)))
            .collect::<Vec<_>>();
        substitutions.push((format!("_{last}"), Formula::Var("x".to_string(), Sort::Int)));
        substitutions
    }

    let input = Formula::Var("_0".to_string(), Sort::Int);
    assert_eq!(
        resolve_r1_synthetic_substitutions(&input, &chain(R1_SUBSTITUTION_DEPTH_BUDGET - 1),),
        Some(Formula::Var("x".to_string(), Sort::Int)),
    );
    assert_eq!(
        resolve_r1_synthetic_substitutions(&input, &chain(R1_SUBSTITUTION_DEPTH_BUDGET)),
        None,
    );
}

#[test]
fn r1_synthetic_substitution_batch_shares_one_budget() {
    let first = Formula::Bool(true);
    let second = Formula::Bool(false);
    let formulas = [&first, &second];
    let mut exact = R1SubstitutionBudget::with_work(4);
    assert_eq!(
        resolve_r1_synthetic_substitution_batch(&formulas, &[], &mut exact),
        Some(vec![first.clone(), second.clone()]),
    );

    let mut one_short = R1SubstitutionBudget::with_work(3);
    assert_eq!(
        resolve_r1_synthetic_substitution_batch(&formulas, &[], &mut one_short),
        None,
        "preflight and output reconstruction must share one batch budget",
    );
}

#[test]
fn r1_synthetic_substitution_honors_and_restores_ambient_deadline() {
    let input = Formula::Bool(true);
    let formulas = [&input];

    {
        let _budget = trust_types::verify_budget::VerifyBudgetGuard::install(
            Some(std::time::Instant::now()),
            u64::MAX,
        );
        assert_eq!(
            resolve_r1_synthetic_substitution_batch(
                &formulas,
                &[],
                &mut R1SubstitutionBudget::new(),
            ),
            None,
            "expired preprocessing must fail closed before cloning the candidate",
        );
    }

    assert_eq!(
        resolve_r1_synthetic_substitution_batch(&formulas, &[], &mut R1SubstitutionBudget::new(),),
        Some(vec![input.clone()]),
        "the RAII deadline scope must restore the prior ambient budget",
    );
}

#[test]
fn r1_synthetic_substitution_rejects_oversized_input_before_clone() {
    let oversized = Formula::And(vec![Formula::Bool(true); R1_SUBSTITUTION_WORK_BUDGET]);
    assert_eq!(resolve_r1_synthetic_substitutions(&oversized, &[]), None);
}

#[test]
fn r1_synthetic_substitution_exponential_acyclic_chain_hits_node_budget() {
    let mut substitutions = Vec::new();
    for index in 0..32 {
        let next = Formula::Var(format!("_{}", index + 1), Sort::Int);
        substitutions
            .push((format!("_{index}"), Formula::Add(Box::new(next.clone()), Box::new(next))));
    }
    substitutions.push(("_32".to_string(), Formula::Var("x".to_string(), Sort::Int)));

    assert_eq!(
        resolve_r1_synthetic_substitutions(
            &Formula::Var("_0".to_string(), Sort::Int),
            &substitutions,
        ),
        None,
        "an acyclic substitution whose materialized tree is exponential must fail closed"
    );
}

#[test]
fn r1_synthetic_substitution_rejects_deep_or_oversized_metadata_before_clone() {
    let mut deep_sort = Sort::Int;
    for _ in 0..=R1_SUBSTITUTION_DEPTH_BUDGET {
        deep_sort = Sort::Array(Box::new(deep_sort), Box::new(Sort::Int));
    }
    assert_eq!(
        resolve_r1_synthetic_substitutions(&Formula::Var("x".to_string(), deep_sort), &[],),
        None,
        "Sort recursion is part of the derive-Clone depth bound",
    );

    assert_eq!(
        resolve_r1_synthetic_substitutions(
            &Formula::Var("x".repeat(R1_SUBSTITUTION_WORK_BUDGET), Sort::Int),
            &[],
        ),
        None,
        "retained metadata bytes share the structural work budget",
    );
}

#[test]
fn r1_synthetic_substitution_charges_metadata_for_every_materialized_occurrence() {
    let replacement = Formula::Var("x".repeat(20_000), Sort::Int);
    let input = Formula::And(vec![Formula::Var("_0".to_string(), Sort::Int); 4]);
    assert_eq!(
        resolve_r1_synthetic_substitutions(&input, &[("_0".to_string(), replacement)]),
        None,
        "one preflight must not license unbounded repeated metadata clones",
    );
}

#[test]
fn r1_candidate_collection_charges_lhs_and_type_range_names_before_scans() {
    let giant_synthetic = Formula::Var(format!("{}#", "x".repeat(1_000)), Sort::Int);
    let substitution = Formula::Eq(Box::new(giant_synthetic), Box::new(Formula::Int(0)));
    let violation = Formula::And(vec![substitution, Formula::Bool(true)]);
    assert!(
        collect_r1_candidate_parts(&violation, &mut R1SubstitutionBudget::with_work(128)).is_none(),
        "substitution-LHS classification must charge the retained name bytes",
    );

    let giant_key = format!("{}#", "k".repeat(1_000));
    let input = Formula::Bool(true);
    let replacement = Formula::Bool(false);
    assert_eq!(
        resolve_r1_synthetic_substitution_batch(
            &[&input],
            &[(giant_key.as_str(), &replacement)],
            &mut R1SubstitutionBudget::with_work(128),
        ),
        None,
        "helper-supplied substitution keys must be charged before hash-map insertion",
    );

    let giant_name = "range_name".repeat(100);
    let var = || Formula::Var(giant_name.clone(), Sort::Int);
    let type_range = Formula::And(vec![
        Formula::Ge(Box::new(var()), Box::new(Formula::Int(0))),
        Formula::Le(Box::new(var()), Box::new(Formula::Int(255))),
    ]);
    assert!(
        collect_r1_candidate_parts(&type_range, &mut R1SubstitutionBudget::with_work(128))
            .is_none(),
        "the two-bound fast path must charge names before comparing them",
    );
}

#[test]
fn r1_loop_bound_pair_scan_shares_the_candidate_work_budget() {
    let int_var = |name: &str| Formula::Var(name.to_string(), Sort::Int);
    let mut conjuncts = (0..8)
        .map(|index| {
            Formula::Ge(Box::new(int_var(&format!("i{index}"))), Box::new(int_var("a__slice_len")))
        })
        .collect::<Vec<_>>();
    conjuncts.push(Formula::Lt(Box::new(int_var("i7")), Box::new(int_var("n"))));
    let violation = Formula::And(conjuncts);
    let expected = Formula::Le(Box::new(int_var("n")), Box::new(int_var("a__slice_len")));

    assert_eq!(
        synthesize_loop_bound_precondition_with_budget(
            &violation,
            R1SubstitutionBudget::with_work(1_000),
        ),
        Some(expected),
    );
    assert_eq!(
        synthesize_loop_bound_precondition_with_budget(
            &violation,
            R1SubstitutionBudget::with_work(420),
        ),
        None,
        "the quadratic match phase must stop when the shared budget is exhausted",
    );
}

#[test]
fn exact_liskov_identity_is_structural_and_mutations_fail_closed() {
    let trait_contract = trust_vcgen::TraitContract {
        trait_name: "demo::Widget".to_string(),
        method: "rank".to_string(),
        parameter_names: vec!["self".to_string(), "x".to_string(), "y".to_string()],
        preconditions: Vec::new(),
        postconditions: vec![Formula::Ge(
            Box::new(Formula::Var("x".to_string(), Sort::Int)),
            Box::new(Formula::Int(0)),
        )],
    };
    let exact_impl = trust_vcgen::ImplContract {
        impl_type: "demo::Button".to_string(),
        method: "rank".to_string(),
        parameter_names: trait_contract.parameter_names.clone(),
        preconditions: Vec::new(),
        postconditions: trait_contract.postconditions.clone(),
    };
    assert!(trust_vcgen::liskov_contracts_have_exact_identity(&trait_contract, &exact_impl,));

    let mut changed_postcondition = exact_impl.clone();
    changed_postcondition.postconditions = vec![Formula::Bool(false)];
    assert!(!trust_vcgen::liskov_contracts_have_exact_identity(
        &trait_contract,
        &changed_postcondition,
    ));

    let mut changed_precondition = exact_impl.clone();
    changed_precondition.preconditions = vec![Formula::Bool(true)];
    assert!(!trust_vcgen::liskov_contracts_have_exact_identity(
        &trait_contract,
        &changed_precondition,
    ));

    let mut swapped_binders = exact_impl.clone();
    swapped_binders.parameter_names = vec!["self".to_string(), "y".to_string(), "x".to_string()];
    assert!(
        !trust_vcgen::liskov_contracts_have_exact_identity(&trait_contract, &swapped_binders),
        "the same formula spelling denotes a different argument after binder reordering"
    );
    let mismatch_vcs = trust_vcgen::verify_liskov(&trait_contract, &swapped_binders);
    assert_eq!(mismatch_vcs.len(), 1);
    assert_eq!(mismatch_vcs[0].formula, Formula::Bool(true));
}

#[test]
fn dyn_summary_in_progress_guard_restores_after_unwind() {
    let def_id = rustc_span::def_id::CRATE_DEF_ID.to_def_id();
    DYN_SUMMARY_IN_PROGRESS.with(|in_progress| {
        assert!(!in_progress.borrow().contains(&def_id));
    });

    let unwind = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _guard = DynSummaryInProgressGuard::enter(def_id).expect("first frame owns entry");
        DYN_SUMMARY_IN_PROGRESS.with(|in_progress| {
            assert!(in_progress.borrow().contains(&def_id));
        });
        assert!(
            DynSummaryInProgressGuard::enter(def_id).is_none(),
            "a nested frame must not remove the outer frame's entry"
        );
        panic!("exercise unwind cleanup");
    }));
    assert!(unwind.is_err());

    DYN_SUMMARY_IN_PROGRESS.with(|in_progress| {
        assert!(!in_progress.borrow().contains(&def_id));
    });
    let guard = DynSummaryInProgressGuard::enter(def_id)
        .expect("a later verification frame must be able to re-enter");
    drop(guard);
    DYN_SUMMARY_IN_PROGRESS.with(|in_progress| {
        assert!(!in_progress.borrow().contains(&def_id));
    });
}

fn private_proof_store_test_root(label: &str) -> PathBuf {
    use std::sync::atomic::{AtomicU64, Ordering};

    static SEQUENCE: AtomicU64 = AtomicU64::new(0);
    let path = std::env::temp_dir().join(format!(
        "trustc-proof-store-{label}-{}-{}",
        std::process::id(),
        SEQUENCE.fetch_add(1, Ordering::Relaxed)
    ));
    std::fs::create_dir(&path).expect("create proof store test root");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;

        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o700))
            .expect("make proof store test root private");
    }
    path.canonicalize().expect("canonical proof store test root")
}

#[test]
fn proof_artifact_store_requires_owner_private_root_and_components() {
    let root = private_proof_store_test_root("private");
    let (_canonical_root, store) =
        prepare_private_proof_artifact_store(&root).expect("private store should be accepted");
    assert_eq!(store.file_name(), Some(std::ffi::OsStr::new("sha256")));
    assert_eq!(
        store.parent().and_then(Path::file_name),
        Some(std::ffi::OsStr::new(trust_types::TRANSPORT_ARTIFACT_STORE_DIRECTORY))
    );
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;

        assert_eq!(
            std::fs::metadata(&store).expect("store metadata").permissions().mode() & 0o777,
            0o700
        );
        assert_eq!(
            std::fs::metadata(store.parent().expect("store parent"))
                .expect("store parent metadata")
                .permissions()
                .mode()
                & 0o777,
            0o700
        );
    }
    std::fs::remove_dir_all(root).expect("remove proof store test root");
}

#[cfg(unix)]
#[test]
fn proof_artifact_store_rejects_non_private_root() {
    use std::os::unix::fs::PermissionsExt as _;

    let root = private_proof_store_test_root("public");
    std::fs::set_permissions(&root, std::fs::Permissions::from_mode(0o755))
        .expect("make root public");
    let error = prepare_private_proof_artifact_store(&root)
        .expect_err("world-readable proof root must fail closed");
    assert!(error.contains("mode 0700"), "unexpected error: {error}");
    std::fs::remove_dir_all(root).expect("remove proof store test root");
}

#[cfg(unix)]
#[test]
fn proof_artifact_store_rejects_symlinked_fixed_components() {
    use std::os::unix::fs::{PermissionsExt as _, symlink};

    for symlink_sha256 in [false, true] {
        let root =
            private_proof_store_test_root(if symlink_sha256 { "sha-link" } else { "store-link" });
        let outside = private_proof_store_test_root(if symlink_sha256 {
            "sha-outside"
        } else {
            "store-outside"
        });
        let store_root = root.join(trust_types::TRANSPORT_ARTIFACT_STORE_DIRECTORY);
        if symlink_sha256 {
            std::fs::create_dir(&store_root).expect("create real store component");
            std::fs::set_permissions(&store_root, std::fs::Permissions::from_mode(0o700))
                .expect("make real store component private");
            symlink(&outside, store_root.join("sha256")).expect("symlink sha256 component");
        } else {
            symlink(&outside, &store_root).expect("symlink store component");
        }

        let error = prepare_private_proof_artifact_store(&root)
            .expect_err("symlinked proof store component must fail closed");
        assert!(
            error.contains("non-symlink") || error.contains("symlink"),
            "unexpected error: {error}"
        );
        assert!(
            std::fs::read_dir(&outside).expect("read outside directory").next().is_none(),
            "rejected proof store traversal must not materialize outside its authority root"
        );
        std::fs::remove_dir_all(root).expect("remove proof store test root");
        std::fs::remove_dir_all(outside).expect("remove outside proof store root");
    }
}

/// `survey` names the historical boolean these tests were written against.
/// `TrustVerifyPolicy` now carries the selected `-Ztrust-policy` instead, and
/// `survey` was exactly "advisory rather than strict", so it maps onto that.
fn test_policy(survey: bool, include_dependencies: bool) -> TrustVerifyPolicy {
    TrustVerifyPolicy {
        include_dependencies,
        policy: if survey {
            rustc_session::config::TrustPolicy::Advisory
        } else {
            rustc_session::config::TrustPolicy::Strict
        },
    }
}

fn test_vc(line_start: u32) -> VerificationCondition {
    VerificationCondition {
        kind: VcKind::DivisionByZero,
        function: trust_types::Symbol::intern("test::f"),
        location: trust_types::SourceSpan {
            file: "test.rs".to_string(),
            line_start,
            col_start: 1,
            line_end: line_start,
            col_end: 5,
        },
        formula: trust_types::Formula::Bool(true),
        contract_metadata: None,
        obligation: None,
    }
}

/// Trust (regression — positive-witness ICE / nullified sep discharges):
/// `refute_unsafe_demand_findings` selects the `[unsafe` FAMILY by marker, but
/// the refutation criterion is "unprovable by construction". A ground
/// `Bool(true)` demand finding is still forced `Failed` from any non-`Failed`
/// verdict; a genuinely solvable separation-logic obligation that a solver
/// PROVED — `[unsafe:sep:deref] null check` (`ptr == 0`, discharged by
/// `SepEngine::discharge_stack_good`) and the `[unsafe:sep:backing]` ESTABLISH
/// obligation (`alloc_size < len`, the `#[trust::backing]` certificate's whole
/// point) — keeps its proof. Overriding those both destroyed real proofs and
/// drove a genuine `Proved` into `structural_refutation_solver_label`, whose
/// positive-witness `debug_assert!` then ICEd trustc on
/// `let x = 7; let p = &x as *const i32; unsafe { *p }`.
#[test]
fn unsafe_demand_refutation_spares_genuinely_discharged_separation_obligations() {
    let unsafe_vc = |message: &str, formula: Formula| {
        let mut vc = test_vc(11);
        vc.kind = VcKind::Assertion { message: message.to_string() };
        vc.formula = formula;
        vc
    };
    let proved = || VerificationResult::Proved {
        solver: "ay-in-process".into(),
        time_ms: 0,
        strength: ProofStrength::smt_unsat(),
        proof_certificate: None,
        solver_warnings: None,
        native_proof_envelope: None,
    };
    let ptr = Formula::Var("ptr_raw_2".to_string(), Sort::Int);
    let mut results = vec![
        // Unprovable by construction: a ground `Bool(true)` violation. Still
        // refuted from a non-`Failed` verdict — the original surviving-mutant fix.
        (
            unsafe_vc("[unsafe] missing SAFETY comment on unsafe block", Formula::Bool(true)),
            VerificationResult::Unknown {
                solver: "trust-full-verifier".into(),
                time_ms: 0,
                reason: "no model".to_string(),
            },
        ),
        // Same family, a different non-`Failed` verdict: still refuted. (A
        // `Proved` on a ground `Bool(true)` violation is deliberately NOT
        // exercised here — that case IS the positive-witness breach and
        // `structural_refutation_solver_label` debug-asserts on it by design. A
        // `Proved` on the `Bool(false)` placeholder is NOT a breach — see
        // `unsafe_demand_refutation_refutes_placeholder_proofs_for_vacuity`.)
        (
            unsafe_vc(
                "[unsafe:unmodeled-call] call to `c` (unsafe fn) is not covered",
                Formula::Bool(true),
            ),
            VerificationResult::Timeout { solver: "trust-mc".into(), timeout_ms: 7 },
        ),
        // A REAL obligation a real solver discharged: `ptr == 0` refuted by the
        // stack-good non-null fact. Must keep its proof.
        (
            unsafe_vc(
                "[unsafe:sep:deref] null check for *raw_2",
                Formula::And(vec![
                    Formula::Gt(Box::new(ptr.clone()), Box::new(Formula::Int(0))),
                    Formula::Eq(Box::new(ptr), Box::new(Formula::Int(0))),
                ]),
            ),
            proved(),
        ),
        // The `#[trust::backing]` ESTABLISH obligation `alloc_size < len`.
        (
            unsafe_vc(
                "[unsafe:sep:backing] field #0 must be valid for field #1 \
                 bytes at construction in map",
                Formula::Lt(
                    Box::new(Formula::Var("len".to_string(), Sort::Int)),
                    Box::new(Formula::Var("len".to_string(), Sort::Int)),
                ),
            ),
            proved(),
        ),
        // A solvable sep obligation nothing discharged still fails closed.
        (
            unsafe_vc(
                "[unsafe:sep:deref] alignment check for *raw_2",
                Formula::Var("misaligned".to_string(), Sort::Bool),
            ),
            VerificationResult::Unknown {
                solver: "trust-full-verifier".into(),
                time_ms: 0,
                reason: "nonlinear".to_string(),
            },
        ),
    ];

    refute_unsafe_demand_findings(&mut results);

    let solver_of = |index: usize| match &results[index].1 {
        VerificationResult::Failed { solver, .. } => format!("failed:{solver}"),
        VerificationResult::Proved { solver, .. } => format!("proved:{solver}"),
        other => format!("other:{other:?}"),
    };
    assert_eq!(
        solver_of(0),
        "failed:structural-unsafe-demand-finding",
        "a ground unprovable demand finding must still be refuted"
    );
    assert_eq!(
        solver_of(1),
        "failed:structural-unsafe-demand-finding",
        "every non-`Failed` verdict on a ground finding is still refuted"
    );
    assert!(
        matches!(&results[1].1, VerificationResult::Failed { time_ms: 7, .. }),
        "the overridden verdict's elapsed time is carried onto the refutation"
    );
    assert_eq!(
        solver_of(2),
        "proved:ay-in-process",
        "a discharged null check carries a real formula and must keep its proof"
    );
    assert_eq!(
        solver_of(3),
        "proved:ay-in-process",
        "the backing ESTABLISH obligation is designed to be discharged"
    );
    assert_eq!(
        solver_of(4),
        "failed:structural-unsafe-demand-finding",
        "an undischarged solvable unsafe obligation still fails closed"
    );
    // Trust (honest label): every row the pass forced is a fail-closed
    // failure with NO counterexample, and every report surface reads it as
    // such; the two proofs it spared have no failure basis at all.
    for index in [0, 1, 4] {
        assert_eq!(
            trust_types::FailureBasis::of_result(&results[index].1),
            Some(trust_types::FailureBasis::UnprovedFailClosed),
            "row {index} was forced Failed without a refutation"
        );
    }
    for index in [2, 3] {
        assert_eq!(trust_types::FailureBasis::of_result(&results[index].1), None);
    }
}

/// Trust (vacuous-placeholder-proof arm): `Bool(false)` — the full-lane
/// reconstruction placeholder (`legacy_vc_from_api_obligation` falls back to it
/// when the obligation's payload formula cannot be reconstructed) — is UNSAT,
/// so a sound solver legitimately returns `Proved` for it. That proof is
/// vacuous about the original obligation, and the vacuity gate
/// (`apply_vacuity_gate_with_authority`) runs only downstream of
/// `refute_unsafe_demand_findings`, so the pass must refuse it itself: forced
/// `Failed` under the dedicated placeholder label, WITHOUT routing through
/// `structural_refutation_solver_label` — whose positive-witness
/// `debug_assert!` is an invariant of the `Bool(true)`
/// unprovable-by-construction class only. On the unrepaired code this row
/// trips that assertion (ICE in a debug build) and, in a release build, is
/// mislabeled `…-over-unwitnessed-proof:…`.
#[test]
fn unsafe_demand_refutation_refutes_placeholder_proofs_for_vacuity() {
    let mut vc = test_vc(13);
    // The reconstructed native-transport shape: re-kinded to the hardened
    // unsafe-operation family, payload lost to the `Bool(false)` placeholder.
    vc.kind = VcKind::HardenedBoundary {
        category: trust_types::HardenedVcCategory::UnsafeOperation,
        callee: "map".to_string(),
        detail: "[unsafe:sep:heap] out-of-bounds heap read".to_string(),
    };
    vc.formula = Formula::Bool(false);
    let mut results = vec![(
        vc,
        VerificationResult::Proved {
            solver: "ay-in-process".into(),
            time_ms: 3,
            strength: ProofStrength::smt_unsat(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        },
    )];

    refute_unsafe_demand_findings(&mut results);

    match &results[0].1 {
        VerificationResult::Failed { solver, time_ms, counterexample } => {
            assert_eq!(
                format!("{solver}"),
                "structural-unsafe-demand-finding-over-vacuous-placeholder-proof:ay-in-process",
                "a placeholder proof is refuted for vacuity, not as a witness breach"
            );
            assert_eq!(*time_ms, 3, "the vacuous proof's elapsed time is carried");
            assert!(counterexample.is_none(), "no counterexample can be minted for a placeholder");
        }
        other => panic!("a `Proved` placeholder row must be forced Failed, got {other:?}"),
    }
    // Trust (honest label): refused for vacuity, not refuted.
    assert_eq!(
        trust_types::FailureBasis::of_result(&results[0].1),
        Some(trust_types::FailureBasis::UnprovedFailClosed)
    );
    assert_eq!(
        verification_result_state_label(&results[0].1),
        "FAILED (unproved, no counterexample; failed closed)"
    );
}

/// Trust (honest label, 2026-10-02): the per-row state word never calls a
/// fail-closed unsafe-demand row "refuted", while a backend refutation keeps
/// its word. The outcome is `Failed` in both — only the description differs.
#[test]
fn unsafe_demand_fail_closed_rows_are_not_labelled_refuted() {
    let mut vc = test_vc(17);
    vc.kind = VcKind::Assertion {
        message: "[unsafe:unmodeled-call] call to `c` (unsafe fn) is not covered".to_string(),
    };
    vc.formula = Formula::Bool(true);
    let mut results = vec![(
        vc,
        VerificationResult::Unknown {
            solver: "trust-full-verifier".into(),
            time_ms: 0,
            reason: "native typed-TrustIr lowering did not complete".to_string(),
        },
    )];
    refute_unsafe_demand_findings(&mut results);
    assert!(results[0].1.is_failed(), "the row must still FAIL the gate");
    assert_eq!(
        verification_result_state_label(&results[0].1),
        "FAILED (unproved, no counterexample; failed closed)"
    );
    // CONTROL: a backend refutation keeps the historical word.
    let refuted =
        VerificationResult::Failed { solver: "ay".into(), time_ms: 0, counterexample: None };
    assert_eq!(verification_result_state_label(&refuted), "FAILED (refuted)");
}

#[test]
fn unsafe_demand_definite_violations_keep_reading_as_refuted() {
    // A double free / use-after-free the separation model established on every
    // reaching execution is a FOUND violation: when the native lane returns
    // Unknown (or an unwitnessed Proved) and this pass forces it Failed, it
    // must not read "unproved, no counterexample" like an unmodelled call.
    let definite = |message: &str| {
        let mut vc = test_vc(18);
        vc.kind = VcKind::Assertion { message: message.to_string() };
        vc.formula = Formula::Bool(true);
        vc
    };
    let unknown = || VerificationResult::Unknown {
        solver: "trust-full-verifier".into(),
        time_ms: 0,
        reason: "native typed-TrustIr lowering did not complete".to_string(),
    };
    let mut reconstructed = test_vc(19);
    reconstructed.kind = VcKind::HardenedBoundary {
        category: trust_types::HardenedVcCategory::UnsafeOperation,
        callee: String::new(),
        detail: "[unsafe:sep:heap] use-after-free: write through freed pointer `p`".to_string(),
    };
    reconstructed.formula = Formula::Bool(false);
    let mut results = vec![
        (definite("[unsafe:sep:free] double-free of `arg_1` (prov#1) in append"), unknown()),
        (definite("[unsafe:sep:heap] use-after-free: read through freed pointer `p`"), unknown()),
        (
            reconstructed,
            VerificationResult::Proved {
                solver: "ay-in-process".into(),
                time_ms: 0,
                strength: trust_types::ProofStrength::smt_unsat(),
                proof_certificate: None,
                solver_warnings: None,
                native_proof_envelope: None,
            },
        ),
        // CONTROL: a non-definite constant row in the same family stays fail-closed.
        (definite("[unsafe] missing SAFETY comment on unsafe block"), unknown()),
    ];
    refute_unsafe_demand_findings(&mut results);
    for (_, result) in &results {
        assert!(result.is_failed(), "every row must still FAIL the gate: {result:?}");
    }
    for (_, result) in &results[..3] {
        let VerificationResult::Failed { solver, counterexample, .. } = result else {
            unreachable!()
        };
        assert!(
            solver.as_str().starts_with(trust_types::UNSAFE_DEMAND_DEFINITE_SOLVER),
            "{solver}"
        );
        assert!(counterexample.is_none());
        assert_eq!(
            trust_types::FailureBasis::of_result(result),
            Some(trust_types::FailureBasis::Refuted)
        );
        assert_eq!(verification_result_state_label(result), "FAILED (refuted)");
    }
    assert_eq!(
        trust_types::FailureBasis::of_result(&results[3].1),
        Some(trust_types::FailureBasis::UnprovedFailClosed)
    );
}

#[test]
fn forced_allocation_after_backend_decline_is_an_explicit_structural_refutation() {
    // Trust: an interval decline on this structurally forced allocation must
    // become an ordinary Failed result, never reach the unwitnessed-Proved ICE.
    let int_var = |name: &str| Formula::Var(name.to_string(), Sort::Int);
    let a = int_var("a");
    let sum = Formula::Add(Box::new(a.clone()), Box::new(Formula::Int(1)));
    let count = int_var("count");
    let ceiling = Formula::Int(1 << 28);
    let mut vc = test_vc(8);
    vc.kind = VcKind::UnboundedAllocation {
        callee: "vec![value; count]".into(),
        count: "count".into(),
        detail: "forced allocation beside safe arithmetic sibling".to_string(),
    };
    vc.formula = Formula::And(vec![
        Formula::Ge(Box::new(a.clone()), Box::new(Formula::Int(0))),
        Formula::Le(Box::new(a), Box::new(Formula::Int(255))),
        Formula::Or(vec![
            Formula::Gt(Box::new(sum.clone()), Box::new(Formula::Int(i128::from(u32::MAX)))),
            Formula::Eq(Box::new(int_var("sum")), Box::new(sum)),
        ]),
        Formula::Eq(Box::new(count.clone()), Box::new(ceiling.clone())),
        Formula::Le(Box::new(count.clone()), Box::new(ceiling.clone())),
        Formula::Ge(Box::new(count), Box::new(ceiling)),
    ]);

    let mut results = vec![(
        vc,
        VerificationResult::Unknown {
            solver: "interval".into(),
            time_ms: 0,
            reason: "direct forced allocation cannot be discharged".to_string(),
        },
    )];
    refute_forced_unbounded_allocations(&mut results);

    let VerificationResult::Failed { solver, counterexample, .. } = &results[0].1 else {
        panic!("forced allocation must become an explicit failed verdict");
    };
    assert_eq!(solver.as_str(), "structural-forced-unbounded-allocation");
    assert!(counterexample.is_none());
}

/// An origin-inventory row an overflow `Assert` in `block` minted: its block, its site and
/// the row's tree.
fn assert_row(
    block: usize,
    vc: VerificationCondition,
) -> (usize, trust_vcgen::OriginSite, VerificationCondition) {
    (block, trust_vcgen::OriginSite::Assert, vc)
}

/// The origin table of `listed`. T3 L4 (C07): an inventory names each row by its id in
/// the body's context, so the rows are interned into a fresh context first, as the
/// consumed generation interns its own, and the table reads each one back for its key,
/// beside its eager row (`eager_rows_by_id`), as the consumed path does.
fn origins_of(
    listed: &[(usize, trust_vcgen::OriginSite, VerificationCondition)],
) -> OverflowCheckOrigins {
    let mut context = trust_types::vc_context::VcContext::new();
    let rows: Vec<trust_vcgen::OriginRow> = listed
        .iter()
        .map(|(block, site, vc)| trust_vcgen::OriginRow {
            block: trust_types::BlockId(*block),
            site: *site,
            vc: context.push_checked_row(vc).expect("a test context has room"),
        })
        .collect();
    let eager = eager_rows_by_id(&rows, listed.iter().map(|(_, _, vc)| vc));
    OverflowCheckOrigins::from_rows(&context, &eager, &rows)
        .expect("every listed row is a generated row")
}

/// Each origin's eager row by the id the origin names it by.
fn eager_rows_by_id<'vc>(
    rows: &[trust_vcgen::OriginRow],
    vcs: impl IntoIterator<Item = &'vc VerificationCondition>,
) -> FxHashMap<trust_types::vc_context::RowId, &'vc VerificationCondition> {
    rows.iter().map(|row| row.vc).zip(vcs).collect()
}

/// T3 L4 (C07): an origin that names a row the generation did not return (here, a row of
/// another context) means the inventory no longer lines up with the generation: no table,
/// so every check is kept.
#[test]
fn an_origin_naming_another_contexts_row_gives_no_table() {
    let vc = test_vc(15);
    let mut other = trust_types::vc_context::VcContext::new();
    let foreign = trust_vcgen::OriginRow {
        block: trust_types::BlockId(1),
        site: trust_vcgen::OriginSite::Assert,
        vc: other.push_checked_row(&vc).expect("a test context has room"),
    };
    let mut context = trust_types::vc_context::VcContext::new();
    let own = trust_vcgen::OriginRow {
        vc: context.push_checked_row(&vc).expect("a test context has room"),
        ..foreign
    };
    let eager = eager_rows_by_id(&[own], [&vc]);
    assert!(OverflowCheckOrigins::from_rows(&context, &eager, &[own]).is_some(), "control");
    assert!(OverflowCheckOrigins::from_rows(&context, &eager, &[own, foreign]).is_none());
}

/// T3 L4 (C07; L4-ORACLE-1): the eager row decides an origin's key. A row whose read-back
/// disagrees with its eager row (here, an id that names a different row of the context)
/// is keyed by its eager row, so the table is the one the eager rows give.
#[test]
fn an_origin_is_keyed_by_its_eager_row_when_the_read_back_disagrees() {
    let (named, read) = (test_vc(16), test_vc(17));
    let (named_key, read_key) = (
        RowKey::of(&named).expect("canonical payload"),
        RowKey::of(&read).expect("canonical payload"),
    );
    assert_ne!(named_key, read_key);
    let mut context = trust_types::vc_context::VcContext::new();
    let row = trust_vcgen::OriginRow {
        block: trust_types::BlockId(3),
        site: trust_vcgen::OriginSite::Assert,
        vc: context.push_checked_row(&read).expect("a test context has room"),
    };
    // The origin's id reads back as `read`, but the generation returned `named` under it.
    let eager = eager_rows_by_id(&[row], [&named]);
    let origins = OverflowCheckOrigins::from_rows(&context, &eager, &[row]).expect("a table");
    assert_eq!(origins.resolve(&named_key), Some(BasicBlock::from_usize(3)));
    assert_eq!(origins.resolve(&read_key), None, "the read-back never spells the key");
}

/// T3 C05: a key only an arithmetic STATEMENT produced never resolves, alone or beside
/// the same block's statement again; beside an Assert's row (in the same block or
/// another) it makes the key ambiguous. So a block that ends in `Assert(Overflow(Add))`
/// and also holds a plain integer `Add` cannot lose its Assert on the plain operation's
/// proof, which gate (5)'s op-only re-confirm would otherwise accept.
#[test]
fn overflow_check_origins_never_resolve_a_statement_row() {
    let statement =
        |block: usize, vc: VerificationCondition| (block, trust_vcgen::OriginSite::Statement, vc);
    let plain = test_vc(13);
    let checked = test_vc(14);
    let plain_key = RowKey::of(&plain).expect("canonical payload");
    let checked_key = RowKey::of(&checked).expect("canonical payload");
    assert_ne!(plain_key, checked_key);

    // One block, its statement's row and its Assert's row: only the Assert resolves.
    let origins = origins_of(&[
        statement(2, plain.clone()),
        statement(2, plain.clone()),
        assert_row(2, checked.clone()),
    ]);
    assert_eq!(origins.resolve(&plain_key), None);
    assert_eq!(
        origins.0.get(&plain_key),
        Some(&OverflowOrigin::Statement(BasicBlock::from_usize(2)))
    );
    assert_eq!(origins.audit_miss(&plain_key), "statement");
    assert_eq!(origins.resolve(&checked_key), Some(BasicBlock::from_usize(2)), "control");

    // A statement row with the Assert row's own key, in the same block or another.
    for block in [2, 5] {
        let origins =
            origins_of(&[assert_row(2, checked.clone()), statement(block, checked.clone())]);
        assert_eq!(origins.0.get(&checked_key), Some(&OverflowOrigin::Ambiguous), "bb{block}");
    }
}

#[test]
fn overflow_check_origins_preserve_repeated_rows_from_one_block() {
    let vc = test_vc(7);
    let canonical_vc = RowKey::of(&vc).expect("test VC must have a canonical payload");
    let origins = origins_of(&[assert_row(3, vc.clone()), assert_row(3, vc)]);

    assert_eq!(
        origins.resolve(&canonical_vc),
        Some(BasicBlock::from_usize(3)),
        "dedupe or repeated emission from one MIR block must retain its unique origin"
    );
}

#[test]
fn overflow_check_origins_fail_closed_for_identical_vcs_from_distinct_blocks() {
    let vc = test_vc(8);
    let canonical_vc = RowKey::of(&vc).expect("test VC must have a canonical payload");
    let origins = origins_of(&[assert_row(4, vc.clone()), assert_row(9, vc)]);

    assert_eq!(
        origins.resolve(&canonical_vc),
        None,
        "one exact VC shared by distinct MIR blocks must be ambiguous and ineligible for elision"
    );
    assert_eq!(origins.0.get(&canonical_vc), Some(&OverflowOrigin::Ambiguous));
}

/// WHY `trust_vcgen::OverflowOrigins::complete` RETURNS AN `Option` AND WHY A REFUSAL
/// MUST NOT DEGRADE TO "the rows I did manage to build".
///
/// `Ambiguous` is not a property of a row — it is a property of the ENUMERATION. The
/// test above proves the map fails closed when it is SHOWN both blocks; this one proves
/// the converse, which is the actual hazard: shown only a PREFIX, the identical input
/// mints `Unique` and licenses a rewrite. Nothing downstream can detect the difference,
/// because a short table and a complete one have the same type and the same shape.
///
/// So completeness has to be decided where it is known — inside the generation, which
/// is the only code that can tell "the walk ended" from "the walk was cut off" (T3 C05:
/// the consumed generation's own walk, no longer a replay) — and a refusal has to
/// arrive as `None`, never as a partial `Vec`.
#[test]
fn a_truncated_origin_enumeration_forges_a_unique_origin() {
    let vc = test_vc(11);
    let canonical_vc = RowKey::of(&vc).expect("test VC must have a canonical payload");
    let complete = [assert_row(4, vc.clone()), assert_row(9, vc.clone())];

    assert_eq!(
        origins_of(&complete).resolve(&canonical_vc),
        None,
        "the COMPLETE enumeration is ambiguous and must refuse"
    );
    assert_eq!(
        origins_of(&complete[..1]).resolve(&canonical_vc),
        Some(BasicBlock::from_usize(4)),
        "a PREFIX of that same enumeration mints Unique(bb4) — the elision seam would \
         then delete bb4's live overflow Assert on the authority of a proof that is \
         equally consistent with bb9. This is the failure a partial replay causes, and \
         it is why the replay refuses instead of truncating."
    );
}

/// The refusal path is INERT, not merely smaller: a generation with no complete origin
/// inventory becomes the default table, every `resolve` misses, and every overflow check
/// is kept.
#[test]
fn a_refused_origin_inventory_yields_an_inert_table() {
    let vc = test_vc(12);
    let canonical_vc = RowKey::of(&vc).expect("test VC must have a canonical payload");

    let refused = OverflowCheckOrigins::default();
    assert!(refused.0.is_empty());
    assert_eq!(
        refused.resolve(&canonical_vc),
        None,
        "a generation with no complete inventory must license no elision at all"
    );
}

#[test]
fn overflow_check_origins_key_by_exact_vc_not_source_span() {
    let true_vc = test_vc(9);
    let mut false_vc = true_vc.clone();
    false_vc.formula = Formula::Bool(false);
    let true_key = RowKey::of(&true_vc).expect("true test VC must have a canonical payload");
    let false_key = RowKey::of(&false_vc).expect("false test VC must have a canonical payload");
    assert_ne!(true_key, false_key, "the formula must participate in the origin identity");

    let origins = origins_of(&[assert_row(5, true_vc), assert_row(6, false_vc)]);

    assert_eq!(origins.resolve(&true_key), Some(BasicBlock::from_usize(5)));
    assert_eq!(origins.resolve(&false_key), Some(BasicBlock::from_usize(6)));
    assert_eq!(
        origins.resolve(&RowKey::unidentified_for_test("not a canonical verification condition")),
        None,
        "an absent exact identity must never inherit authority from a nearby source span"
    );
}

#[test]
fn original_vc_snapshot_uses_full_original_claim_and_final_row_identity() {
    // Trust: a native-selected BV formula is not the original typed Int VC.
    let base = test_vc(10);
    let target = "aarch64-apple-darwin;ptr64";
    let result = VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("snapshot-control"),
        time_ms: 0,
        reason: "no proof claim".into(),
    };
    let rows = build_transport_results_with_runtime_checks_for_target(
        true,
        Some(target),
        &[(base.clone(), result)],
        None,
        Some(&[None]),
        &FxHashMap::default(),
    );
    let row = &rows[0];
    let snapshot = row.original_vc_snapshot.as_ref().expect("original full VC persisted");
    let id = row.obligation_id.as_deref().expect("final row ID");
    let digest = row.claim_digest_sha256.as_deref().unwrap();
    let decoded = snapshot.decode_for_row(id, digest).unwrap();
    assert_eq!(canonical_exact_vc_payload(&decoded), canonical_exact_vc_payload(&base));
    assert!(snapshot.decode_for_row("different-request-row", digest).is_err());
    let mut substituted = snapshot.as_ref().clone();
    let mut replacement = base.clone();
    replacement.formula = trust_types::Formula::BitVec { value: 0, width: 64 };
    substituted.original_vc_json = serde_json::to_string(&replacement).unwrap();
    substituted.payload_sha256 =
        trust_types::stable_sha256_hex(substituted.original_vc_json.as_bytes());
    assert!(
        substituted.decode_for_row(id, digest).is_err(),
        "native BV cannot replace the original claim"
    );
    assert!(row.proof_evidence.is_none(), "snapshot does not manufacture proof evidence");
}

#[test]
fn exact_vc_claim_digest_binds_every_claim_dimension() {
    let base = test_vc(10);
    let canonical_payload =
        canonical_exact_vc_claim_payload(&base, false, None).expect("test VC claim must serialize");
    let base_digest =
        exact_vc_claim_digest_sha256(&base, false, None).expect("test VC must have a claim digest");
    assert_eq!(base_digest.len(), 64);
    let expected_digest =
        domain_length_bound_sha256_hex(EXACT_VC_CLAIM_DIGEST_DOMAIN, canonical_payload.as_bytes());
    assert_eq!(
        base_digest, expected_digest,
        "transport claim digest must use the exact canonical VC payload and protocol domain"
    );
    let payload: serde_json::Value =
        serde_json::from_str(&canonical_payload).expect("canonical claim payload must be JSON");
    assert_eq!(payload["schema"], EXACT_VC_CLAIM_SCHEMA_VERSION);
    assert_eq!(payload["semantics"]["overflow_checks"], false);
    assert!(payload["semantics"]["target"].is_null());
    assert!(payload.get("vc").is_some(), "schema wrapper must bind the VC (claim v3, C09w)");
    let unknown = VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("mock"),
        time_ms: 1,
        reason: "claim binding probe".to_string(),
    };
    let rows = build_transport_results_with_runtime_checks(
        false,
        &[(base.clone(), unknown)],
        None,
        Some(&[None]),
    );
    assert_eq!(
        rows[0].claim_digest_sha256.as_deref(),
        Some(base_digest.as_str()),
        "every real VC transport row must carry the exact claim digest"
    );
    assert_eq!(
        rows[0].typed_kind.as_deref(),
        Some(&base.kind),
        "every real VC transport row must carry the producer's exact typed kind"
    );
    assert_eq!(rows[0].kind, base.kind.transport_tag());
    assert_eq!(rows[0].description, base.kind.description());

    let assert_changed = |dimension: &str, changed: VerificationCondition| {
        assert_ne!(
            exact_vc_claim_digest_sha256(&changed, false, None).as_deref(),
            Some(base_digest.as_str()),
            "changing the VC {dimension} must change its transport claim digest"
        );
    };

    let mut changed = base.clone();
    changed.formula = trust_types::Formula::Bool(false);
    assert_changed("formula", changed);

    let mut changed = base.clone();
    changed.function = trust_types::Symbol::intern("test::different_function");
    assert_changed("function", changed);

    let mut changed = base.clone();
    changed.location.file = "different-source.rs".to_string();
    assert_changed("source", changed);

    let mut changed = base.clone();
    changed.kind = VcKind::RemainderByZero;
    assert_changed("kind", changed);

    let mut changed = base;
    changed.contract_metadata = Some(trust_types::ContractMetadata {
        has_requires: true,
        ..trust_types::ContractMetadata::default()
    });
    assert_changed("contract metadata", changed);

    assert_ne!(
        exact_vc_claim_digest_sha256(&test_vc(10), true, None).as_deref(),
        Some(base_digest.as_str()),
        "changing available compiler overflow semantics must change the claim digest"
    );
    let targeted_digest =
        exact_vc_claim_digest_sha256(&test_vc(10), false, Some("aarch64-apple-darwin;ptr64"));
    assert_ne!(
        targeted_digest.as_deref(),
        Some(base_digest.as_str()),
        "changing available compiler target identity must change the claim digest"
    );
}

#[test]
fn exact_vc_claim_digest_canonicalizes_state_machine_label_map_order() {
    let vc_with_label_order = |order: &[usize]| {
        let mut labels = trust_types::fx::FxHashMap::default();
        for state in order {
            labels.insert(*state, vec![format!("state_{state}"), format!("property_{state}")]);
        }
        VerificationCondition {
            kind: VcKind::Temporal {
                property: "AG !bad".to_string(),
                machine: Some(trust_types::StateMachineMetadata {
                    states: vec!["ready".to_string(), "running".to_string(), "bad".to_string()],
                    init_states: vec![0],
                    transitions: vec![(0, "start".to_string(), 1), (1, "fail".to_string(), 2)],
                    labels,
                }),
            },
            ..test_vc(10)
        }
    };

    let forward = vc_with_label_order(&[0, 1, 2]);
    let reverse = vc_with_label_order(&[2, 1, 0]);
    assert_eq!(
        exact_vc_key(&forward).map(|key| key.canonical_payload),
        exact_vc_key(&reverse).map(|key| key.canonical_payload),
        "equivalent unordered label maps must have one exact canonical identity"
    );
    let digest = exact_vc_claim_digest_sha256(&forward, false, None);
    assert_eq!(
        digest,
        exact_vc_claim_digest_sha256(&reverse, false, None),
        "equivalent unordered label maps must publish the same claim digest"
    );

    let mut changed = reverse;
    let VcKind::Temporal { machine: Some(machine), .. } = &mut changed.kind else {
        panic!("test fixture must retain its temporal state machine");
    };
    machine.labels.insert(1, vec!["different".to_string()]);
    assert_ne!(
        digest,
        exact_vc_claim_digest_sha256(&changed, false, None),
        "changing label content must still change the exact claim digest"
    );
}

