#[test]
fn advisory_policy_help_is_only_for_structurally_sound_pure_gaps() {
    let gap = |unknown, runtime_checked, skipped| FullVerificationFailure {
        failed: 0,
        unknown,
        runtime_checked,
        skipped,
    };

    let pure_gaps =
        [(gap(1, 0, 0), false), (gap(0, 1, 0), false), (gap(0, 0, 1), false), (gap(0, 0, 0), true)];
    for (failure, has_unproved_assumption_panic) in pure_gaps {
        assert!(
            advisory_policy_help_applies(failure, has_unproved_assumption_panic, true),
            "a structurally sound pure coverage gap should receive actionable advisory guidance"
        );
    }

    let refutation =
        FullVerificationFailure { failed: 1, unknown: 0, runtime_checked: 0, skipped: 0 };
    let mixed = FullVerificationFailure { failed: 1, unknown: 1, runtime_checked: 0, skipped: 0 };
    assert!(!advisory_policy_help_applies(refutation, false, true));
    assert!(!advisory_policy_help_applies(mixed, false, true));
    assert!(!advisory_policy_help_applies(gap(1, 0, 0), false, false));
    assert!(!advisory_policy_help_applies(gap(0, 0, 0), false, true));
}

#[test]
fn strict_scope_bucket_fatality_follows_the_discharge_policy() {
    // Trust (program-3 C.7): `strict_failure_is_fatal` gained
    // `require_full_discharge`, and the two policies differ on EXACTLY ONE
    // bucket. This test pins both sides, because pinning only one leaves the
    // other free to regress — and the whole point of the parameter is that the
    // two answers differ.
    let failed = FullVerificationFailure { failed: 1, unknown: 0, runtime_checked: 0, skipped: 0 };
    let unknown = FullVerificationFailure { failed: 0, unknown: 1, runtime_checked: 0, skipped: 0 };
    let checked = FullVerificationFailure { failed: 0, unknown: 0, runtime_checked: 1, skipped: 0 };
    let skipped = FullVerificationFailure { failed: 0, unknown: 0, runtime_checked: 0, skipped: 1 };
    let clean = FullVerificationFailure { failed: 0, unknown: 0, runtime_checked: 0, skipped: 0 };

    // Full discharge: every unproved bucket is fatal, `runtime_checked` included.
    for failure in [failed, unknown, checked, skipped] {
        assert!(
            strict_failure_is_fatal(failure, true),
            "full discharge must reject every unproved outcome bucket: {failure:?}"
        );
    }

    // Policy B: `runtime_checked` is the ONE tolerated bucket — rustc still emits
    // the check, so such a row is bit-for-bit vanilla Rust semantics and failing
    // the build on it buys no safety while costing drop-in. Every other bucket
    // stays fatal.
    for failure in [failed, unknown, skipped] {
        assert!(
            strict_failure_is_fatal(failure, false),
            "policy B must still reject this bucket: {failure:?}"
        );
    }
    assert!(
        !strict_failure_is_fatal(checked, false),
        "policy B tolerates a runtime-checked row; this is the whole difference"
    );

    // Nothing unproved is fatal under either policy.
    assert!(!strict_failure_is_fatal(clean, true));
    assert!(!strict_failure_is_fatal(clean, false));
}

#[test]
fn default_gap_policy_tolerates_only_the_exact_defined_float_advisory_exception() {
    let failed = || VerificationResult::Failed {
        solver: trust_types::Symbol::intern("float-policy-test"),
        time_ms: 1,
        counterexample: None,
    };

    for width in [32, 64] {
        let mut vc = test_vc(width);
        vc.kind = VcKind::FloatOverflowToInfinity {
            op: BinOp::Add,
            operand_ty: trust_types::Ty::Float { width },
        };
        assert_eq!(
            residual_gap_tolerance_denial(&[(vc, failed())], true),
            None,
            "defined binary{width} infinity is a nonfatal default-policy advisory"
        );
    }

    let mut contract = test_vc(70);
    contract.kind = VcKind::Postcondition;
    assert_eq!(
        residual_gap_tolerance_denial(&[(contract, failed())], true),
        Some(GapToleranceDenial::RowRefuted),
        "the exception must never widen to arbitrary L1 contract failures"
    );

    let mut unsupported = test_vc(71);
    unsupported.kind = VcKind::UnsupportedMir {
        kind: "float-policy-negative".to_string(),
        detail: "unmodeled construct".to_string(),
    };
    let unknown = VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("float-policy-test"),
        reason: "unsupported".to_string(),
        time_ms: 1,
    };
    assert_eq!(
        residual_gap_tolerance_denial(&[(unsupported, unknown)], true),
        Some(GapToleranceDenial::RowHasNoFallback),
        "a genuine no-fallback modeling gap must stay fail-closed"
    );
}

#[test]
fn default_gap_policy_asks_the_fallback_question_of_unproved_rows_only() {
    // Policy B as ruled (2026-07-25, "What still fails the build under B"): the
    // second fatal class is "an UNPROVED row that has no runtime check". A
    // PROVED postcondition beside a runtime-checked division is not a gap; an
    // unproved postcondition still is.
    let proved = || VerificationResult::Proved {
        solver: "ay-in-process".into(),
        time_ms: 0,
        strength: ProofStrength::smt_unsat(),
        proof_certificate: None,
        solver_warnings: None,
        native_proof_envelope: None,
    };
    let unknown = || VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("policy-b-test"),
        reason: "pdr returned unknown".to_string(),
        time_ms: 1,
    };
    let mut contract = test_vc(80);
    contract.kind = VcKind::Postcondition;
    assert!(!contract.kind.has_runtime_fallback(true), "the test needs a no-fallback kind");
    let checked_div = test_vc(81); // `DivisionByZero`: always runtime-checked

    assert_eq!(
        residual_gap_tolerance_denial(
            &[(contract.clone(), proved()), (checked_div.clone(), unknown())],
            true
        ),
        None,
        "a PROVED no-fallback row must not deny a gap that lies on a runtime-checked row"
    );
    assert_eq!(
        residual_gap_tolerance_denial(&[(contract.clone(), unknown())], true),
        Some(GapToleranceDenial::RowHasNoFallback),
        "an UNPROVED no-fallback row stays fatal"
    );
    assert_eq!(
        residual_gap_tolerance_denial(
            &[(contract.clone(), proved()), (contract, unknown()), (checked_div, unknown())],
            true
        ),
        Some(GapToleranceDenial::RowHasNoFallback),
        "one proved no-fallback row does not launder a second, unproved one"
    );
}

#[test]
fn default_gap_policy_reports_opaque_hardened_design_mandates_but_denies_real_hardened_rows() {
    // Hardened design mandates (2026-09-16): an OPAQUE `HardenedBoundary` row —
    // violation formula `Bool(true)`, the transport's `design_mandate` shape —
    // is a design requirement targo partitions as `mandated`; it must not deny
    // the default policy's tolerance. A hardened row carrying a REAL formula
    // is an obligation with no runtime fallback and still denies.
    let unknown = || VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("hardened-test"),
        reason: "opaque mandate".to_string(),
        time_ms: 1,
    };
    let hardened_kind = || VcKind::HardenedBoundary {
        category: trust_types::HardenedVcCategory::CompatObservable,
        callee: "std::env::args".to_string(),
        detail: "CLI boundary uses Unicode String args".to_string(),
    };
    let mut mandate = test_vc(90);
    mandate.kind = hardened_kind();
    mandate.formula = trust_types::Formula::Bool(true);
    let checked_div = test_vc(91); // `DivisionByZero`: always runtime-checked
    assert_eq!(
        residual_gap_tolerance_denial(&[(mandate, unknown()), (checked_div, unknown())], true),
        None,
        "an opaque design mandate is reported, not fatal, under the default policy"
    );

    let mut real = test_vc(92);
    real.kind = hardened_kind();
    real.formula = trust_types::Formula::Le(
        Box::new(trust_types::Formula::var("x", trust_types::Sort::Int)),
        Box::new(trust_types::Formula::Int(0)),
    );
    assert_eq!(
        residual_gap_tolerance_denial(&[(real, unknown())], true),
        Some(GapToleranceDenial::RowHasNoFallback),
        "a hardened row with a real formula is an obligation and stays fatal"
    );

    // G3-MANDATE-L1-ONLY-1 (2026-10-27): an L0 unsafe/FFI row whose `Bool(true)` is
    // a modelling-gap fail-close (an FFI call with no summary) is not a design
    // requirement and keeps denying tolerance, unknown or refuted.
    for kind in [
        VcKind::FfiBoundaryViolation {
            callee: "raise".to_string(),
            desc: "FFI call has no summary: behavior unmodeled, cannot prove safe".to_string(),
        },
        VcKind::HardenedBoundary {
            category: trust_types::HardenedVcCategory::FfiBoundary,
            callee: "getpgrp".to_string(),
            detail: "no summary".to_string(),
        },
        VcKind::Assertion {
            message: "[unsafe:unmodeled-call] call to `ext` is not covered".to_string(),
        },
    ] {
        let mut gap = test_vc(93);
        gap.kind = kind;
        gap.formula = trust_types::Formula::Bool(true);
        assert_eq!(
            residual_gap_tolerance_denial(&[(gap.clone(), unknown())], true),
            Some(GapToleranceDenial::RowHasNoFallback),
            "an unknown L0 modelling gap is not a mandate: {:?}",
            gap.kind
        );
        let failed = VerificationResult::Failed {
            solver: trust_types::Symbol::intern("hardened-test"),
            time_ms: 1,
            counterexample: None,
        };
        assert_eq!(
            residual_gap_tolerance_denial(&[(gap.clone(), failed)], true),
            Some(GapToleranceDenial::RowRefuted),
            "a refuted L0 modelling gap is a refutation: {:?}",
            gap.kind
        );
    }
}

