/// A transport row marked by the bridge as an EXTERN print/format/write dispatch
/// panic-freedom row (as it appears after `legacy_vc_from_api_obligation` folds the
/// marked obligation description into `VcKind::Assertion { message }`).
fn extern_call_transport_row(outcome: Outcome) -> TransportObligationResult {
    extern_call_transport_row_for("alloc::fmt::format", outcome)
}

/// An extern print/format/write dispatch row for a NAMED callee. The callee is
/// carried between the first backtick pair exactly as the bridge writes it, which
/// is where `extern_call_row_callee` reads it back from.
fn extern_call_transport_row_for(callee: &str, outcome: Outcome) -> TransportObligationResult {
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "assert".to_string(),
        original_vc_snapshot: None,
        typed_kind: None,
        description: format!(
            "assertion: {}extern print/format/write dispatch `{callee}` runs a user Display/Debug impl that may panic",
            trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX
        ),
        location: None,
        outcome,
        solver: "trust-full-verifier".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: None,
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    }
}

fn plain_transport_row(outcome: Outcome, design_mandate: bool) -> TransportObligationResult {
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "assert".to_string(),
        original_vc_snapshot: None,
        typed_kind: None,
        description: "assertion: some obligation".to_string(),
        location: None,
        outcome,
        solver: "ay-in-process".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: None,
        design_mandate,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    }
}

fn contract_panic_transport_row(outcome: Outcome) -> TransportObligationResult {
    let mut row = plain_transport_row(outcome, false);
    row.description = format!(
        "assertion: {}declared capacity panic",
        trust_types::assumption::CONTRACT_PANIC_VC_MARKER
    );
    row
}

#[test]
fn contract_panic_rows_rewrite_only_in_survey() {
    let mut row = contract_panic_transport_row(Outcome::Failed);
    row.typed_kind = Some(Box::new(VcKind::Assertion {
        message: format!(
            "{}declared capacity panic",
            trust_types::assumption::CONTRACT_PANIC_VC_MARKER
        ),
    }));
    let strict = test_policy(false, false);
    let boundary = test_policy(false, false);
    for (name, policy) in [("strict", strict), ("implicit boundary", boundary)] {
        assert!(
            rewrite_contract_panic_transport_rows(&policy, std::slice::from_ref(&row)).is_none(),
            "{name} must retain the raw failed row; contract panic is not proof"
        );
    }

    let survey = test_policy(true, false);
    let rewritten = rewrite_contract_panic_transport_rows(&survey, std::slice::from_ref(&row))
        .expect("survey must publish conditional contract evidence");
    assert_eq!(rewritten.len(), 1);
    assert_eq!(rewritten[0].kind, trust_types::assumption::CONTRACT_PANIC_MATCHED_ROW_KIND);
    assert_eq!(rewritten[0].outcome, Outcome::Failed, "conditional evidence is never proof");
    assert_eq!(rewritten[0].solver, trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE);
    assert!(
        rewritten[0].typed_kind.is_none(),
        "a synthetic contract-panic classification must not retain the original VC identity"
    );
}

fn failed_test_result() -> VerificationResult {
    VerificationResult::Failed {
        solver: trust_types::Symbol::intern("ay-in-process"),
        time_ms: 3,
        counterexample: None,
    }
}

fn memory_safe_gate_artifacts(
    vc: VerificationCondition,
    result: VerificationResult,
    status: TrustStatus,
    row: TransportObligationResult,
) -> VerificationArtifacts {
    let mut dispositions = IndexVec::new();
    dispositions.push(TrustDisposition {
        kind: TrustObligationKind::Assertion,
        status,
        strength: TrustProofStrength::None,
        certified: false,
    });
    let summary = TrustFunctionSummary::from_dispositions(&dispositions);
    // Trust (T3 L4, C07r): the one row lives in a context of its own.
    let mut rows = trust_types::vc_context::VcContext::new();
    let results = RowResults::intern(&mut rows, vec![(vc, result)]);
    VerificationArtifacts {
        proof_results: TrustProofResults {
            dispositions,
            fingerprints: IndexVec::new(),
            summary,
            premises: Vec::new(),
        },
        telemetry: TrustProofTelemetry { details: IndexVec::new() },
        results,
        transport_results: vec![row],
        full_verification: None,
        result_bindings: Vec::new(),
        proof_authorities: Vec::new(),
        overflow_check_origins: OverflowCheckOrigins::default(),
        coroutine_resume_contract: None,
        max_proof_level: None,
        expanded_function_identity: None,
        runtime_checked_std_members: Vec::new(),
        calculus_reporting: None,
        ctx: Arc::new(rows),
    }
}

#[test]
fn memory_safe_failed_panic_gets_authenticated_assumption_row() {
    let results = vec![(test_vc(7), failed_test_result())];
    let mut failed = plain_transport_row(Outcome::Failed, false);
    failed.kind = "divzero".to_string();
    failed.typed_kind = Some(Box::new(VcKind::DivisionByZero));
    failed.claim_digest_sha256 = Some("real-vc-claim-digest".to_string());
    failed.native_trust_ir = Some(test_transport_native_trust_ir());
    failed.proof_evidence = Some(test_transport_proof_evidence());

    let rewritten = rewrite_memory_safe_panic_refutation_rows(true, &results, &[failed])
        .expect("safe failed panic must be reclassified");
    assert_eq!(rewritten.len(), 1);
    assert_eq!(
        rewritten[0].kind,
        format!("assumption:{}", trust_types::assumption::MEMORY_SAFE_PANIC_ASSUMPTION_TAG)
    );
    assert_eq!(rewritten[0].outcome, Outcome::Skipped);
    assert_eq!(rewritten[0].solver, trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE);
    assert!(rewritten[0].native_trust_ir.is_none());
    assert!(rewritten[0].proof_evidence.is_none());
    assert!(
        rewritten[0].typed_kind.is_none(),
        "a synthetic memory-safe assumption must not retain the original VC identity"
    );
    assert!(
        rewritten[0].claim_digest_sha256.is_none(),
        "a synthetic assumption must not retain the real VC's claim authority"
    );
    assert!(
        native_lowering_collapse_keeps_row(&rewritten[0]),
        "a later native-lowering collapse must retain the explicit safe-panic assumption"
    );

    let artifacts = memory_safe_gate_artifacts(
        test_vc(7),
        failed_test_result(),
        TrustStatus::Failed,
        plain_transport_row(Outcome::Failed, false),
    );
    assert!(
        !memory_safe_artifacts_have_non_demotable_failure(&artifacts, &rewritten),
        "raw trustc must accept the same authenticated safe-panic assumption as Targo"
    );
    assert!(
        memory_safe_artifacts_have_non_demotable_failure(&artifacts, &artifacts.transport_results),
        "the raw failed row must remain fatal until it is actually reclassified"
    );
}

#[test]
fn memory_safe_rewrite_never_touches_unsafe_or_disabled_policy_rows() {
    let failed = plain_transport_row(Outcome::Failed, false);
    let safe_results = vec![(test_vc(8), failed_test_result())];
    assert!(
        rewrite_memory_safe_panic_refutation_rows(false, &safe_results, &[failed.clone()])
            .is_none(),
        "an unsafe body/default policy passes enabled=false and must stay strict"
    );

    let mut unsafe_vc = test_vc(9);
    unsafe_vc.kind = VcKind::UnsafeOperation { desc: "raw pointer dereference".to_string() };
    let unsafe_results = vec![(unsafe_vc, failed_test_result())];
    assert!(
        rewrite_memory_safe_panic_refutation_rows(true, &unsafe_results, &[failed]).is_none(),
        "UB-class rows remain failed even if a caller incorrectly asks the pure helper to demote"
    );
}

#[test]
fn memory_safe_rewrite_rejects_contract_and_nonpanic_l0_failures() {
    let failed = plain_transport_row(Outcome::Failed, false);
    let mut contract_vc = test_vc(10);
    contract_vc.kind = VcKind::Assertion {
        message: format!("{}declared panic", trust_types::assumption::CONTRACT_PANIC_VC_MARKER),
    };
    let contract_row = contract_panic_transport_row(Outcome::Failed);
    assert!(
        rewrite_memory_safe_panic_refutation_rows(
            true,
            &[(contract_vc.clone(), failed_test_result())],
            std::slice::from_ref(&contract_row),
        )
        .is_none(),
        "contract-panic evidence keeps its separate fail-closed protocol"
    );
    let contract_artifacts = memory_safe_gate_artifacts(
        contract_vc,
        failed_test_result(),
        TrustStatus::Failed,
        contract_row.clone(),
    );
    assert!(
        memory_safe_artifacts_have_non_demotable_failure(
            &contract_artifacts,
            std::slice::from_ref(&contract_row),
        ),
        "memory-safe must reject contract-panic conditional evidence"
    );

    let mut allocation_vc = test_vc(11);
    allocation_vc.kind = VcKind::UnboundedAllocation {
        callee: "Vec::with_capacity".to_string(),
        count: "1 << 30".to_string(),
        detail: "exceeds configured allocation budget".to_string(),
    };
    assert!(
        rewrite_memory_safe_panic_refutation_rows(
            true,
            &[(allocation_vc, failed_test_result())],
            &[failed],
        )
        .is_none(),
        "availability/design failures are not Rust runtime-panic assumptions"
    );
}

#[test]
fn memory_safe_gate_accepts_only_authenticated_lowering_gap() {
    let mut unsupported_vc = test_vc(12);
    unsupported_vc.kind = VcKind::UnsupportedMir {
        kind: "FullVerification::Assertion".to_string(),
        detail: "native typed lowering did not complete".to_string(),
    };
    let unknown = VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("trust-full-verifier"),
        time_ms: 0,
        reason: "lowering failed".to_string(),
    };
    let raw = plain_transport_row(Outcome::Unknown, false);
    let artifacts =
        memory_safe_gate_artifacts(unsupported_vc, unknown, TrustStatus::Unknown, raw.clone());
    let mut marked = raw;
    marked.kind = format!("assumption:{}", trust_types::assumption::NATIVE_LOWERING_ASSUMPTION_TAG);
    marked.outcome = Outcome::Skipped;
    marked.solver = trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE.to_string();
    assert!(!memory_safe_artifacts_have_non_demotable_failure(&artifacts, &[marked]));

    let unmarked = plain_transport_row(Outcome::Unknown, false);
    assert!(memory_safe_artifacts_have_non_demotable_failure(&artifacts, &[unmarked]));
}

// Trust (coroutine resume-state contract): the pure gates of the contract-row
// upgrade. The full `coroutine_protocol_disposition` needs a TyCtxt/Body; the
// two row-level predicates it composes are pinned here directly.
#[test]
fn coroutine_contract_upgrade_row_gates_fail_closed() {
    let evidence = trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: 2,
    };

    // (a) all-rows-proved: an empty row set DECLINES (the sentinel obligations
    // never surfaced), any non-proved row blocks, design-mandate inventory
    // rows are excepted.
    assert!(!coroutine_contract_rows_all_statically_proved(&[]));
    let proved = plain_transport_row(Outcome::Proved, false);
    let unknown = plain_transport_row(Outcome::Unknown, false);
    let mandate = plain_transport_row(Outcome::Unknown, true);
    assert!(coroutine_contract_rows_all_statically_proved(&[proved.clone()]));
    assert!(coroutine_contract_rows_all_statically_proved(&[proved.clone(), mandate.clone()]));
    assert!(!coroutine_contract_rows_all_statically_proved(&[proved.clone(), unknown.clone()]));

    // (b) sentinel-proof visibility: per-sentinel marker rows must be PROVED,
    // must parse to the evidence's exact state set, and must match its COUNT.
    let sentinel_row = |outcome: Outcome, states: &[u128]| {
        let mut row = plain_transport_row(outcome, false);
        row.description = trust_types::assumption::coroutine_resume_contract_obligation_description(
            states,
            "resumed after return",
        );
        row
    };
    let two_proved = [sentinel_row(Outcome::Proved, &[0]), sentinel_row(Outcome::Proved, &[0])];
    assert!(rows_exhibit_coroutine_sentinel_proof(&two_proved, &evidence));
    // Count mismatch (one of the two sentinels vanished): decline.
    assert!(!rows_exhibit_coroutine_sentinel_proof(&two_proved[..1], &evidence));
    // Unproved sentinel: decline.
    let one_unknown = [sentinel_row(Outcome::Proved, &[0]), sentinel_row(Outcome::Unknown, &[0])];
    assert!(!rows_exhibit_coroutine_sentinel_proof(&one_unknown, &evidence));
    // State-set drift between the marker rows and the evidence: decline.
    let drifted = [sentinel_row(Outcome::Proved, &[0, 3]), sentinel_row(Outcome::Proved, &[0, 3])];
    assert!(!rows_exhibit_coroutine_sentinel_proof(&drifted, &evidence));

    // The marker travels inside `VcKind::Assertion`'s RENDERED description, so
    // the belt must see through exactly the one `"assertion: "` renderer prefix
    // — without this the real transport shape is unmatchable and the belt could
    // only ever have passed via the deleted aggregate fallback.
    let rendered = |states: &[u128]| {
        let mut row = plain_transport_row(Outcome::Proved, false);
        row.description = trust_types::VcKind::Assertion {
            message: trust_types::assumption::coroutine_resume_contract_obligation_description(
                states,
                "resumed after return",
            ),
        }
        .description();
        row
    };
    assert!(rows_exhibit_coroutine_sentinel_proof(&[rendered(&[0]), rendered(&[0])], &evidence));

    // (c) THE DELETED AGGREGATE FALLBACK. A proved whole-function panic-freedom
    // row — under either the id the fallback looked for or the `assert:0` id a
    // coroutine body actually carries — is NOT sentinel-proof evidence:
    // measured, that row's `Proved` came from the interprocedural rule, which
    // cannot see a sentinel `Terminator::Assert` and is vacuous for a call-free
    // resume body. Accepting it would make the contract vacuous.
    let canon = trust_types::canonical_artifact_id_component("crate::f::{closure#0}");
    for id in [format!("vc:{canon}:assertion:panic-freedom:0"), format!("vc:{canon}:assert:0")] {
        let mut aggregate = plain_transport_row(Outcome::Proved, false);
        aggregate.obligation_id = Some(id);
        aggregate.description =
            "assertion: panic freedom: no assertion, `unreachable!`, or panic is reachable"
                .to_string();
        assert!(!rows_exhibit_coroutine_sentinel_proof(
            std::slice::from_ref(&aggregate),
            &evidence
        ));
    }

    // Zero-sentinel evidence can never be witnessed by an empty marker count.
    let empty_evidence = trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: 0,
    };
    assert!(!rows_exhibit_coroutine_sentinel_proof(&[], &empty_evidence));
}

// Trust (coroutine resume-state contract, D1 publish coupling): the pure
// publish decision is the ONE seam pairing the bridge's entry Assume
// (witnessed by evidence) with a published row. The load-bearing pin is the
// third case: EVIDENCE PRESENT + ZERO MIR SENTINELS must publish the
// assumption row (strict abort), never "not a coroutine" (no row) — the exact
// unpaired state of the D1 defect, where a narrowing Assume shipped with no
// row, no assumption, and no abort.
#[test]
fn coroutine_publish_decision_pairs_every_assume_with_a_row() {
    let evidence = |count: usize| trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: count,
    };

    // Advisory lane + no unmarked conditional proof, so these cases isolate the
    // ORIGINAL (pre-D2) axes; the D2 axes get their own test below.
    let ev2 = evidence(2);
    let decide = |sentinels, ev, proved, visible| {
        coroutine_protocol_publish_decision(sentinels, ev, proved, visible, true, true)
    };

    // Not a coroutine resume body: no sentinels, no evidence — publish nothing.
    assert!(matches!(
        decide(0, None, true, false),
        CoroutineProtocolPublishDecision::NotACoroutineResumeBody
    ));
    // Sentinels without evidence: the pre-lane fail-closed assumption row.
    assert!(matches!(
        decide(2, None, true, false),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // THE D1 PIN: evidence (the module carries the entry Assume) with zero
    // MIR sentinels must still publish — assumption row + strict abort.
    assert!(matches!(
        decide(0, Some(&ev2), true, true),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // Sentinel-count mismatch (a pruned/dropped sentinel): assumption row.
    assert!(matches!(
        decide(1, Some(&ev2), true, true),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // Unproved rows / invisible sentinel proof: assumption row.
    assert!(matches!(
        decide(2, Some(&ev2), false, true),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    assert!(matches!(
        decide(2, Some(&ev2), true, false),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // The full upgrade: exact count + all rows proved + sentinel proof visible.
    assert!(matches!(
        decide(2, Some(&ev2), true, true),
        CoroutineProtocolPublishDecision::PublishContractRow
    ));
}

// Trust (D2): THE FALSE-PROVE PINS. `pub async fn tick(x: u32) -> u32 { x }`
// under default strict policy reported "2 proved, 0 failed, 0 unknown … of
// which 2 kernel-certified by the clean CIC kernel" and exit 0, while a driver
// polling it twice panicked "`async fn` resumed after completion" at the exact
// span of the row certified panic-free. Two independent gates now close it.
#[test]
fn coroutine_publish_decision_refuses_contract_in_fail_closed_and_over_unmarked_proof() {
    let evidence = trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: 2,
    };
    // Everything the ORIGINAL upgrade required is satisfied in all three calls;
    // only the two D2 axes vary. That is what makes these gates load-bearing
    // rather than incidentally masked by another failing precondition.

    // PART A — a fail-closed lane may not publish the contract row. No
    // caller-side discharge lane exists (the bridge says so in the obligation
    // text it mints), so publishing here converts an undischarged premise into
    // silence. This is the arm that restores the strict abort.
    assert!(matches!(
        coroutine_protocol_publish_decision(2, Some(&evidence), true, true, false, true),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // PART B — an UNMARKED row claiming proof over the entry `Assume` blocks
    // the upgrade even in the advisory lane. The whole-function panic-freedom
    // aggregate was exactly such a row: a proof that consumed the premise
    // without saying so on the row.
    assert!(matches!(
        coroutine_protocol_publish_decision(2, Some(&evidence), true, true, true, false),
        CoroutineProtocolPublishDecision::PublishAssumptionRow
    ));
    // Both D2 axes clear + advisory: the feature is GATED, not deleted.
    assert!(matches!(
        coroutine_protocol_publish_decision(2, Some(&evidence), true, true, true, true),
        CoroutineProtocolPublishDecision::PublishContractRow
    ));
}

// Trust (D2 part B): the marker must land ON THE ROW THAT CONSUMED THE ASSUME.
// The entry `Assume(resume_state ∈ live_states)` dominates every block, so every
// discharge in the body is conditional; only the bridge-MARKED sentinel rows may
// be conditional without saying so on the row, because describing them is what
// the contract row is for. Before D2 the whole-function panic-freedom aggregate
// shipped as `kind: "assert"`, `outcome: "proved"`, `assurance: Certified`,
// `axiom_closure: Empty`, with a CIC term BYTE-IDENTICAL to the sentinel row's
// ex-falso derivation — and nothing linked it to the sibling contract row.
#[test]
fn coroutine_conditional_stamp_marks_the_row_that_consumed_the_assume() {
    let evidence = trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: 1,
    };
    // Trust: exercise populated, exactly bound original-VC sidecars, not the
    // default None that would hide a stale snapshot after demotion.
    let with_snapshot = |mut row: TransportObligationResult| {
        let target = "aarch64-apple-darwin;ptr64";
        let mut vc = test_vc(10);
        vc.kind = VcKind::Assertion {
            message: row.description.strip_prefix("assertion: ").unwrap().to_string(),
        };
        let digest = exact_vc_claim_digest_sha256(&vc, true, Some(target)).unwrap();
        let id = format!("coroutine-stamp-{digest}");
        row.original_vc_snapshot = Some(Box::new(
            trust_types::OriginalVcSnapshot::capture(&vc, true, target, &id, &digest)
                .expect("bounded original VC snapshot"),
        ));
        row.obligation_id = Some(id);
        row.claim_digest_sha256 = Some(digest);
        row.typed_kind = Some(Box::new(vc.kind));
        row
    };
    let marked_sentinel = {
        let mut row = plain_transport_row(Outcome::Proved, false);
        row.description = trust_types::VcKind::Assertion {
            message: trust_types::assumption::coroutine_resume_contract_obligation_description(
                &[0],
                "resumed after return",
            ),
        }
        .description();
        with_snapshot(row)
    };
    let aggregate = {
        let mut row = plain_transport_row(Outcome::Proved, false);
        row.kind = "assert".to_string();
        row.description =
            "assertion: panic freedom: no assertion, `unreachable!`, or panic is reachable"
                .to_string();
        with_snapshot(row)
    };

    assert!(marked_sentinel.original_vc_snapshot.is_some());
    assert!(aggregate.original_vc_snapshot.is_some());

    // The marked sentinel alone is fine: it is conditional BY DESIGN and says so.
    assert!(coroutine_rows_free_of_unmarked_conditional_proof(
        std::slice::from_ref(&marked_sentinel),
        &evidence
    ));
    // The aggregate next to it is NOT: an unmarked proof over the entry Assume.
    assert!(!coroutine_rows_free_of_unmarked_conditional_proof(
        &[marked_sentinel.clone(), aggregate.clone()],
        &evidence
    ));
    // A design-mandate row is inventory, never a discharge target.
    assert!(coroutine_rows_free_of_unmarked_conditional_proof(
        &[marked_sentinel.clone(), plain_transport_row(Outcome::Proved, true)],
        &evidence
    ));
    // A row that never claimed proof needs no marker.
    assert!(coroutine_rows_free_of_unmarked_conditional_proof(
        &[marked_sentinel.clone(), plain_transport_row(Outcome::Unknown, false)],
        &evidence
    ));

    // The stamp: the aggregate loses its bare proof claim and its Certified
    // grade, keeps its identity after the prefix, and the marked sentinel is
    // left exactly as it was.
    let stamped = stamp_coroutine_conditional_rows(
        &[marked_sentinel.clone(), aggregate.clone()],
        Some(&evidence),
    );
    assert_eq!(stamped.len(), 2);
    assert_eq!(stamped[0], marked_sentinel, "a marked sentinel row must pass through untouched");
    assert_eq!(stamped[1].outcome, Outcome::Skipped);
    assert!(stamped[1].proof_evidence.is_none(), "a conditional row keeps no Certified grade");
    assert!(
        stamped[1].original_vc_snapshot.is_none(),
        "a reclassified conditional row keeps no original-claim replay sidecar"
    );
    // Trust (VF1): the aggregate was ungraded, and the stamp grades nothing.
    assert_eq!(stamped[1].grade, None);
    {
        use trust_types::authority_grade::{
            GradeDischarge, GradeEncoding, GradePremise, ObligationGrade,
        };
        let mut graded = aggregate.clone();
        graded.grade = Some(ObligationGrade::new(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::KernelReconstructed,
            &[],
        ));
        let stamped = stamp_coroutine_conditional_rows(&[graded], Some(&evidence));
        assert_eq!(stamped[0].outcome, Outcome::Skipped);
        assert!(stamped[0].proof_evidence.is_none());
        assert!(
            stamped[0].original_vc_snapshot.is_none(),
            "disclosing the executor premise must not retain an original-claim replay sidecar"
        );
        assert_eq!(
            stamped[0].grade.as_ref().map(|grade| grade.premises.as_slice()),
            Some(&[GradePremise::ExecutorProtocol][..]),
            "a conditional row's grade names the executor-protocol premise it now rests on"
        );
    }
    assert!(trust_types::assumption::is_coroutine_resume_conditional_row_kind(&stamped[1].kind));
    assert_eq!(
        stamped[1]
            .kind
            .strip_prefix(trust_types::assumption::COROUTINE_RESUME_CONDITIONAL_ROW_KIND_PREFIX),
        Some("assert"),
        "the original kind must survive after the prefix"
    );
    assert_eq!(
        stamped[1].reason.as_deref(),
        Some(trust_types::assumption::COROUTINE_RESUME_CONDITIONAL_ROW_REASON)
    );
    // Idempotent: a stamped row no longer claims Proved, so it is not restamped.
    let twice = stamp_coroutine_conditional_rows(&stamped, Some(&evidence));
    assert_eq!(twice, stamped);

    // EVIDENCE-ABSENT. `trust_vcgen::build_coroutine_resume_state_facts` derives
    // the executor-protocol premise from the BODY, so the rows of a recognized
    // resume body are conditional on it whether or not the bridge's module
    // evidence reached this seam. Nothing may ship as bare `Proved` there — and
    // with no authenticated state set to check a marker against, the sentinel
    // row's own description buys no exemption either.
    let unauthenticated =
        stamp_coroutine_conditional_rows(&[marked_sentinel.clone(), aggregate], None);
    assert_eq!(unauthenticated.len(), 2);
    assert!(
        unauthenticated.iter().all(|row| row.outcome != Outcome::Proved),
        "an evidence-absent recognized resume body must ship NO bare Proved row: \
         {unauthenticated:?}"
    );
    assert!(
        unauthenticated.iter().all(|row| {
            trust_types::assumption::is_coroutine_resume_conditional_row_kind(&row.kind)
        }),
        "and every demoted row must say WHY on its kind: {unauthenticated:?}"
    );
    assert!(
        unauthenticated.iter().all(|row| row.proof_evidence.is_none()),
        "a conditional row keeps no Certified grade: {unauthenticated:?}"
    );
    assert!(
        unauthenticated.iter().all(|row| row.original_vc_snapshot.is_none()),
        "every demoted row clears its original-claim replay sidecar: {unauthenticated:?}"
    );
    // Still leaves non-discharge inventory alone, including its snapshot.
    let mandate = with_snapshot(plain_transport_row(Outcome::Proved, true));
    assert_eq!(
        stamp_coroutine_conditional_rows(std::slice::from_ref(&mandate), None),
        vec![mandate],
        "a design-mandate row is inventory, never a discharge target"
    );
    // Existing Unknown rows retain their complete diagnostic payload unchanged.
    let unknown = with_snapshot(plain_transport_row(Outcome::Unknown, false));
    for authenticated in [Some(&evidence), None] {
        assert_eq!(
            stamp_coroutine_conditional_rows(std::slice::from_ref(&unknown), authenticated),
            vec![unknown.clone()],
            "a row that already lacks proof is not reclassified"
        );
    }
}

// The published contract row is Skipped/conditional on the wire: the
// memory-safe lane must keep REJECTING it (it is not an authenticated
// memory-safe assumption), and it must never read as the old assumption row.
#[test]
fn coroutine_contract_row_is_not_an_assumption_row_and_memory_safe_still_rejects() {
    let evidence = trust_ir_bridge::CoroutineResumeContractModuleEvidence {
        function_def_path: "crate::f::{closure#0}".to_string(),
        live_states: vec![0],
        sentinel_obligation_count: 2,
    };
    let mut row = plain_transport_row(Outcome::Skipped, false);
    row.kind = trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_KIND.to_string();
    row.solver = trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_SOLVER.to_string();
    row.description =
        trust_types::assumption::coroutine_resume_contract_row_description(&evidence.live_states);
    row.reason = Some(trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_REASON.to_string());
    assert!(
        !transport_row_is_coroutine_protocol_assumption(&row),
        "the contract row must never be mistaken for the assumption row"
    );
    assert!(
        !transport_row_is_authenticated_memory_safe_assumption(&row),
        "the contract row grants nothing in the memory-safe lane"
    );
}

#[test]
fn memory_safe_zero_data_obligations_still_rejects_coroutine_protocol_premise() {
    let dispositions: IndexVec<ObligationId, TrustDisposition> = IndexVec::new();
    let summary = TrustFunctionSummary::from_dispositions(&dispositions);
    let artifacts = VerificationArtifacts {
        proof_results: TrustProofResults {
            dispositions,
            fingerprints: IndexVec::new(),
            summary,
            premises: Vec::new(),
        },
        telemetry: TrustProofTelemetry { details: IndexVec::new() },
        results: RowResults::default(),
        transport_results: Vec::new(),
        full_verification: None,
        result_bindings: Vec::new(),
        proof_authorities: Vec::new(),
        overflow_check_origins: OverflowCheckOrigins::default(),
        coroutine_resume_contract: None,
        max_proof_level: None,
        expanded_function_identity: None,
        runtime_checked_std_members: Vec::new(),
        calculus_reporting: None,
        ctx: Arc::new(trust_types::vc_context::VcContext::new()),
    };
    assert!(
        !memory_safe_artifacts_have_non_demotable_failure(&artifacts, &[]),
        "a genuinely obligation-free safe function remains admissible"
    );

    let mut coroutine = plain_transport_row(Outcome::Skipped, false);
    coroutine.kind = "assumption:coroutine".to_string();
    coroutine.description = "unverified coroutine executor protocol".to_string();
    coroutine.solver = "trust-classifier".to_string();
    assert!(transport_row_is_coroutine_protocol_assumption(&coroutine));
    assert!(
        memory_safe_artifacts_have_non_demotable_failure(&artifacts, &[coroutine]),
        "a synthetic protocol premise must not disappear behind summary.total == 0"
    );

    // Trust (2026-10-10, ZERO-ROW-GATE): the publisher's verdict is the memory-safe
    // gate's too. A zero-obligation body the publisher did NOT call vacuously clean
    // (a call no authenticated registry discharges) is refused; one it did is not.
    assert!(memory_safe_zero_obligation_body_is_unclean(&artifacts, Some(false)));
    assert!(!memory_safe_zero_obligation_body_is_unclean(&artifacts, Some(true)));
    assert!(
        memory_safe_zero_obligation_body_is_unclean(&artifacts, None),
        "a zero-obligation body with no publisher verdict fails closed"
    );
}

// A row proved independently of native bundle construction does not prove the
// bundle that construction discarded. The run-make companion exercises real
// Rust source; these controls exercise the production publisher and strict
// accounting with an actual reference-checked root proof and failure carrier.
fn discarded_bundle_gap_fixture(reason: &str) -> VerificationArtifacts {
    let mut vc = test_vc(417);
    vc.formula = Formula::Eq(Box::new(Formula::Int(0)), Box::new(Formula::Int(1)));
    let mut artifacts = memory_safe_gate_artifacts(
        vc,
        authority_test_proved(),
        TrustStatus::Trusted,
        plain_transport_row(Outcome::Proved, false),
    );
    let clean = certify_all(&artifacts.results, None);
    artifacts.proof_authorities =
        build_result_proof_authorities(&artifacts.results, &[], None, &clean);
    assert!(all_results_have_static_proof_authority(
        &artifacts.results,
        &[],
        &artifacts.proof_authorities,
    ));
    artifacts.transport_results = build_transport_results_with_runtime_checks_bound(
        false,
        None,
        &artifacts.results,
        None,
        &clean,
        &[],
        &artifacts.proof_authorities,
    );
    assert_eq!(artifacts.transport_results[0].outcome, Outcome::Proved);

    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member"]);
    let contracts = trust_types::CompilerContractBundle::new(Vec::new());
    let mut bundle = trust_mir_extract::function_to_verifier_api_bundle(&root, &contracts, &[]);
    bundle.obligations = vec![
        authority_test_native_obligation("obligation:demo:root:arithmetic", 417, 417),
        authority_test_native_obligation("obligation:demo:member:divzero", 418, 418),
    ];
    let context = trust_router::VerifierExecutionContext::new("discarded-generic-bundle");
    artifacts.full_verification = Some(native_trust_ir_bundle_build_failure_result(
        &bundle,
        &bundle.obligations,
        &context,
        reason,
    ));
    artifacts
}

#[test]
fn discarded_generic_bundle_keeps_gap_beside_proved_root() {
    let artifacts = discarded_bundle_gap_fixture(
        "TyKind::Array length N is not a concrete target usize",
    );
    let run = artifacts.full_verification.as_ref().unwrap();
    assert_eq!(run.requested_obligations.len(), 2, "root and discarded-member debt");
    assert!(native_run_trust_ir_lowering_failed(run));
    let failure = native_full_verification_failure(Some(run)).expect("strict native debt");
    assert!(strict_failure_is_fatal(failure, true));
    assert!(!native_run_is_vacuously_clean(run));
    let published = unaccounted_gap_rows(&artifacts, &artifacts.transport_results, &[], None)
        .expect("a root proof cannot discharge discarded native members");
    assert_eq!(published.len(), 2);
    assert_eq!(published[0], artifacts.transport_results[0], "keep the actual root proof");
    assert_eq!(published[1].kind, NATIVE_VERIFICATION_GAP_ROW_KIND);
    assert_eq!(published[1].outcome, Outcome::Unknown);
    let wire = serde_json::to_string(&published).expect("public rows serialize");
    let decoded: Vec<TransportObligationResult> = serde_json::from_str(&wire).unwrap();
    assert_eq!(decoded, published, "the public wire retains both proof and debt");
    assert!(unaccounted_gap_rows(&artifacts, &published, &[], None).is_none());
}

#[test]
fn lowering_gap_dedup_requires_the_existing_authenticated_assumption() {
    let artifacts = discarded_bundle_gap_fixture("generic-param T");
    let mut assumption = plain_transport_row(Outcome::Skipped, false);
    assumption.kind = format!(
        "assumption:{}",
        trust_types::assumption::NATIVE_LOWERING_ASSUMPTION_TAG,
    );
    assumption.solver = trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE.to_string();
    assert!(transport_row_is_authenticated_native_lowering_assumption(&assumption));
    assert!(unaccounted_gap_rows(&artifacts, &[assumption.clone()], &[], None).is_none());
    assert!(native_run_trust_ir_lowering_failed(artifacts.full_verification.as_ref().unwrap()),
        "transport assumption dedup never removes the strict failure");
    assumption.solver = "untrusted-label".to_string();
    let published = unaccounted_gap_rows(&artifacts, &[assumption.clone()], &[], None)
        .expect("a label alone accounts for no failed bundle");
    assert_eq!(published.len(), 2);
    assert_eq!(published[0], assumption);
    assert_eq!(published[1].kind, NATIVE_VERIFICATION_GAP_ROW_KIND);
}

#[test]
fn unaccounted_lowering_gap_preserves_deadline_and_complete_run() {
    use trust_types::determinism::StopCause;
    let mut artifacts = discarded_bundle_gap_fixture(&format!(
        "{NATIVE_BUNDLE_DEADLINE_DECLINE} before native trust-ir bundle construction",
    ));
    let published = unaccounted_gap_rows(&artifacts, &artifacts.transport_results, &[], None)
        .expect("deadline debt remains published");
    assert_eq!(published[1].outcome, Outcome::Timeout);
    assert_eq!(clock_test_stop_cause(&published[1]), Some(StopCause::WallBackstop));
    artifacts.full_verification = None;
    assert!(unaccounted_gap_rows(&artifacts, &artifacts.transport_results, &[], None).is_none());
    let obligation = authority_test_native_obligation("obligation:complete", 417, 417);
    artifacts.full_verification = Some(authority_test_strict_native_run(obligation));
    assert!(!native_run_trust_ir_lowering_failed(artifacts.full_verification.as_ref().unwrap()));
    assert!(unaccounted_gap_rows(&artifacts, &artifacts.transport_results, &[], None).is_none(),
        "a complete retained run receives no synthetic lowering debt");
}

/// Trust (2026-10-10, ZERO-ROW-GATE): the strict/certify empty-inventory accept is
/// keyed on the publisher's verdict and on the published rows. Before, it read
/// neither: `pub fn f(x: u32, n: u32) -> u32 { x.rotate_left(n) }` published one
/// `unknown` `native-verification-gap` row (its call is discharged by no
/// authenticated registry) and the first early return of
/// `abort_on_full_verification_failure` accepted it, exit 0 under certify.
#[test]
fn zero_obligation_inventory_accept_follows_the_published_row() {
    let gap = PublishedRowTally::of(&[transport_native_verification_gap_row()], None);
    let clean = PublishedRowTally::of(&[transport_no_obligations_row()], None);
    // The live shape of the hole: calls undischarged, the gap row published.
    assert!(!zero_obligation_inventory_accepted(Some(false), gap));
    // The verdict alone refuses, whatever the rows say.
    assert!(!zero_obligation_inventory_accepted(Some(false), clean));
    // The belt: an `unknown` or timed-out published row refuses even a clean verdict.
    assert!(!zero_obligation_inventory_accepted(Some(true), gap));
    let mut timed_out = transport_no_obligations_row();
    timed_out.outcome = Outcome::Timeout;
    assert!(!zero_obligation_inventory_accepted(
        Some(true),
        PublishedRowTally::of(&[timed_out], None)
    ));
    // A body with bridged obligations never takes the empty-inventory accept.
    assert!(!zero_obligation_inventory_accepted(None, clean));
    // The genuine vacuous body still passes.
    assert!(zero_obligation_inventory_accepted(Some(true), clean));
}

/// F2 pin: strict batteries-on enforcement NEVER demotes, for every gap shape —
/// its transport rows stay byte-identical.
#[test]
fn strict_lane_never_demotes_any_gap() {
    for lowering_failed in [true, false] {
        for has_extern in [true, false] {
            for others_proved in [true, false] {
                assert_eq!(
                    default_lane_demotion_decision(
                        /*strict_enforcement=*/ true,
                        /*fmt_format_demotable=*/ false,
                        /*memory_safe=*/ true,
                        lowering_failed,
                        has_extern,
                        others_proved,
                    ),
                    DefaultLaneDemotion::None,
                    "strict lane must never demote a non-fmt::format gap (lowering_failed={lowering_failed}, has_extern={has_extern}, others_proved={others_proved})"
                );
            }
        }
    }
}

