// ---------------------------------------------------------------------------
// Trust (wave-3): the BV legacy-row decoder. `formula_from_trust_spec_expr` /
// `reconstruct_obligation_violation_formula` must decode the payload schema's
// bitvector fragment FAITHFULLY (the decoded formula is what the kernel
// re-certifies and what the vacuity precheck inspects before ANY proof
// authority mints) and fail closed on every node they cannot reverse exactly.
// ---------------------------------------------------------------------------

/// A minimal obligation whose only proof-relevant content is the typed
/// `trust.vc.formula.payload` metadata entry built from `predicate`.
fn obligation_with_formula_payload(
    predicate: &trust_verifier_api::TrustSpecPredicate,
) -> trust_verifier_api::TrustObligation {
    trust_verifier_api::TrustObligation {
        obligation_id: "vc:demo:arithmetic_safety:0".to_string(),
        kind: trust_verifier_api::ObligationKind::Custom {
            namespace: "trust.vc.test".to_string(),
            name: "arithmetic_safety".to_string(),
        },
        contract_id: None,
        proof_item_id: None,
        source: trust_verifier_api::SourceLocation::default(),
        description: "decoder round-trip".to_string(),
        required_strength: None,
        summary_facts: Vec::new(),
        metadata: vec![
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_SCHEMA_METADATA_KEY.to_string(),
                value: trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION.to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY.to_string(),
                value: serde_json::to_string(predicate).expect("TrustSpecPredicate serializes"),
            },
        ],
    }
}

#[test]
fn bv_payload_reconstructs_the_real_violation_formula() {
    use trust_verifier_api::{
        TrustSpecBinaryOp as Bin, TrustSpecBvBinaryOp as BvBin, TrustSpecBvUnaryOp as BvUn,
        TrustSpecExpr, TrustSpecSort, TrustSpecVariable, TrustSpecVariableOrigin,
    };

    // The float-overflow witness residue shape (`a + b: f64`): sign bits agree
    // AND the left operand's exponent is finite — pure QF_BV over BitVec(64)
    // parameter leaves, exactly what vcgen emits and PDR proves.
    let bv64 = TrustSpecSort::BitVec { width: 64 };
    let lhs = TrustSpecExpr::variable("_1", bv64);
    let rhs = TrustSpecExpr::variable("_2", bv64);
    let sign_bit = |operand: &TrustSpecExpr| {
        TrustSpecExpr::bv_unary(BvUn::Extract { high: 63, low: 63 }, operand.clone(), 1)
    };
    let root = TrustSpecExpr::binary(
        Bin::And,
        TrustSpecExpr::binary(Bin::Eq, sign_bit(&lhs), sign_bit(&rhs)),
        TrustSpecExpr::bv_binary(
            BvBin::Ult,
            TrustSpecExpr::bv_unary(BvUn::Extract { high: 62, low: 52 }, lhs.clone(), 11),
            TrustSpecExpr::bitvec_literal("2047", 11),
            11,
        ),
    );
    let predicate = trust_verifier_api::TrustSpecPredicate::new(
        root,
        vec![
            TrustSpecVariable {
                name: "_1".to_string(),
                sort: bv64,
                origin: TrustSpecVariableOrigin::Local { index: 1 },
            },
            TrustSpecVariable {
                name: "_2".to_string(),
                sort: bv64,
                origin: TrustSpecVariableOrigin::Local { index: 2 },
            },
        ],
    );

    let formula =
        reconstruct_obligation_violation_formula(&obligation_with_formula_payload(&predicate))
            .expect("a BV-payload row must keep its REAL violation formula, not the placeholder");

    let bx = Box::new;
    let var64 = |name: &str| bx(Formula::Var(name.to_string(), trust_types::Sort::BitVec(64)));
    let expected = Formula::And(vec![
        Formula::Eq(
            bx(Formula::BvExtract { inner: var64("_1"), high: 63, low: 63 }),
            bx(Formula::BvExtract { inner: var64("_2"), high: 63, low: 63 }),
        ),
        Formula::BvULt(
            bx(Formula::BvExtract { inner: var64("_1"), high: 62, low: 52 }),
            bx(Formula::BitVec { value: 2047, width: 11 }),
            11,
        ),
    ]);
    assert_eq!(formula, expected);
    // The exact veto this decoder removes: a reconstructed BV row is opaque to
    // the boolean-skeleton evaluator, so the vacuity precheck inside
    // `build_result_proof_authorities` passes instead of vetoing the proof.
    assert!(!trust_router::constant_folder::violation_formula_is_vacuously_unsat(&formula));
}

#[test]
fn bv_payload_conversions_and_arithmetic_decode_faithfully() {
    use trust_verifier_api::{
        TrustSpecBinaryOp as Bin, TrustSpecBvBinaryOp as BvBin, TrustSpecBvUnaryOp as BvUn,
        TrustSpecExpr, TrustSpecSort,
    };

    // (bv2nat(bvadd(int2bv(n, 8), #x01)) == 0) ∧ bvslt(sign_extend(bvnot(x)), 0)
    // — exercises BvFromInt, IntFromBv (unsigned flag threaded), BV arithmetic,
    // BvNot, SignExt, a signed comparison, and BitVec literals in one predicate.
    let bv8 = TrustSpecSort::BitVec { width: 8 };
    let sum = TrustSpecExpr::bv_binary(
        BvBin::Add,
        TrustSpecExpr::bv_from_int(TrustSpecExpr::variable("n", TrustSpecSort::Int), 8),
        TrustSpecExpr::bitvec_literal("1", 8),
        8,
    );
    let widened_not = TrustSpecExpr::bv_unary(
        BvUn::SignExt { extend_by: 8 },
        TrustSpecExpr::bv_unary(BvUn::Not, TrustSpecExpr::variable("x", bv8), 8),
        16,
    );
    let root = TrustSpecExpr::binary(
        Bin::And,
        TrustSpecExpr::binary(
            Bin::Eq,
            TrustSpecExpr::int_from_bv(sum, false, 8),
            TrustSpecExpr::int_literal("0"),
        ),
        TrustSpecExpr::bv_binary(
            BvBin::Slt,
            widened_not,
            TrustSpecExpr::bitvec_literal("0", 16),
            16,
        ),
    );

    let formula = formula_from_trust_spec_expr(&root).expect("the composite BV shape decodes");

    let bx = Box::new;
    let expected = Formula::And(vec![
        Formula::Eq(
            bx(Formula::BvToInt(
                bx(Formula::BvAdd(
                    bx(Formula::IntToBv(
                        bx(Formula::Var("n".to_string(), trust_types::Sort::Int)),
                        8,
                    )),
                    bx(Formula::BitVec { value: 1, width: 8 }),
                    8,
                )),
                8,
                false,
            )),
            bx(Formula::Int(0)),
        ),
        Formula::BvSLt(
            bx(Formula::BvSignExt(
                bx(Formula::BvNot(
                    bx(Formula::Var("x".to_string(), trust_types::Sort::BitVec(8))),
                    8,
                )),
                8,
            )),
            bx(Formula::BitVec { value: 0, width: 16 }),
            16,
        ),
    ]);
    assert_eq!(formula, expected);
}

#[test]
fn undecodable_node_inside_bv_payload_keeps_the_fail_closed_placeholder() {
    use trust_verifier_api::{TrustSpecBvBinaryOp as BvBin, TrustSpecExpr, TrustSpecSort};

    // `old(x)` has no `Formula` inverse. The WHOLE row must fail closed (`None`
    // → the caller keeps `Bool(false)`), never a guessed sub-formula.
    let bv64 = TrustSpecSort::BitVec { width: 64 };
    let root = TrustSpecExpr::bv_binary(
        BvBin::Ult,
        TrustSpecExpr::old(TrustSpecExpr::variable("x", bv64)),
        TrustSpecExpr::bitvec_literal("5", 64),
        64,
    );
    let predicate = trust_verifier_api::TrustSpecPredicate::new(root, Vec::new());
    assert_eq!(
        reconstruct_obligation_violation_formula(&obligation_with_formula_payload(&predicate)),
        None,
    );
}

#[test]
fn ugt_uge_payload_nodes_fail_closed() {
    use trust_verifier_api::{TrustSpecBvBinaryOp as BvBin, TrustSpecExpr, TrustSpecSort};

    // No `Formula` produces `Ugt`/`Uge`, so a payload containing one cannot be
    // the encoder's image — the decoder must refuse it rather than guess an
    // operand-swapped equivalent.
    let bv64 = TrustSpecSort::BitVec { width: 64 };
    for op in [BvBin::Ugt, BvBin::Uge] {
        let root = TrustSpecExpr::bv_binary(
            op,
            TrustSpecExpr::variable("x", bv64),
            TrustSpecExpr::variable("y", bv64),
            64,
        );
        assert_eq!(formula_from_trust_spec_expr(&root), None, "{op:?} must fail closed");
    }
}

#[test]
fn malformed_bv_payload_sort_disagreement_fails_closed() {
    use trust_verifier_api::{
        TrustSpecBvBinaryOp as BvBin, TrustSpecBvUnaryOp as BvUn, TrustSpecExpr, TrustSpecExprKind,
        TrustSpecSort,
    };

    let bv = |width: u32| TrustSpecSort::BitVec { width };
    let var64 = TrustSpecExpr::variable("x", bv(64));

    // (a) literal whose node sort disagrees with its stamped width.
    let lying_literal = TrustSpecExpr {
        sort: bv(8),
        kind: TrustSpecExprKind::BitVecLiteral { value: "1".to_string(), width: 16 },
    };
    assert_eq!(formula_from_trust_spec_expr(&lying_literal), None);

    // (b) extract whose stamped width disagrees with the slice `[3:0]`.
    let lying_extract = TrustSpecExpr {
        sort: bv(5),
        kind: TrustSpecExprKind::BvUnary {
            op: BvUn::Extract { high: 3, low: 0 },
            expr: Box::new(var64.clone()),
            width: 5,
        },
    };
    assert_eq!(formula_from_trust_spec_expr(&lying_extract), None);

    // (c) sign-extension by zero (the encoder refuses to produce it).
    let zero_extend = TrustSpecExpr {
        sort: bv(64),
        kind: TrustSpecExprKind::BvUnary {
            op: BvUn::SignExt { extend_by: 0 },
            expr: Box::new(var64.clone()),
            width: 64,
        },
    };
    assert_eq!(formula_from_trust_spec_expr(&zero_extend), None);

    // (d) binary comparison whose operand widths disagree with the op width.
    let mismatched_compare = TrustSpecExpr {
        sort: TrustSpecSort::Bool,
        kind: TrustSpecExprKind::BvBinary {
            op: BvBin::Ult,
            lhs: Box::new(TrustSpecExpr::variable("narrow", bv(32))),
            rhs: Box::new(var64),
            width: 64,
        },
    };
    assert_eq!(formula_from_trust_spec_expr(&mismatched_compare), None);

    // (e) non-decimal literal text (never encoder-produced).
    assert_eq!(formula_from_trust_spec_expr(&TrustSpecExpr::bitvec_literal("0x1f", 8)), None);
}

#[test]
fn non_bool_root_bv_payload_fails_closed() {
    use trust_verifier_api::TrustSpecExpr;

    // A decodable BV node, but a BitVec-sorted ROOT is not a proposition — the
    // compiler encoder only ever mints Bool roots, so this is a foreign payload.
    let predicate = trust_verifier_api::TrustSpecPredicate::new(
        TrustSpecExpr::bitvec_literal("7", 64),
        Vec::new(),
    );
    assert_eq!(
        reconstruct_obligation_violation_formula(&obligation_with_formula_payload(&predicate)),
        None,
    );
}

#[test]
fn bool_literal_payload_still_maps_to_the_placeholder() {
    use trust_verifier_api::TrustSpecExpr;

    // must-NOT twin: widening the decoder must not start treating the literal
    // `Bool(false)` bookkeeping placeholder as a reconstructable real formula.
    let predicate =
        trust_verifier_api::TrustSpecPredicate::new(TrustSpecExpr::bool_literal(false), Vec::new());
    assert_eq!(
        reconstruct_obligation_violation_formula(&obligation_with_formula_payload(&predicate)),
        None,
    );
}

// ---------------------------------------------------------------------------
// Trust (wave-3): the derived-total certificate fallback row must be explicit
// evidence that stays fail-closed in every consumer.
// ---------------------------------------------------------------------------

#[test]
fn derived_total_certificate_row_is_explicit_and_fail_closed() {
    let row = transport_derived_total_certificate_row();
    assert_eq!(row.kind, "derived-total-certificate");
    assert_eq!(row.outcome, Outcome::Unknown);
    assert_eq!(row.solver, "trust-compiler");
    // Every fail-closed consumer must stay engaged: the row blocks extern-call
    // demotion, folds into the native-lowering assumption collapse (it is not a
    // proof or refutation that must survive), and is not mistaken for the
    // absent-callee panic class.
    assert!(transport_row_blocks_extern_call_demotion(&row));
    assert!(!native_lowering_collapse_keeps_row(&row));
    assert!(!transport_row_is_unproved_assumption_panic(&row));
}

#[test]
fn derived_total_fallback_summary_shape_stays_fatal_under_strict() {
    // must-NOT twin: the certificate fallback keeps `summary.total == 0` and
    // `full_verification: None`, and that zero-inventory shape must REMAIN a
    // strict-lane failure (skipped: 1) — the explicit certificate row is
    // evidence, never proof credit, so a derived body that genuinely cannot
    // lower must not become silently green.
    let summary = TrustFunctionSummary {
        total: 0,
        trusted: 0,
        certified: 0,
        cached: 0,
        failed: 0,
        unknown: 0,
        runtime_checked: 0,
        max_level: TrustProofLevel::None,
    };
    // Mirror `derived_total_artifacts` exactly: the certificate is the whole
    // transport inventory, while no native result, binding, or proof-authority
    // row exists that could authenticate it as proof credit.
    let transport_results = [transport_derived_total_certificate_row()];
    let results: [(VerificationCondition, VerificationResult); 0] = [];
    let result_bindings: [Option<ResultObligationBinding>; 0] = [];
    let proof_authorities: [Option<ResultProofAuthority>; 0] = [];
    let failure = full_verification_failure(
        &summary,
        &transport_results,
        &results,
        &result_bindings,
        &proof_authorities,
    )
    .expect("the zero-inventory certificate fallback must stay a strict failure");
    assert_eq!(
        failure,
        FullVerificationFailure { failed: 0, unknown: 0, runtime_checked: 0, skipped: 1 },
    );
    // `false` — the DEFAULT policy — is the load-bearing case: this asserts the
    // zero-inventory certificate fallback stays fatal even under the tolerant
    // policy, which is the one a real build runs.
    assert!(strict_failure_is_fatal(failure, false));
}

// ---------------------------------------------------------------------------
// Trust #540 / composition review 2026-07-18 — R1 flip-seam hardening + C2
// mint guards. Finding (c): the narrowed-ambiguity refusal (proved co-matches
// must not shrink the MF-1 population to a single wrong row); finding (a):
// the designed R1-establisher exclusion in the ensures-marker mint; finding
// (b): the authored-clause cross-check.
// ---------------------------------------------------------------------------

fn r1_test_var(name: &str) -> trust_types::Formula {
    trust_types::Formula::Var(name.to_string(), trust_types::Sort::Int)
}

/// `P = (name != 0)` — the shape the R1 harvest's `¬V`/proposer lane gates to
/// parameter-only variables.
fn r1_test_nonzero_assumption(name: &str) -> trust_types::Formula {
    trust_types::Formula::Not(Box::new(trust_types::Formula::Eq(
        Box::new(r1_test_var(name)),
        Box::new(trust_types::Formula::Int(0)),
    )))
}

#[test]
fn r1_flip_decision_refuses_multiple_unproved_matches_regardless_of_binding() {
    // MF-1 is independent of the narrowed-binding predicate: >= 2 unproved
    // key-sharers refuse even if the certificate would "bind" one of them.
    assert_eq!(r1_flip_decision(2, &[4, 7], |_| true), R1FlipDecision::RefuseAmbiguous);
    assert_eq!(r1_flip_decision(3, &[0, 1, 2], |_| true), R1FlipDecision::RefuseAmbiguous);
}

#[test]
fn r1_flip_decision_narrowed_two_row_key_refuses_when_unbound() {
    // THE finding-(c) regression shape: a two-row key where one row is already
    // proved (full-lane bridge / `promote_kernel_certifiable` run BEFORE the
    // flip seam). The old unproved-only match set saw a single row and flipped
    // it — the proved row HID the ambiguity MF-1 would have refused. The
    // narrowed case now requires the certificate to bind the sole unproved
    // row; unbound refuses.
    assert_eq!(r1_flip_decision(2, &[5], |_| false), R1FlipDecision::RefuseNarrowed);
    assert_eq!(r1_flip_decision(4, &[9], |_| false), R1FlipDecision::RefuseNarrowed);
}

#[test]
fn r1_flip_decision_narrowed_two_row_key_applies_when_bound() {
    // The `flip_caller_covered`/`flip_private_reachable` per-key layout: a
    // proved co-match (the division's other vcgen encoding, natively proved)
    // plus the single unproved isolated row, with the certificate's assumption
    // connected to that row — the sole-unproved-match rule admits the flip.
    assert_eq!(
        r1_flip_decision(2, &[5], |index| {
            assert_eq!(index, 5, "binding must be evaluated on the sole unproved row");
            true
        }),
        R1FlipDecision::Apply(5)
    );
}

#[test]
fn r1_flip_decision_unique_match_does_not_consult_binding() {
    // A unique key match that is the sole unproved row is unambiguous by
    // construction — the pre-review behavior, preserved bit-for-bit (the
    // binding predicate must not even run: pre-opt/post-opt formula drift on
    // the general single-match population must not regress admitted flips).
    assert_eq!(
        r1_flip_decision(1, &[3], |_| unreachable!(
            "unique key match must not consult the narrowed-binding predicate"
        )),
        R1FlipDecision::Apply(3)
    );
}

#[test]
fn r1_flip_decision_without_unproved_matches_is_no_target() {
    // No key match at all, and the all-matches-already-proved population: in
    // both cases there is nothing to discharge (a flip onto a proved row would
    // be a no-op and the sealed token stays unconsumed).
    assert_eq!(r1_flip_decision(0, &[], |_| true), R1FlipDecision::NoTarget);
    assert_eq!(r1_flip_decision(3, &[], |_| true), R1FlipDecision::NoTarget);
}

#[test]
fn r1_narrowed_binding_connects_assumption_to_row_operand() {
    // P = divisor != 0 over the parameter base name; the row's per-body vcgen
    // formula carries SSA-versioned spellings (`divisor#s0_1`). The
    // version-stripped base-name comparison binds them.
    let p = r1_test_nonzero_assumption("divisor");
    let row = trust_types::Formula::And(vec![
        trust_types::Formula::Eq(
            Box::new(r1_test_var("_3#s0_1")),
            Box::new(trust_types::Formula::Bool(true)),
        ),
        trust_types::Formula::Eq(
            Box::new(r1_test_var("divisor#s0_1")),
            Box::new(trust_types::Formula::Int(0)),
        ),
    ]);
    assert!(r1_narrowed_flip_assumption_binds_row(&p, Some(&row)));
}

#[test]
fn r1_narrowed_binding_refuses_macro_twin_over_different_operand() {
    // The finding-(c) hazard scenario: the certificate was harvested for the
    // same-key operation over `b`; the sole unproved row is a DIFFERENT
    // operation over `d` (macro-twin spans sharing kind+file+line+col). P is
    // not connected to the row's violation, so the certificate cannot be the
    // one that discharges it — refuse.
    let p = r1_test_nonzero_assumption("b");
    let row = trust_types::Formula::Eq(
        Box::new(r1_test_var("d#s0_2")),
        Box::new(trust_types::Formula::Int(0)),
    );
    assert!(!r1_narrowed_flip_assumption_binds_row(&p, Some(&row)));
}

#[test]
fn r1_narrowed_binding_fails_closed_without_source_formula() {
    // Full-lane rows answer only through the recovered per-body vcgen formula
    // (`R1NativeRowFlipKey::source_formula`); recovery failure must refuse the
    // narrowed flip, never fall back to the transport placeholder.
    let p = r1_test_nonzero_assumption("b");
    assert!(!r1_narrowed_flip_assumption_binds_row(&p, None));
}

#[test]
fn r1_narrowed_binding_refuses_closed_assumption() {
    // A closed P constrains nothing row-distinguishing. Unreachable past the
    // mint's connectedness check, but the seam must not rely on that.
    assert!(!r1_narrowed_flip_assumption_binds_row(
        &trust_types::Formula::Bool(true),
        Some(&r1_test_var("divisor"))
    ));
}

#[test]
fn r1_variable_base_name_strips_version_tokens_only() {
    assert_eq!(r1_variable_base_name("divisor#s0_1"), "divisor");
    assert_eq!(r1_variable_base_name("divisor"), "divisor");
    assert_eq!(r1_variable_base_name("_4#s0_3_s1_0"), "_4");
}

#[test]
fn r1_recursive_callsite_inventory_is_exact_and_multiplicity_preserving() {
    let span = |line| trust_types::SourceSpan {
        file: "src/lib.rs".to_string(),
        line_start: line,
        col_start: 4,
        line_end: line,
        col_end: 12,
    };
    let first = span(10);
    let second = span(20);

    assert!(exact_callsite_span_multiset_matches(
        &[first.clone(), first.clone(), second.clone()],
        &[second.clone(), first.clone(), first.clone()],
    ));
    assert!(
        !exact_callsite_span_multiset_matches(
            &[first.clone(), first.clone()],
            std::slice::from_ref(&first),
        ),
        "one produced row must not discharge two same-span recursive calls",
    );
    assert!(
        !exact_callsite_span_multiset_matches(
            std::slice::from_ref(&first),
            &[first.clone(), second],
        ),
        "an extra producer row must not enter the sealed recursive proof",
    );
}

/// UX contract of the crate-level R1 scan-gap warning: it is a raw `dcx`
/// warning (deliberately not a lint, so `-Dwarnings` cannot fail a sound
/// build), which also means `-Awarnings`/`#[allow]` cannot silence it — so it
/// must NEVER fire on a compile in which no verdict was withheld. A crate that
/// merely contains a `global_asm!` item (scan poisoned) but proves every
/// Level-0 obligation compiles without it; the poison's cause is stated exactly
/// when its effect (a kept non-proved verdict) was felt. The positive half is
/// pinned end-to-end by tests/ui/trust/r1/reject_global_asm_names_reason.rs.
#[test]
fn r1_scan_gap_warning_requires_a_withheld_verdict() {
    // Poisoned scan, fully-proved crate: SILENT — this is the ordinary-source
    // UX regression case (trust-verify defaults to On).
    assert!(!r1_scan_gap_warning_applies(true, false));
    // Un-poisoned scan never warns, withheld verdict or not.
    assert!(!r1_scan_gap_warning_applies(false, false));
    assert!(!r1_scan_gap_warning_applies(false, true));
    // Poisoned scan AND a withheld verdict: the cause must be stated.
    assert!(r1_scan_gap_warning_applies(true, true));
}

/// Budget and worker-limit arithmetic decides when the pass stops asking
/// solvers questions. A saturating or silently-defaulting bound would turn a
/// configured budget into the built-in one and change which obligations get
/// answered at all, so the clamping edges are pinned here.
mod runtime_config_tests {
    use super::*;

    #[test]
    fn zero_function_budget_disables_deadline() {
        assert!(verify_fn_deadline_from_ms(0, std::time::Instant::now()).is_none());
    }

    /// gate-rca deadline (2026-10-17): the native lane may spend half of what is left of
    /// the function clock when it starts, so the certifying lanes after it keep the other
    /// half; no clock, no cutoff; a passed deadline leaves the native lane nothing.
    /// Negative control: the cutoff is strictly before a live deadline, so a lane that
    /// ran to it would still leave the certifying lanes time.
    #[test]
    fn the_native_lane_cutoff_is_half_of_what_is_left() {
        let now = std::time::Instant::now();
        let deadline = now + std::time::Duration::from_secs(120);
        let cutoff = native_lane_cutoff(now, Some(deadline)).expect("a clock has a cutoff");
        assert_eq!(cutoff, now + std::time::Duration::from_secs(60));
        assert!(cutoff < deadline, "the certifying lanes keep a share");
        assert_eq!(native_lane_cutoff(now, None), None, "no function clock, no cutoff");
        let passed = now.checked_sub(std::time::Duration::from_millis(5)).unwrap_or(now);
        assert_eq!(
            native_lane_cutoff(now, Some(passed)),
            Some(now),
            "a passed deadline leaves the native lane nothing"
        );
    }

    #[test]
    fn huge_function_budget_clamps_without_becoming_the_default() {
        let now = std::time::Instant::now();
        let deadline = verify_fn_deadline_from_ms(u64::MAX, now)
            .expect("a positive configured budget must produce a deadline");
        let default_ms =
            rustc_session::config::Options::default().unstable_opts.trust_verify_function_budget_ms;

        assert!(
            deadline > now + std::time::Duration::from_millis(default_ms),
            "an overflowing huge budget must not silently shrink to the 120-second default"
        );
    }

    #[test]
    fn solver_timeout_is_capped_by_remaining_function_budget() {
        let now = std::time::Instant::now();
        let deadline = now + std::time::Duration::from_millis(37);
        assert_eq!(remaining_solver_timeout_ms(500, Some(deadline), now), Some(37));
        assert_eq!(remaining_solver_timeout_ms(11, Some(deadline), now), Some(11));
        assert_eq!(remaining_solver_timeout_ms(500, None, now), Some(500));
    }

    #[test]
    fn expired_function_budget_starts_no_new_solver_query() {
        let now = std::time::Instant::now();
        let expired = now.checked_sub(std::time::Duration::from_millis(1)).unwrap();
        assert_eq!(remaining_solver_timeout_ms(500, Some(expired), now), None);
    }

    #[test]
    fn sub_millisecond_remaining_budget_still_gets_one_millisecond() {
        let now = std::time::Instant::now();
        let deadline = now + std::time::Duration::from_nanos(1);
        assert_eq!(remaining_solver_timeout_ms(500, Some(deadline), now), Some(1));
    }

    #[test]
    fn full_verifier_worker_limit_is_capped_to_resource_limit_width() {
        assert_eq!(verify_worker_thread_limit_from(4), Some(4));
        assert_eq!(verify_worker_thread_limit_from(256), Some(256));
        assert_eq!(verify_worker_thread_limit_from(usize::from(u16::MAX) + 1), None);
        assert_eq!(verify_worker_thread_limit_from(0), None);
        assert_eq!(verify_worker_thread_limit_from(1), Some(1));
    }

    #[test]
    fn full_verifier_context_carries_deadline_and_worker_limit() {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        let context = full_verifier_execution_context_from("run-limited", Some(deadline), Some(2));

        assert_eq!(context.deadline(), Some(deadline));
        assert_eq!(context.limits.worker_threads, Some(2));
    }

    #[test]
    fn full_verifier_context_applies_positive_worker_cap() {
        let worker_threads = verify_worker_thread_limit_from(3);
        let context = full_verifier_execution_context_from("run-worker-cap", None, worker_threads);

        assert_eq!(context.limits.worker_threads, Some(3));
    }

    #[test]
    fn full_verifier_context_ignores_zero_worker_cap() {
        for configured in [0] {
            let worker_threads = verify_worker_thread_limit_from(configured);
            let context =
                full_verifier_execution_context_from("run-default-workers", None, worker_threads);

            assert!(context.limits.worker_threads.is_none());
            assert!(!context.limits.has_any_limit());
        }
    }

    #[test]
    fn full_verifier_context_stays_unlimited_without_worker_limit() {
        let context = full_verifier_execution_context_from("run-unlimited", None, None);

        assert!(context.deadline().is_none());
        assert!(!context.limits.has_any_limit());
    }

    #[test]
    fn full_verifier_run_id_is_canonical_for_impl_def_paths() {
        let run_id = full_verifier_run_id("<demo::Button as demo::sealed::Widget>::rank");
        let context = full_verifier_execution_context_from(run_id, None, None);
        let bundle = trust_verifier_api::TrustContractBundle::empty(
            "bundle-run-id-test",
            trust_verifier_api::BundleSubject::Function {
                crate_name: "demo".to_string(),
                path: "<demo::Button as demo::sealed::Widget>::rank".to_string(),
            },
        );
        let result = trust_router::FullVerificationEngine::with_required_native_engines()
            .verify_bundle(&bundle, &context);

        result
            .validate_derived_state()
            .expect("compiler-generated impl run IDs must form canonical verifier envelopes");
    }
}

/// Trust: the producer half of the loop-elided-refutation fix.
///
/// The defect these pin: a TRUE `ensures(*ret >= 0)` on
/// `fn f(n: i32) -> i32 { let mut i = 0; while i < n { i = i + 1; } i }` was
/// published as `verified_counterexample = true`. The postcondition VC took the
/// flattened single-formula typed-CHC arm — one nullary `error` relation, one
/// constraint-only rule, no loop transition relation — so the loop-carried `i`
/// was a free variable and the solver satisfied the query by choosing a value
/// the program cannot produce. These tests fix WHEN the compiler discloses that,
/// because the consumer gate in trust-bmc can only act on rows that carry it.
mod trust_mc_typed_chc_encoding_fidelity {
    use super::*;

    fn obligation_with_metadata(
        kind: trust_verifier_api::ObligationKind,
        metadata: Vec<trust_verifier_api::MetadataEntry>,
    ) -> trust_verifier_api::TrustObligation {
        trust_verifier_api::TrustObligation {
            obligation_id: "vc:demo__f:postcondition:1".to_string(),
            kind,
            contract_id: None,
            proof_item_id: None,
            source: trust_verifier_api::SourceLocation::default(),
            description: "postcondition".to_string(),
            required_strength: None,
            summary_facts: Vec::new(),
            metadata,
        }
    }

    fn fidelity_of(obligation: &trust_verifier_api::TrustObligation) -> Option<&str> {
        api_obligation_metadata_value(obligation, TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_METADATA_KEY)
    }

    fn spec_var(name: &str) -> trust_verifier_api::TrustSpecExpr {
        trust_verifier_api::TrustSpecExpr {
            sort: trust_verifier_api::TrustSpecSort::Int,
            kind: trust_verifier_api::TrustSpecExprKind::Variable { name: name.to_string() },
        }
    }
    fn spec_int(value: i64) -> trust_verifier_api::TrustSpecExpr {
        trust_verifier_api::TrustSpecExpr {
            sort: trust_verifier_api::TrustSpecSort::Int,
            kind: trust_verifier_api::TrustSpecExprKind::IntLiteral { value: value.to_string() },
        }
    }
    fn spec_bin(
        op: trust_verifier_api::TrustSpecBinaryOp,
        lhs: trust_verifier_api::TrustSpecExpr,
        rhs: trust_verifier_api::TrustSpecExpr,
    ) -> trust_verifier_api::TrustSpecExpr {
        trust_verifier_api::TrustSpecExpr {
            sort: trust_verifier_api::TrustSpecSort::Bool,
            kind: trust_verifier_api::TrustSpecExprKind::Binary {
                op,
                lhs: Box::new(lhs),
                rhs: Box::new(rhs),
            },
        }
    }
    fn spec_eq(
        lhs: trust_verifier_api::TrustSpecExpr,
        rhs: trust_verifier_api::TrustSpecExpr,
    ) -> trust_verifier_api::TrustSpecExpr {
        spec_bin(trust_verifier_api::TrustSpecBinaryOp::Eq, lhs, rhs)
    }
    fn spec_and(
        lhs: trust_verifier_api::TrustSpecExpr,
        rhs: trust_verifier_api::TrustSpecExpr,
    ) -> trust_verifier_api::TrustSpecExpr {
        spec_bin(trust_verifier_api::TrustSpecBinaryOp::And, lhs, rhs)
    }
    fn predicate_of(
        root: trust_verifier_api::TrustSpecExpr,
    ) -> trust_verifier_api::TrustSpecPredicate {
        trust_verifier_api::TrustSpecPredicate::new(root, Vec::new())
    }
    fn params(names: &[&str]) -> trust_types::fx::FxHashSet<String> {
        names.iter().map(|n| (*n).to_string()).collect()
    }

    /// The minimum a `VerifiableFunction` needs for `verifiable_body_is_acyclic`
    /// to answer, in the two shapes that matter: `Goto -> Return` (acyclic) and
    /// `Goto -> Goto` back to the entry (one back edge). Both terminators are ones
    /// the acyclicity walk models, so it answers `Some(_)` rather than declining.
    pub(super) fn cfg_shaped_function(cyclic: bool) -> trust_types::VerifiableFunction {
        use trust_types::{BasicBlock, BlockId, LocalDecl, Terminator, Ty};
        trust_types::VerifiableFunction {
            name: "demo::f".into(),
            def_path: "demo::f".into(),
            span: SourceSpan::default(),
            body: trust_types::VerifiableBody {
                locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
                blocks: vec![
                    BasicBlock {
                        id: BlockId(0),
                        stmts: Vec::new(),
                        terminator: Terminator::Goto(BlockId(1)),
                    },
                    BasicBlock {
                        id: BlockId(1),
                        stmts: Vec::new(),
                        terminator: if cyclic {
                            Terminator::Goto(BlockId(0))
                        } else {
                            Terminator::Return
                        },
                    },
                ],
                arg_count: 0,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// The measured F shape: the return place is defined by the loop-carried
    /// local, and NOTHING defines that local, so the refutation picks a value no
    /// execution reaches.
    #[test]
    fn return_defined_by_an_undefined_loop_local_is_disclosed() {
        let root = spec_and(
            spec_eq(spec_var("_5"), spec_var("i#s0_1_s3_0")),
            spec_eq(spec_var("_0"), spec_var("i#s0_1_s3_0")),
        );
        assert!(
            typed_chc_return_depends_on_elided_definition(
                &predicate_of(root),
                &params(&["n", "_1"])
            ),
            "`_0 = i#…` with no defining equality for `i#…` is an elided definition"
        );
    }

    /// THE REGRESSION THE FUNCTION-SCOPED VERSION CAUSED. A loop local IS
    /// unconstrained, but the return place is defined by a PARAMETER, so the
    /// counterexample is one a caller can actually supply.
    /// `{ let mut i = 0; while i < 3 { i = i + 1; } n }` with `ensures(*ret >= 5)`
    /// really is defective at `n = 0` and must keep refuting; keying on the
    /// function's back edge demoted it and took >=16 falsification mutants along.
    #[test]
    fn return_defined_by_a_parameter_keeps_its_refutation_despite_a_loop_local() {
        let root = spec_and(
            spec_eq(spec_var("_5"), spec_var("i#s0_1_s3_0")),
            spec_eq(spec_var("_0"), spec_var("n")),
        );
        assert!(
            !typed_chc_return_depends_on_elided_definition(
                &predicate_of(root),
                &params(&["n", "_1"])
            ),
            "an unconstrained loop local the RETURN VALUE never reads must not cost \
             this refutation its authority"
        );
    }

    /// The exact acyclic encoding — every non-input defined. This lane's entire
    /// bug-detection value lives here and must be untouched.
    #[test]
    fn exact_acyclic_encoding_is_not_disclosed() {
        let root = spec_and(
            spec_eq(spec_var("_0"), spec_var("n")),
            spec_bin(trust_verifier_api::TrustSpecBinaryOp::Ge, spec_var("_0"), spec_int(5)),
        );
        assert!(!typed_chc_return_depends_on_elided_definition(
            &predicate_of(root),
            &params(&["n", "_1"])
        ));
    }

    /// Fails toward NOT disclosing: no anchor for the conclusion, no claim.
    #[test]
    fn an_unanchored_return_place_discloses_nothing() {
        let root = spec_eq(spec_var("_7"), spec_var("i#s0_1_s3_0"));
        assert!(!typed_chc_return_depends_on_elided_definition(
            &predicate_of(root),
            &params(&["n"])
        ));
    }

    #[test]
    fn loopy_body_on_the_flattened_arm_is_disclosed_as_over_approximation() {
        let mut obligation =
            obligation_with_metadata(trust_verifier_api::ObligationKind::Postcondition, Vec::new());
        // `return_depends_on_elided_definition` is true, so the `exact` arm is not
        // reached and the CFG/payload arguments cannot affect this row. The cyclic
        // shape is passed anyway so the fixture matches the case being named.
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(true),
            None,
            &params(&[]),
            true,
            true,
            false,
        );

        assert_eq!(
            fidelity_of(&obligation),
            Some(TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_LOOP_ELIDED),
            "a loop-carrying body on the flattened single-formula CHC must disclose that its \
             encoding over-approximates; without the disclosure trust-bmc credits the \
             refutation and a true postcondition is reported false"
        );
    }

    #[test]
    fn acyclic_body_is_not_disclosed_and_keeps_its_refutation_authority() {
        // The cost control: an acyclic body must not be disclosed, because disclosing it
        // too would turn every genuine straight-line contract violation into `unknown`.
        //
        // WHAT THIS TEST DOES NOT ESTABLISH, corrected 2026-09-26. It used to justify
        // itself with "the flattened single-formula CHC is EXACT for an acyclic body —
        // every non-input variable is defined by the path constraints". That is FALSE as a
        // general claim, and it is the sentence a future `exact` attestation would most
        // likely be built on, so it must not stand. `trust_verify.rs` names four
        // producer-side over-approximations that reach this very gate FROM AN ACYCLIC BODY
        // and "still arrive unattested and still refute": unmodeled call results, `&mut`
        // havoc, deref-store invalidation and opaque frames. On top of that,
        // `combine_relevant_block_defs_recorded` is documented as "a solver-performance
        // heuristic rather than a soundness gate" and is recorded as having left `x / 2`
        // unstated in the ACYCLIC `if x < 0 { 0 } else { x / 2 }`, making a true
        // `result >= 0` refutable; and `prune_unlowerable_conjuncts` drops whole conjuncts.
        //
        // So "acyclic" is NOT a sufficient exactness predicate. What this test pins is the
        // weaker, true thing: the DISCLOSURE is keyed on the groundedness of the return
        // place, and an acyclic body that grounds it is not stamped. Refutation authority
        // is a separate question and is fail-closed regardless — the positive `exact`
        // value the consumer needs is one the compiler is forbidden to emit
        // (crates/trust-bmc/src/verifier_api.rs:126-129), so today NOTHING in this lane
        // carries refutation authority, disclosed or not. See
        // docs/issues/2026-09-26-chc-refutation-authority-is-fail-closed-by-design.md.
        let mut obligation =
            obligation_with_metadata(trust_verifier_api::ObligationKind::Postcondition, Vec::new());
        // No payload is handed over, so the `exact` arm below declines for want of one
        // and this row is stamped with NOTHING — which is what "not disclosed" means
        // here. The `exact` arm's own positive and negative cases are the three tests
        // after this one; this test is about the absence of the LOOP_ELIDED stamp.
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(false),
            None,
            &params(&[]),
            true,
            false,
            false,
        );

        assert_eq!(fidelity_of(&obligation), None);
    }

    /// The POSITIVE case for the `exact` arm, which had no test at all until
    /// 2026-09-27. The arm may only fire where the flattened single-formula CHC is
    /// what was actually submitted (an acyclic body) AND the payload grounds every
    /// name it mentions, so a refutation cannot have picked a value no execution
    /// reaches.
    #[test]
    fn an_acyclic_body_whose_payload_determines_every_name_is_stamped_exact() {
        let mut obligation =
            obligation_with_metadata(trust_verifier_api::ObligationKind::Postcondition, Vec::new());
        let payload = predicate_of(spec_and(
            spec_eq(spec_var("_0"), spec_var("n")),
            spec_bin(trust_verifier_api::TrustSpecBinaryOp::Ge, spec_var("_0"), spec_int(5)),
        ));
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(false),
            Some(&payload),
            &params(&["n"]),
            true,
            false,
            false,
        );

        assert_eq!(
            fidelity_of(&obligation),
            Some(TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_EXACT),
            "an acyclic body whose payload grounds every mentioned name is the one shape \
             this attestation is allowed to describe"
        );
    }

    /// The payload half of the gate, on its own. Same acyclic body; one mentioned
    /// name (the loop-carried local) is grounded by nothing, so the formula does not
    /// determine it and no attestation may be written.
    #[test]
    fn an_acyclic_body_whose_payload_leaves_a_name_undetermined_is_not_stamped() {
        let mut obligation =
            obligation_with_metadata(trust_verifier_api::ObligationKind::Postcondition, Vec::new());
        let payload = predicate_of(spec_eq(spec_var("_0"), spec_var("i#s0_1_s3_0")));
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(false),
            Some(&payload),
            &params(&["n"]),
            true,
            false,
            false,
        );

        assert_eq!(fidelity_of(&obligation), None);
    }

    /// The CFG half of the gate, on its own. The payload is the determining one from
    /// the positive test; only the back edge differs. A looping body does not take the
    /// flattened arm at all, so an exactness claim about that arm's artifact would be
    /// a claim about an encoding that was never submitted.
    #[test]
    fn a_cyclic_body_is_never_stamped_exact() {
        let mut obligation =
            obligation_with_metadata(trust_verifier_api::ObligationKind::Postcondition, Vec::new());
        let payload = predicate_of(spec_and(
            spec_eq(spec_var("_0"), spec_var("n")),
            spec_bin(trust_verifier_api::TrustSpecBinaryOp::Ge, spec_var("_0"), spec_int(5)),
        ));
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(true),
            Some(&payload),
            &params(&["n"]),
            true,
            false,
            false,
        );

        assert_ne!(fidelity_of(&obligation), Some(TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_EXACT));
    }

    #[test]
    fn whole_function_panic_freedom_aggregate_is_never_stamped() {
        // Two reasons, both load-bearing. It routes to the STRUCTURAL whole-CFG
        // CHC, which carries real per-block relations, so the disclosure would
        // be false. And its identity is fixed by exact-shape gates
        // (`obligation_is_synthesized_whole_function_panic_freedom` here,
        // `obligation_is_whole_function_panic_freedom` in trust-bmc) whose
        // metadata allowlists do NOT include this key and must stay closed —
        // they gate a PROOF credit, and nothing in this fix may widen one.
        let mut obligation = obligation_with_metadata(
            trust_verifier_api::ObligationKind::Assertion,
            vec![trust_verifier_api::MetadataEntry {
                key: TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY.to_string(),
                value: "true".to_string(),
            }],
        );
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &cfg_shaped_function(false),
            None,
            &params(&[]),
            false,
            true,
            false,
        );

        assert_eq!(fidelity_of(&obligation), None);
        assert!(
            obligation
                .metadata
                .iter()
                .all(|entry| { entry.key != TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_METADATA_KEY }),
            "stamping this key on the panic-freedom aggregate would break its exact-shape gate"
        );
    }
}

/// Trust (measurement, 2026-08-08): what the enriched data-flow CFG-CHC actually
/// produces for the SHAPE THE COMPILER'S OWN PRODUCER EMITS.
///
/// The existing `dataflow_*` tests above hand-build functions whose NON-ENTRY
/// blocks carry SSA block params (`bb1` in `dataflow_encoder_fires_on_invoke_
/// function` declares one, and the `Invoke` threads an arg into it). No function
/// the compiler lowers has that shape. `crates/trust-ir-bridge/src/lower.rs`
/// gives block params ONLY to the entry block, and `block_args_for` returns an
/// empty arg list for every non-entry target, because the bridge has no
/// phi/block-param merge at all. Its cross-block merge is MEMORY:
/// `multi_block_written_locals` promotes any local written in two or more
/// reachable blocks — every loop accumulator — into an `Alloca` read back with
/// `Load`, and trust-ir's own `mem2reg` is documented as "the conservative no-phi
/// subset" that declines exactly the multi-block case.
///
/// So this module builds `fn f(n: i32) -> i32 { let mut i = 0; while i < n { i =
/// i + 1; } i }` the way the bridge really lowers it, and pins the consequence:
/// the enriched encoder DOES fire and DOES emit many relations and rules, but
/// every relation except the entry block's is NULLARY, and no value is threaded
/// across any edge. There is no loop-carried state for PDR to infer `i >= 0`
/// over — the enrichment is structural, not data-flow, on real input.
#[cfg(test)]
mod dataflow_chc_on_the_real_bridge_lowering_shape {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, OverflowOp,
        Ty, ValueId,
    };

    use super::*;

    /// `fn f(n: i32) -> i32 { let mut i = 0; while i < n { i = i + 1; } i }`,
    /// lowered the way `trust-ir-bridge` lowers it: `n` is the entry block's only
    /// param, `i` is a memory-promoted `Alloca` slot (written in bb0 and bb3 —
    /// two distinct blocks), every read of `i` is a `Load`, and NO non-entry
    /// block has params or receives edge args.
    fn bridge_shaped_counting_loop() -> Function {
        let n = ValueId::new(1);
        let slot = ValueId::new(10);
        let zero = ValueId::new(2);
        let load_guard = ValueId::new(3);
        let guard = ValueId::new(4);
        let load_body = ValueId::new(5);
        let one = ValueId::new(6);
        let sum = ValueId::new(7);
        let overflow_bit = ValueId::new(8);
        let load_exit = ValueId::new(9);

        let load = |dest: ValueId| {
            InstrNode::new(Inst::Load { ty: Ty::I32, ptr: slot, volatile: false, align: None })
                .with_result(dest)
        };
        let store = |value: ValueId| {
            InstrNode::new(Inst::Store {
                ty: Ty::I32,
                ptr: slot,
                value,
                volatile: false,
                align: None,
            })
        };

        // bb0(n: i32): %10 = alloca i32 ; %2 = 0 ; store %10 <- %2 ; br bb1
        let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32);
        bb0.body.push(
            InstrNode::new(Inst::Alloca { ty: Ty::I32, count: None, align: None })
                .with_result(slot),
        );
        bb0.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(0) }).with_result(zero),
        );
        bb0.body.push(store(zero));
        bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

        // bb1(): %3 = load %10 ; %4 = slt %3, %1 ; condbr %4 -> bb2, bb4
        let mut bb1 = Block::new(BlockId::new(1));
        bb1.body.push(load(load_guard));
        bb1.body.push(
            InstrNode::new(Inst::ICmp { op: ICmpOp::Slt, ty: Ty::I32, lhs: load_guard, rhs: n })
                .with_result(guard),
        );
        bb1.body.push(InstrNode::new(Inst::CondBr {
            cond: guard,
            then_target: BlockId::new(2),
            then_args: vec![],
            else_target: BlockId::new(4),
            else_args: vec![],
        }));

        // bb2(): %5 = load %10 ; %6 = 1 ; %7,%8 = add.overflow i32 %5,%6 ;
        //        condbr %8 -> bb5 (panic), bb3
        let mut bb2 = Block::new(BlockId::new(2));
        bb2.body.push(load(load_body));
        bb2.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(1) }).with_result(one),
        );
        bb2.body.push(
            InstrNode::new(Inst::Overflow {
                op: OverflowOp::AddOverflow,
                ty: Ty::I32,
                lhs: load_body,
                rhs: one,
            })
            .with_results([sum, overflow_bit]),
        );
        bb2.body.push(InstrNode::new(Inst::CondBr {
            cond: overflow_bit,
            then_target: BlockId::new(5),
            then_args: vec![],
            else_target: BlockId::new(3),
            else_args: vec![],
        }));

        // bb3(): store %10 <- %7 ; br bb1     (the BACK EDGE)
        let mut bb3 = Block::new(BlockId::new(3));
        bb3.body.push(store(sum));
        bb3.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

        // bb4(): %9 = load %10 ; return %9
        let mut bb4 = Block::new(BlockId::new(4));
        bb4.body.push(load(load_exit));
        bb4.body.push(InstrNode::new(Inst::Return { values: vec![load_exit] }));

        // bb5(): unreachable   (the checked-arithmetic panic sink)
        let mut bb5 = Block::new(BlockId::new(5));
        bb5.body.push(InstrNode::new(Inst::Unreachable));

        let mut function =
            Function::new(FuncId::new(0), "demo::f", FuncTyId::new(0), BlockId::new(0));
        function.blocks = vec![bb0, bb1, bb2, bb3, bb4, bb5];
        function
    }

    /// Every SSA value that any rule threads through a RELATION ARGUMENT
    /// (in a head application or a body premise). This is exactly the set of
    /// values that can appear in a PDR invariant — anything outside it is
    /// rule-local and existentially quantified.
    fn values_carried_in_relation_arguments(rules: &serde_json::Value) -> BTreeSet<String> {
        fn note(args: Option<&Vec<serde_json::Value>>, carried: &mut BTreeSet<String>) {
            for arg in args.into_iter().flatten() {
                if let Some(name) = arg.get("name").and_then(|name| name.as_str()) {
                    carried.insert(name.to_string());
                }
            }
        }
        let mut carried = BTreeSet::new();
        for rule in rules.as_array().into_iter().flatten() {
            note(rule["head"].get("args").and_then(|args| args.as_array()), &mut carried);
            note(
                rule["body"]["relation"].get("args").and_then(|args| args.as_array()),
                &mut carried,
            );
        }
        carried
    }

    /// SUPERSEDES `the_lever_fires_but_carries_no_loop_state` (2026-08-08).
    ///
    /// That test recorded a DEFECT as a measurement: on this exact fixture every
    /// relation except the entry block's was nullary and the only value any
    /// relation carried was the entry parameter `v1`, so `i >= 0` was not
    /// expressible over any predicate and PDR had nothing to strengthen. The
    /// defect is fixed (`ChcDataflowFrame`), so its assertions are now FALSE and
    /// keeping them would pin the bug. They are replaced here by the inverted
    /// claims, over the same fixture and the same measurement helper — strictly
    /// stronger: the accumulator is now a relation column, not absent from every
    /// relation.
    #[test]
    fn the_lever_now_carries_the_loop_accumulator() {
        let function = bridge_shaped_counting_loop();
        assert!(
            super::super::function_has_back_edge(&function),
            "the redirect's own loop gate must see this function as loopy"
        );

        let (relations, rules, _vars) = super::super::trust_mc_dataflow_chc_for_function(
            &function,
            super::super::ChcErrorMode::Structural,
            None,
        )
        .expect("well-formed function")
        .expect("the enriched encoder DOES fire on this shape");

        // Unchanged: it is a transition system by the counts the redirect is
        // judged on.
        let relations = relations.as_array().expect("relations array");
        assert_eq!(relations.len(), 7, "error + one relation per block: {relations:?}");
        assert!(
            rules.as_array().expect("rules array").len() > 1,
            "many rules, not the single flattened constraint-only rule"
        );

        // CHANGED: bb1..bb4 all sit on the loop and must now carry the promoted
        // `i` slot; bb0 still carries `n`. bb5 — the `Unreachable` panic sink —
        // stays nullary on purpose: nothing downstream of it can read anything,
        // so backward liveness drops every column there. That is a dropped dead
        // column, not a dropped fact.
        for relation in relations {
            let name = relation["name"].as_str().unwrap_or_default();
            if name == "error" || name == "bb5" {
                continue;
            }
            assert!(
                relation["arg_sorts"].as_array().is_some_and(|args| !args.is_empty()),
                "{name} must carry loop-carried state, not be nullary: {relation:?}"
            );
        }
        assert_eq!(
            relations.iter().find(|relation| relation["name"] == "bb5").expect("bb5 relation")["arg_sorts"],
            serde_json::json!([]),
            "the panic sink observes nothing, so it carries nothing"
        );

        // RESTORED PIN (collateral of the supersession, not part of it). The test
        // this one replaced asserted the ENTRY relation's exact arity and sort,
        // `bb0 == [int]`. Only the loop-state claim was inverted by the change;
        // the entry relation still carries exactly `n` and nothing else, and
        // relaxing that to "non-empty" above would let a bug that gave bb0
        // spurious extra columns, or that dropped `n`'s sort, pass unnoticed.
        assert_eq!(
            relations.iter().find(|relation| relation["name"] == "bb0").expect("bb0 relation")["arg_sorts"],
            serde_json::json!([{ "kind": "int" }]),
            "the entry block carries exactly the entry parameter `n`, as an Int"
        );

        // CHANGED, and this is the decisive one. The loop-carried `i` is now a
        // RELATION ARGUMENT — a per-block cell column the back edge updates — so
        // `i >= 0` is expressible as an invariant over bb1/bb2/bb3/bb4 and PDR
        // has something to strengthen. `v1` (the entry param) is still threaded.
        let carried = values_carried_in_relation_arguments(&rules);
        assert!(carried.contains("v1"), "the entry parameter stays threaded: {carried:?}");
        let cell_columns: BTreeSet<&String> =
            carried.iter().filter(|name| name.contains("_cell_v10")).collect();
        assert!(
            cell_columns.len() >= 4,
            "the `i` slot (%10) must be a relation column on every block that is not its \
             defining block: {carried:?}"
        );
        // The increment crosses bb2 -> bb3 as an SSA value, so it is threaded too;
        // without that the back edge would pass a FREE value and the cell column
        // would be havoc'd again one edge later.
        assert!(
            carried.contains("v7"),
            "the incremented value must be threaded from the block that computes it to the \
             block that stores it: {carried:?}"
        );

        // RESTORED PIN, second half. The superseded test pinned the carried set by
        // EQUALITY (`{"v1"}`); `contains` alone would not notice a value threaded
        // that has no business being threaded. Equality on the new set would be
        // brittle — the cell columns are named after a slot index — so the
        // characterization is closed instead. Every carried name must be one of:
        //   * `v1` — the entry parameter `n`;
        //   * `v2` — the `Const 0` bb0 stores into the slot, which the bb0 -> bb1
        //     edge passes as bb1's cell column, i.e. `i`'s INITIAL value;
        //   * `v7` — the increment, crossing bb2 -> bb3 (the block that computes
        //     it to the block that stores it);
        //   * a column of the ONE promoted slot, `%10`.
        // In particular no SECOND slot may be promoted, and no unrelated value may
        // acquire a relation column.
        for name in &carried {
            assert!(
                name == "v1" || name == "v2" || name == "v7" || name.contains("_cell_v10"),
                "unexpected value threaded into a relation argument: {name} in {carried:?}"
            );
        }
        // The set is exactly those, so a DROPPED thread is caught too, not only an
        // added one — this is the equality the superseded test had.
        assert_eq!(
            carried,
            ["bb1_cell_v10", "bb2_cell_v10", "bb3_cell_v10", "bb4_cell_v10", "v1", "v2", "v7"]
                .into_iter()
                .map(str::to_string)
                .collect::<BTreeSet<String>>(),
            "the carried set is pinned exactly: entry param, initial value, increment, cells"
        );
    }

    #[test]
    fn the_arithmetic_safety_redirect_would_refute_a_correct_loop_and_now_falls_back() {
        let function = bridge_shaped_counting_loop();

        // The pre-existing coverage gate PASSES — nothing about this function's
        // arithmetic surface is unmodeled — so it is not what protects us here.
        assert!(
            super::super::function_overflow_surface_fully_modeled(&function),
            "checked i32 add + loads/stores are all inside the modeled surface"
        );

        // What is wrong is the other direction. The `Overflow`'s left operand is
        // a havoc'd `Load` result: it is in no relation argument and no fold
        // equality defines it. `error :- bb2(), fold, v5 + 1 > i32::MAX` is then
        // satisfiable by choosing v5 = i32::MAX, so the enriched CHC reports a
        // counterexample for a loop that provably never overflows.
        let loop_body = function.block(trust_ir::BlockId::new(2)).expect("bb2");
        assert!(
            !super::super::block_overflow_violations_are_anchored(loop_body),
            "the checked add's operand is an unconstrained existential"
        );

        // So the redirect must fail CLOSED to the untouched flattened path
        // rather than publish that counterexample.
        assert!(
            super::super::trust_mc_dataflow_chc_for_function(
                &function,
                super::super::ChcErrorMode::ArithmeticSafetyOnly,
                None,
            )
            .expect("well-formed function")
            .is_none(),
            "an unanchored overflow violation must fall back, not refute"
        );
    }

    #[test]
    fn an_anchored_overflow_still_encodes() {
        // Regression guard for the gate above: when the operands ARE anchored
        // (here, the entry block's own param), the enriched encoding is
        // unchanged and still emits its violation edge.
        let a = ValueId::new(0);
        let value = ValueId::new(2);
        let bit = ValueId::new(3);
        let mut bb0 = Block::new(BlockId::new(0)).with_param(a, Ty::I32);
        bb0.body.push(
            InstrNode::new(Inst::Overflow {
                op: OverflowOp::AddOverflow,
                ty: Ty::I32,
                lhs: a,
                rhs: a,
            })
            .with_results([value, bit]),
        );
        bb0.body.push(InstrNode::new(Inst::Return { values: vec![] }));
        let mut function =
            Function::new(FuncId::new(0), "demo::anchored", FuncTyId::new(0), BlockId::new(0));
        function.blocks = vec![bb0];

        assert!(super::super::function_overflow_violations_are_anchored(&function));
        let (_relations, rules, _vars) = super::super::trust_mc_dataflow_chc_for_function(
            &function,
            super::super::ChcErrorMode::ArithmeticSafetyOnly,
            None,
        )
        .expect("well-formed function")
        .expect("an anchored overflow keeps its enriched encoding");
        assert!(
            rules
                .as_array()
                .expect("rules array")
                .iter()
                .any(|rule| rule["head"]["name"] == "error"),
            "the overflow violation edge is still emitted: {rules:?}"
        );
    }
}

/// Trust (2026-08-08): the elided-definition disclosure must not be suppressed
/// by an env flag that does not decide whether the row is actually flattened.
#[cfg(test)]
mod dataflow_redirect_never_suppresses_the_elided_definition_disclosure {
    use super::*;

    #[test]
    fn an_arithmetic_safety_row_is_disclosed_regardless_of_the_dataflow_gate() {
        // The suppression that used to live in
        // `annotate_trust_mc_typed_chc_encoding_fidelity` fired on
        // (env gate ON && kind == ArithmeticSafety) alone. It matched neither of
        // the redirect's two remaining preconditions — the function must have a
        // back edge, and the enriched builder must not have returned `Ok(None)` —
        // so a straight-line row, or any row the coverage/anchoring gates reject,
        // fell back to the flattened formula with its disclosure stripped and its
        // refutation authority restored. The annotation no longer reads the
        // environment at all: whether it discloses is decided solely by whether
        // the return place depends on an elided definition.
        let mut obligation = trust_verifier_api::TrustObligation {
            obligation_id: "vc:demo__f:arithmetic_safety:1".to_string(),
            kind: trust_verifier_api::ObligationKind::ArithmeticSafety,
            contract_id: None,
            proof_item_id: None,
            source: trust_verifier_api::SourceLocation::default(),
            description: "arithmetic safety".to_string(),
            required_strength: None,
            summary_facts: Vec::new(),
            metadata: Vec::new(),
        };
        annotate_trust_mc_typed_chc_encoding_fidelity(
            &mut obligation,
            &super::trust_mc_typed_chc_encoding_fidelity::cfg_shaped_function(true),
            None,
            &Default::default(),
            true,
            true,
            false,
        );
        assert_eq!(
            api_obligation_metadata_value(
                &obligation,
                TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_METADATA_KEY,
            ),
            Some(TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_LOOP_ELIDED),
            "a flattened loop-elided ArithmeticSafety row must keep its disclosure"
        );
    }
}

// ---------------------------------------------------------------------------
// LOOP-CARRIED STATE in the enriched CFG-CHC.
//
// The subject is F:
//
//     #[ensures(move |ret: &i32| *ret >= 0)]
//     pub fn f(n: i32) -> i32 { let mut i: i32 = 0; while i < n { i = i + 1; } i }
//
// which is TRUE and which the encoder could not express before: the producer
// (`trust-ir-bridge`) gives block params only to the entry block and routes `i`
// through an `Alloca`/`Store`/`Load` memory merge, so every non-entry relation
// was NULLARY and `_0` came out of a havoc'd `Load` — a free variable a solver
// may pick adversarially.
//
// These fixtures deliberately go through the REAL producer
// (`trust_ir_bridge::lower_mir_compat_to_trust_ir`) rather than hand-building a
// `trust_ir::Function`: the earlier `dataflow_*` tests hand-built functions whose
// NON-ENTRY blocks carry params, a shape the compiler never emits, which is
// exactly why the nullary-relation defect went unnoticed.
// ---------------------------------------------------------------------------

/// F's body in the compiler's own MIR model, in the shape rustc actually emits
/// for a checked `i = i + 1` inside a `while`:
///
/// ```text
/// bb0: _2 = const 0                       ; goto bb1
/// bb1: _3 = Lt(_2, _1)                    ; switchInt(_3) -> [0: bb4, else: bb2]
/// bb2: _4 = CheckedAdd(_2, const 1)       ; assert(!(_4.1)) -> bb3
/// bb3: _2 = move (_4.0)                   ; goto bb1
/// bb4: _0 = copy _2                       ; return
/// ```
///
/// `_2` is written in bb0 AND bb3, so `multi_block_written_locals` promotes it to
/// an `Alloca` slot — the loop-carried cell this encoding has to thread. The
/// checked add is what splits the increment (bb2) from the write-back (bb3), so
/// the sum ALSO has to cross a block boundary; it does so inside a tuple built by
/// `Undef`/`InsertField` and read back by `ExtractField`.
fn dataflow_loop_accumulator_function() -> trust_types::VerifiableFunction {
    let span = trust_types::SourceSpan::default();
    trust_types::VerifiableFunction {
        name: "f".to_string(),
        def_path: "demo::f".to_string(),
        span: span.clone(),
        body: trust_types::VerifiableBody {
            locals: vec![
                trust_types::LocalDecl { index: 0, ty: trust_types::Ty::i32(), name: None },
                trust_types::LocalDecl {
                    index: 1,
                    ty: trust_types::Ty::i32(),
                    name: Some("n".to_string()),
                },
                trust_types::LocalDecl {
                    index: 2,
                    ty: trust_types::Ty::i32(),
                    name: Some("i".to_string()),
                },
                trust_types::LocalDecl { index: 3, ty: trust_types::Ty::Bool, name: None },
                trust_types::LocalDecl {
                    index: 4,
                    ty: trust_types::Ty::Tuple(vec![trust_types::Ty::i32(), trust_types::Ty::Bool]),
                    name: None,
                },
            ],
            blocks: vec![
                trust_types::BasicBlock {
                    id: trust_types::BlockId(0),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(2),
                        rvalue: trust_types::Rvalue::Use(trust_types::Operand::Constant(
                            trust_types::ConstValue::Int(0),
                        )),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::Goto(trust_types::BlockId(1)),
                },
                trust_types::BasicBlock {
                    id: trust_types::BlockId(1),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(3),
                        rvalue: trust_types::Rvalue::BinaryOp(
                            trust_types::BinOp::Lt,
                            trust_types::Operand::Copy(trust_types::Place::local(2)),
                            trust_types::Operand::Copy(trust_types::Place::local(1)),
                        ),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::SwitchInt {
                        discr: trust_types::Operand::Copy(trust_types::Place::local(3)),
                        targets: vec![(0, trust_types::BlockId(4))],
                        otherwise: trust_types::BlockId(2),
                        exhaustive_enum_unreachable: false,
                        span: span.clone(),
                    },
                },
                trust_types::BasicBlock {
                    id: trust_types::BlockId(2),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(4),
                        rvalue: trust_types::Rvalue::CheckedBinaryOp(
                            trust_types::BinOp::Add,
                            trust_types::Operand::Copy(trust_types::Place::local(2)),
                            trust_types::Operand::Constant(trust_types::ConstValue::Int(1)),
                        ),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::Assert {
                        cond: trust_types::Operand::Copy(trust_types::Place::field(4, 1)),
                        expected: false,
                        msg: trust_types::AssertMessage::Overflow(trust_types::BinOp::Add),
                        target: trust_types::BlockId(3),
                        span: span.clone(),
                        unwind: trust_types::UnwindEdge::Unreachable,
                    },
                },
                trust_types::BasicBlock {
                    id: trust_types::BlockId(3),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(2),
                        rvalue: trust_types::Rvalue::Use(trust_types::Operand::Move(
                            trust_types::Place::field(4, 0),
                        )),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::Goto(trust_types::BlockId(1)),
                },
                trust_types::BasicBlock {
                    id: trust_types::BlockId(4),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(0),
                        rvalue: trust_types::Rvalue::Use(trust_types::Operand::Copy(
                            trust_types::Place::local(2),
                        )),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::Return,
                },
            ],
            arg_count: 1,
            return_ty: trust_types::Ty::i32(),
            datatype_defs: Default::default(),
        },
        contracts: Vec::new(),
        preconditions: Vec::new(),
        postconditions: Vec::new(),
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

/// Lower [`dataflow_loop_accumulator_function`] with the real producer and
/// return its single trust-ir function.
fn dataflow_loop_accumulator_trust_ir() -> trust_ir::Function {
    let module =
        trust_ir_bridge::lower_mir_compat_to_trust_ir(&dataflow_loop_accumulator_function())
            .expect("the loop fixture must lower through the real MIR->trust-ir bridge");
    module.functions.into_iter().next().expect("the bridge emits one function")
}

/// Every var name a `{kind:...}` expression reads.
fn dataflow_expr_vars(expr: &serde_json::Value, out: &mut Vec<String>) {
    match expr["kind"].as_str() {
        Some("var") => {
            if let Some(name) = expr["name"].as_str() {
                out.push(name.to_string());
            }
        }
        Some("binary") => {
            dataflow_expr_vars(&expr["lhs"], out);
            dataflow_expr_vars(&expr["rhs"], out);
        }
        Some("unary") => dataflow_expr_vars(&expr["expr"], out),
        _ => {}
    }
}

/// Least-fixed-point GROUNDEDNESS over one rule: starting from the vars its body
/// relation binds (a rule's ONLY bound vars — everything else is universally
/// quantified, i.e. free for the solver to choose), close over the rule's
/// defining equalities `x = E`. A var outside the result is one the solver may
/// pick adversarially.
fn dataflow_grounded_vars(
    relation_args: &[serde_json::Value],
    constraints: &[serde_json::Value],
) -> std::collections::BTreeSet<String> {
    let mut grounded: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    for arg in relation_args {
        dataflow_expr_vars(arg, &mut Vec::new());
        if let Some(name) = arg["name"].as_str() {
            grounded.insert(name.to_string());
        }
    }
    let mut changed = true;
    while changed {
        changed = false;
        for constraint in constraints {
            if constraint["kind"] != "binary" || constraint["op"] != "eq" {
                continue;
            }
            let Some(defined) = constraint["lhs"]["name"].as_str() else { continue };
            if constraint["lhs"]["kind"] != "var" || grounded.contains(defined) {
                continue;
            }
            let mut reads = Vec::new();
            dataflow_expr_vars(&constraint["rhs"], &mut reads);
            if reads.iter().all(|name| grounded.contains(name)) {
                grounded.insert(defined.to_string());
                changed = true;
            }
        }
    }
    grounded
}

#[test]
fn dataflow_threads_the_loop_accumulator_through_non_entry_relations() {
    // (a) The loop cell IS a relation argument in a non-entry block. Before the
    // loop-carried-state frame, every relation except the entry block was
    // NULLARY (`arg_sorts == []`) and the only value threaded anywhere was the
    // entry parameter — so `i >= 0` was not expressible over ANY predicate and
    // PDR had nothing to strengthen.
    let function = dataflow_loop_accumulator_trust_ir();
    let (relations, rules, vars) =
        super::trust_mc_dataflow_chc_for_function(&function, super::ChcErrorMode::Structural, None)
            .expect("a well-formed loop must not error")
            .expect("the enriched encoder MUST fire for the bridge's own loop shape");

    let relations = relations.as_array().expect("relations array");
    let nullary: Vec<&str> = relations
        .iter()
        .filter(|relation| relation["name"] != "error")
        .filter(|relation| relation["arg_sorts"].as_array().is_none_or(|args| args.is_empty()))
        .filter_map(|relation| relation["name"].as_str())
        .collect();
    assert!(
        nullary.is_empty(),
        "every block relation must carry loop-carried state; these are still nullary: {nullary:?} \
         (relations: {relations:?})"
    );

    // The cell column is named after the slot, per block, so a rule can tie a
    // block's INCOMING slot value to its successor's.
    let cell_columns: Vec<&str> = vars
        .iter()
        .filter_map(|var| var["name"].as_str())
        .filter(|name| name.contains("_cell_v"))
        .collect();
    assert!(
        !cell_columns.is_empty(),
        "the un-aliased `let mut i` slot must be promoted to threaded cell columns; vars: {vars:?}"
    );

    // The back edge must UPDATE the cell rather than pass it through: some rule
    // whose head is the loop header carries a cell argument that is NOT the
    // source block's incoming cell column.
    let rules = rules.as_array().expect("rules array");
    let back_edge_updates = rules.iter().any(|rule| {
        let Some(body_relation) = rule["body"]["relation"]["name"].as_str() else { return false };
        let head_args: Vec<&str> = rule["head"]["args"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|a| a["name"].as_str())
            .collect();
        let body_args: Vec<&str> = rule["body"]["relation"]["args"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|a| a["name"].as_str())
            .collect();
        rule["head"]["name"] != "error"
            && rule["head"]["name"] != body_relation
            && head_args.iter().any(|name| !name.contains("_cell_v"))
            && body_args.iter().any(|name| name.contains("_cell_v"))
            && head_args != body_args
    });
    assert!(
        back_edge_updates,
        "some transition must pass a STORED value where the target expects its cell column \
         (that update is what makes `i` loop-carried): {rules:?}"
    );
}

#[test]
fn dataflow_grounds_the_returned_value_in_the_loop_cell() {
    // (b) + (c). Build the encoding for the return block exactly as a
    // postcondition routing would — the block's relation premise plus its
    // straight-line fold — and check that the RETURNED value is grounded in the
    // relation's own arguments. `error :- bbRet(args), fold, NOT(ret >= 0)` is
    // then NOT satisfiable by a free choice of `ret`: its value is pinned by an
    // equality chain rooted in the relation arguments, so whether `error` is
    // reachable is decided by what invariant holds of the CELL COLUMN — which is
    // the question PDR is for.
    //
    // Before the loop-carried-state frame this failed: `ret` was the result of a
    // havoc'd `Load`, so `v_0 = -1` satisfied the rule and routing the
    // postcondition would have published a refutation of a TRUE contract.
    let function = dataflow_loop_accumulator_trust_ir();
    let frame = super::ChcDataflowFrame::build(&function, &[]);
    let mut var_decls = super::ChcVarDecls::default();

    let return_block = function
        .blocks
        .iter()
        .find(|block| {
            matches!(&block.terminator().map(|t| &t.inst), Some(trust_ir::Inst::Return { .. }))
        })
        .expect("the fixture returns");
    let returned = match &return_block.terminator().expect("terminator").inst {
        trust_ir::Inst::Return { values } => *values.first().expect("returns one value"),
        _ => unreachable!(),
    };

    let relation_args = frame.relation_arg_exprs(return_block, &mut var_decls);
    let fold = super::chc_fold_block_body(return_block, &frame, &mut var_decls);
    let grounded = dataflow_grounded_vars(&relation_args, &fold.constraints);

    let returned_name = super::chc_value_var_name(returned);
    assert!(
        grounded.contains(&returned_name),
        "the returned value `{returned_name}` must be GROUNDED in the return block's relation \
         arguments — otherwise `error :- bbRet(args), fold, NOT({returned_name} >= 0)` is \
         satisfiable by free choice. grounded={grounded:?} args={relation_args:?} \
         fold={:?}",
        fold.constraints
    );

    // It is grounded THROUGH the promoted cell, not through anything else: the
    // return block's relation carries exactly the slot column.
    let arg_names: Vec<&str> =
        relation_args.iter().filter_map(|arg| arg["name"].as_str()).collect();
    assert!(
        arg_names.iter().any(|name| name.contains("_cell_v")),
        "the return block's relation must carry the promoted slot: {arg_names:?}"
    );

    // CONTROL that must not regress: grounding must not PIN the returned value
    // to a constant. `ensures(*ret >= 5)` over the same loop is FALSE, and its
    // error rule has to stay satisfiable — which it does exactly because the cell
    // column is a free relation argument whose value the transitions, not this
    // rule, determine. If any constraint here fixed the cell to a literal, a
    // false postcondition would become unrefutable.
    for constraint in &fold.constraints {
        if constraint["kind"] == "binary"
            && constraint["op"] == "eq"
            && let Some(defined) = constraint["lhs"]["name"].as_str()
            && arg_names.contains(&defined)
        {
            panic!(
                "no fold constraint may define a relation ARGUMENT — that would pin the \
                 loop-carried state and could make a false postcondition unrefutable: \
                 {constraint:?}"
            );
        }
    }
}

#[test]
fn dataflow_refuses_to_promote_a_slot_whose_address_escapes() {
    // The promotion is sound ONLY because it is refused whenever the slot's
    // address could escape: a hidden write through an alias would change the slot
    // without a `Store` the fold can see, and the threaded column would then
    // assert something the real semantics does not entail — the false-SAFE
    // direction. Passing the address to a call is the canonical escape.
    use trust_ir::{Block, BlockId, FuncId, FuncTyId, Function, Inst, InstrNode, Ty, ValueId};

    let build = |escapes: bool| {
        let slot = ValueId::new(0);
        let stored = ValueId::new(1);
        let loaded = ValueId::new(2);
        let mut bb0 = Block::new(BlockId::new(0));
        bb0.body.push(
            InstrNode::new(Inst::Alloca { ty: Ty::I32, count: None, align: None })
                .with_result(slot),
        );
        bb0.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: trust_ir::Constant::Int(0) })
                .with_result(stored),
        );
        bb0.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: slot,
            value: stored,
            volatile: false,
            align: None,
        }));
        if escapes {
            // `takes_ptr(&mut i)` — the address is now observable by a callee.
            bb0.body.push(InstrNode::new(Inst::Call { callee: FuncId::new(1), args: vec![slot] }));
        }
        bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

        let mut bb1 = Block::new(BlockId::new(1));
        bb1.body.push(
            InstrNode::new(Inst::Load { ty: Ty::I32, ptr: slot, volatile: false, align: None })
                .with_result(loaded),
        );
        bb1.body.push(InstrNode::new(Inst::Return { values: vec![loaded] }));

        let mut function =
            Function::new(FuncId::new(0), "demo::slot", FuncTyId::new(0), BlockId::new(0));
        function.blocks = vec![bb0, bb1];
        function
    };

    let kept = build(false);
    assert_eq!(
        super::ChcDataflowFrame::build(&kept, &[]).cells.len(),
        1,
        "a slot used only as a same-typed, non-volatile Load/Store `ptr` operand is promotable"
    );

    let escaped = build(true);
    assert!(
        super::ChcDataflowFrame::build(&escaped, &[]).cells.is_empty(),
        "a slot whose address is passed to a call MUST keep today's havoc — promoting it would \
         assert that no hidden write can change it, which is exactly what the escape allows"
    );
}

/// BMC-LANE-1: the complete constructor is an enumerated READ of every lane, so a
/// slot whose address is packed into one — at any lane, not only the first —
/// escapes with the aggregate exactly as a call argument does. A
/// `MakeAggregate { .. } => false` arm (no lane reads) would keep the slot
/// promoted while the callee writes through the packed pointer: the false-SAFE
/// direction. The control packs only unrelated scalars and keeps the slot.
#[test]
fn dataflow_refuses_to_promote_a_slot_whose_address_is_packed_into_a_complete_constructor() {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, Inst, InstrNode, Ty, ValueId,
    };

    let build = |pack_slot: bool| {
        let slot = ValueId::new(0);
        let stored = ValueId::new(1);
        let other = ValueId::new(2);
        let agg = ValueId::new(3);
        let loaded = ValueId::new(4);
        let mut bb0 = Block::new(BlockId::new(0));
        bb0.body.push(
            InstrNode::new(Inst::Alloca { ty: Ty::I32, count: None, align: None })
                .with_result(slot),
        );
        bb0.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(0) })
                .with_result(stored),
        );
        bb0.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: slot,
            value: stored,
            volatile: false,
            align: None,
        }));
        bb0.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(7) }).with_result(other),
        );
        let (ty, fields) = if pack_slot {
            // `g((7, &mut i))` with the reference spelled as the slot itself, the
            // way any trust-ir producer may legally spell it.
            (Ty::Tuple(vec![Ty::I32, Ty::Ptr]), vec![other, slot])
        } else {
            (Ty::Tuple(vec![Ty::I32, Ty::I32]), vec![other, other])
        };
        bb0.body.push(
            InstrNode::new(Inst::MakeAggregate { ty, variant: None, fields }).with_result(agg),
        );
        bb0.body.push(InstrNode::new(Inst::Call { callee: FuncId::new(1), args: vec![agg] }));
        bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

        let mut bb1 = Block::new(BlockId::new(1));
        bb1.body.push(
            InstrNode::new(Inst::Load { ty: Ty::I32, ptr: slot, volatile: false, align: None })
                .with_result(loaded),
        );
        bb1.body.push(InstrNode::new(Inst::Return { values: vec![loaded] }));

        let mut function =
            Function::new(FuncId::new(0), "demo::packed_slot", FuncTyId::new(0), BlockId::new(0));
        function.blocks = vec![bb0, bb1];
        function
    };

    assert_eq!(
        super::ChcDataflowFrame::build(&build(false), &[]).cells.len(),
        1,
        "a constructor of unrelated scalars beside the slot leaves it promotable"
    );
    assert!(
        super::ChcDataflowFrame::build(&build(true), &[]).cells.is_empty(),
        "a slot whose address is a constructor lane (lane 1) escapes with the aggregate: \
         promoting it would assert the callee cannot write it"
    );
}

/// A CHECKED counting loop with a real `Return`, self-contained so the goal-edge
/// tests do not reach into another module's fixture:
/// `fn f(n: i32) -> i32 { let mut i = 0; while i < n { i += 1; } i }`, lowered the
/// way the bridge lowers it — the accumulator lives in an `Alloca`, and the
/// checked add is `Overflow` + `Not` + a non-branching `Assert`.
fn postcondition_goal_counting_loop() -> trust_ir::Function {
    postcondition_goal_counting_loop_typed(trust_ir::Ty::I32, trust_ir::ICmpOp::Slt)
}

/// The same loop over an arbitrary scalar type/comparison — `U64`+`Ult` is the
/// shape the real bridge emits for `fn f(n: u64) -> u64`, which is what the
/// BV-domain goal-translation tests need (the i32 fixture exercises the Int-VC
/// lane).
fn postcondition_goal_counting_loop_typed(
    scalar: trust_ir::Ty,
    cmp: trust_ir::ICmpOp,
) -> trust_ir::Function {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, OverflowOp,
        Ty, ValueId,
    };
    let ty = scalar;
    let icmp_op = cmp;
    let n = ValueId::new(1);
    let zero = ValueId::new(2);
    let load_guard = ValueId::new(3);
    let guard = ValueId::new(4);
    let load_body = ValueId::new(5);
    let one = ValueId::new(6);
    let sum = ValueId::new(7);
    let bit = ValueId::new(8);
    let negated = ValueId::new(9);
    let slot = ValueId::new(10);
    let load_exit = ValueId::new(11);
    let false_const = ValueId::new(12);

    let load = |dest: ValueId| {
        InstrNode::new(Inst::Load { ty: ty.clone(), ptr: slot, volatile: false, align: None })
            .with_result(dest)
    };
    let store = |value: ValueId| {
        InstrNode::new(Inst::Store {
            ty: ty.clone(),
            ptr: slot,
            value,
            volatile: false,
            align: None,
        })
    };

    let mut bb0 = Block::new(BlockId::new(0)).with_param(n, ty.clone());
    bb0.body.push(
        InstrNode::new(Inst::Alloca { ty: ty.clone(), count: None, align: None }).with_result(slot),
    );
    bb0.body.push(
        InstrNode::new(Inst::Const { ty: ty.clone(), value: Constant::Int(0) }).with_result(zero),
    );
    bb0.body.push(store(zero));
    bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

    let mut bb1 = Block::new(BlockId::new(1));
    bb1.body.push(load(load_guard));
    bb1.body.push(
        InstrNode::new(Inst::ICmp { op: icmp_op, ty: ty.clone(), lhs: load_guard, rhs: n })
            .with_result(guard),
    );
    bb1.body.push(InstrNode::new(Inst::CondBr {
        cond: guard,
        then_target: BlockId::new(2),
        then_args: vec![],
        else_target: BlockId::new(3),
        else_args: vec![],
    }));

    let mut bb2 = Block::new(BlockId::new(2));
    bb2.body.push(load(load_body));
    bb2.body.push(
        InstrNode::new(Inst::Const { ty: ty.clone(), value: Constant::Int(1) }).with_result(one),
    );
    bb2.body.push(
        InstrNode::new(Inst::Overflow {
            op: OverflowOp::AddOverflow,
            ty: ty.clone(),
            lhs: load_body,
            rhs: one,
        })
        .with_result(sum)
        .with_result(bit),
    );
    // The bridge's real assert shape: `icmp eq %bit, false`, not `UnOp::Not`.
    bb2.body.push(
        InstrNode::new(Inst::Const { ty: Ty::Bool, value: Constant::Bool(false) })
            .with_result(false_const),
    );
    bb2.body.push(
        InstrNode::new(Inst::ICmp { op: ICmpOp::Eq, ty: Ty::Bool, lhs: bit, rhs: false_const })
            .with_result(negated),
    );
    bb2.body.push(InstrNode::new(Inst::Assert {
        cond: negated,
        kind: trust_ir::AssertKind::Unspecified,
        site: None,
    }));
    bb2.body.push(store(sum));
    bb2.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

    let mut bb3 = Block::new(BlockId::new(3));
    bb3.body.push(load(load_exit));
    bb3.body.push(InstrNode::new(Inst::Return { values: vec![load_exit] }));

    let mut function =
        Function::new(FuncId::new(0), "demo::counting", FuncTyId::new(0), BlockId::new(0));
    function.blocks.push(bb0);
    function.blocks.push(bb1);
    function.blocks.push(bb2);
    function.blocks.push(bb3);
    function
}

/// **THE POSTCONDITION COVERAGE GATE.** The encoder models every integer as a
/// mathematical `int`, which is a sound OVER-approximation of the machine only
/// while the two agree on executions the machine CONTINUES.
///
///   * checked arithmetic (`Overflow` + `Assert(Not(bit))`) is fine — on overflow
///     the real program panics and never returns, so the model merely explores a
///     superset of the real return states;
///   * a WRAPPING add is not: reality wraps to a negative value and RETURNS it,
///     while the model counts upward forever. The model is then a strict
///     UNDER-approximation and `ensures(*ret >= 0)` would be "proved" for a
///     function that demonstrably returns a negative number.
///
/// This is the false-SAFE direction, so the gate must refuse the second shape.
#[test]
fn the_postcondition_coverage_gate_refuses_unbounded_wrapping_arithmetic() {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, OverflowOp,
        Ty, ValueId,
    };

    // `checked`: %3,%4 = add.overflow %1,%2 ; %6 = false ; %5 = eq %4,%6 ;
    //            assert %5 ; return %3
    // `wrapping`: %3 = add %1,%2 ; return %3        <- the same sum, unchecked
    let build = |wrapping: bool, assert_the_bit: bool| {
        let n = ValueId::new(1);
        let one = ValueId::new(2);
        let sum = ValueId::new(3);
        let bit = ValueId::new(4);
        let negated = ValueId::new(5);
        let false_const = ValueId::new(6);
        let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32);
        bb0.body.push(
            InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(1) }).with_result(one),
        );
        if wrapping {
            bb0.body.push(
                InstrNode::new(Inst::BinOp {
                    op: trust_ir::BinOp::Add,
                    ty: Ty::I32,
                    lhs: n,
                    rhs: one,
                })
                .with_result(sum),
            );
        } else {
            bb0.body.push(
                InstrNode::new(Inst::Overflow {
                    op: OverflowOp::AddOverflow,
                    ty: Ty::I32,
                    lhs: n,
                    rhs: one,
                })
                .with_result(sum)
                .with_result(bit),
            );
            if assert_the_bit {
                // THE BRIDGE'S REAL SHAPE. `Terminator::Assert { expected: false }`
                // lowers to `icmp eq %bit, false` + `Assert` — deliberately NOT
                // `UnOp::Not` (`lower.rs`: "TrustIr unary `not` is a bitwise
                // integer op"). Writing this test with `UnOp::Not` is what let the
                // gate ship refusing every checked function in the real producer.
                bb0.body.push(
                    InstrNode::new(Inst::Const { ty: Ty::Bool, value: Constant::Bool(false) })
                        .with_result(false_const),
                );
                bb0.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Eq,
                        ty: Ty::Bool,
                        lhs: bit,
                        rhs: false_const,
                    })
                    .with_result(negated),
                );
                bb0.body.push(InstrNode::new(Inst::Assert {
                    cond: negated,
                    kind: trust_ir::AssertKind::Unspecified,
                    site: None,
                }));
            }
        }
        bb0.body.push(InstrNode::new(Inst::Return { values: vec![sum] }));
        let mut function =
            Function::new(FuncId::new(0), "demo::acc", FuncTyId::new(0), BlockId::new(0));
        function.blocks.push(bb0);
        function
    };

    assert!(
        super::function_unbounded_int_arithmetic_is_faithful(&build(false, true)),
        "checked arithmetic whose overflow bit is asserted-false traps on overflow, so the \
         unbounded model is a sound over-approximation and must be admitted"
    );
    assert!(
        !super::function_unbounded_int_arithmetic_is_faithful(&build(true, false)),
        "a WRAPPING add is modeled as unbounded `int`; the real negative return state is \
         absent from the model, so a false postcondition would be PROVED — refuse"
    );
    // `overflowing_add`: the bit is produced but nothing traps on it, so the real
    // program CONTINUES with the wrapped value. Same hazard, different shape.
    assert!(
        !super::function_unbounded_int_arithmetic_is_faithful(&build(false, false)),
        "an unasserted overflow bit means execution continues wrapped — refuse"
    );
}

/// The bridge does not hand the overflow flag straight to the assert: it packs
/// `Overflow`'s two results into a tuple (`Undef -> InsertField(_,0,result) ->
/// InsertField(_,1,flag)`) and reads the flag back with `ExtractField(tuple, 1)`,
/// often in a LATER block. The coverage gate has to follow that chain, or it
/// refuses every checked function the real producer emits — which is precisely
/// how the first version of this gate shipped inert.
#[test]
fn the_coverage_gate_follows_the_overflow_flag_through_the_tuple_chain() {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, OverflowOp,
        Ty, ValueId,
    };
    let n = ValueId::new(1);
    let one = ValueId::new(2);
    let sum = ValueId::new(3);
    let flag = ValueId::new(4);
    let undef = ValueId::new(5);
    let with_value = ValueId::new(6);
    let tuple = ValueId::new(7);
    let read_back = ValueId::new(8);
    let false_const = ValueId::new(9);
    let negated = ValueId::new(10);

    let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32);
    bb0.body.push(
        InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(1) }).with_result(one),
    );
    bb0.body.push(
        InstrNode::new(Inst::Overflow {
            op: OverflowOp::AddOverflow,
            ty: Ty::I32,
            lhs: n,
            rhs: one,
        })
        .with_result(sum)
        .with_result(flag),
    );
    bb0.body.push(InstrNode::new(Inst::Undef { ty: Ty::I32 }).with_result(undef));
    bb0.body.push(
        InstrNode::new(Inst::InsertField { ty: Ty::I32, aggregate: undef, field: 0, value: sum })
            .with_result(with_value),
    );
    bb0.body.push(
        InstrNode::new(Inst::InsertField {
            ty: Ty::I32,
            aggregate: with_value,
            field: 1,
            value: flag,
        })
        .with_result(tuple),
    );
    bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

    // The read-back and the assert land in the NEXT block, as they do in real MIR.
    let mut bb1 = Block::new(BlockId::new(1));
    bb1.body.push(
        InstrNode::new(Inst::ExtractField { ty: Ty::Bool, aggregate: tuple, field: 1 })
            .with_result(read_back),
    );
    bb1.body.push(
        InstrNode::new(Inst::Const { ty: Ty::Bool, value: Constant::Bool(false) })
            .with_result(false_const),
    );
    bb1.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: Ty::Bool,
            lhs: read_back,
            rhs: false_const,
        })
        .with_result(negated),
    );
    bb1.body.push(InstrNode::new(Inst::Assert {
        cond: negated,
        kind: trust_ir::AssertKind::Unspecified,
        site: None,
    }));
    bb1.body.push(InstrNode::new(Inst::Return { values: vec![sum] }));

    let mut function =
        Function::new(FuncId::new(0), "demo::packed", FuncTyId::new(0), BlockId::new(0));
    function.blocks.push(bb0);
    function.blocks.push(bb1);

    assert!(
        super::function_unbounded_int_arithmetic_is_faithful(&function),
        "the flag is asserted false through `InsertField`/`ExtractField`, so the checked add \
         traps on overflow and the unbounded model is a sound over-approximation"
    );
}

/// The counting loop `fn f(n: i32) -> i32 { let mut i = 0; while i < n { i += 1; } i }`
/// in the bridge's CURRENT spelling of the checked add (BMC-LANE-1): `Overflow`
/// packed by the complete constructor `MakeAggregate(sum, flag)`, the flag read
/// back with `ExtractField(tuple, 1)` and asserted false, and the sum read back
/// with `ExtractField(tuple, 0)` in the NEXT block and stored to the accumulator.
///
/// `variant` is the constructor's variant (`None` is the real shape; `Some(v)` makes
/// it an enum constructor of `Ty::Enum`, whose lanes are variant `v`'s payload only,
/// so its lane `i` is `ExtractField` field `i + 1` and must never resolve as field
/// `i`), and
/// `assert_flag: false` is the `overflowing_add` control. Returns the function and
/// the `(tuple, sum, flag)` ids.
fn postcondition_goal_counting_loop_packed(
    variant: Option<u32>,
    assert_flag: bool,
) -> (trust_ir::Function, [trust_ir::ValueId; 3]) {
    use trust_ir::{
        Block, BlockId, Constant, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, OverflowOp,
        Ty, ValueId,
    };
    let n = ValueId::new(1);
    let zero = ValueId::new(2);
    let load_guard = ValueId::new(3);
    let guard = ValueId::new(4);
    let load_body = ValueId::new(5);
    let one = ValueId::new(6);
    let sum = ValueId::new(7);
    let flag = ValueId::new(8);
    let negated = ValueId::new(9);
    let slot = ValueId::new(10);
    let load_exit = ValueId::new(11);
    let false_const = ValueId::new(12);
    let tuple = ValueId::new(13);
    let read_flag = ValueId::new(14);
    let read_sum = ValueId::new(15);

    let load = |dest: ValueId| {
        InstrNode::new(Inst::Load { ty: Ty::I32, ptr: slot, volatile: false, align: None })
            .with_result(dest)
    };
    let store = |value: ValueId| {
        InstrNode::new(Inst::Store { ty: Ty::I32, ptr: slot, value, volatile: false, align: None })
    };

    let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32);
    bb0.body.push(
        InstrNode::new(Inst::Alloca { ty: Ty::I32, count: None, align: None }).with_result(slot),
    );
    bb0.body.push(
        InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(0) }).with_result(zero),
    );
    bb0.body.push(store(zero));
    bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

    let mut bb1 = Block::new(BlockId::new(1));
    bb1.body.push(load(load_guard));
    bb1.body.push(
        InstrNode::new(Inst::ICmp { op: ICmpOp::Slt, ty: Ty::I32, lhs: load_guard, rhs: n })
            .with_result(guard),
    );
    bb1.body.push(InstrNode::new(Inst::CondBr {
        cond: guard,
        then_target: BlockId::new(2),
        then_args: vec![],
        else_target: BlockId::new(3),
        else_args: vec![],
    }));

    let mut bb2 = Block::new(BlockId::new(2));
    bb2.body.push(load(load_body));
    bb2.body.push(
        InstrNode::new(Inst::Const { ty: Ty::I32, value: Constant::Int(1) }).with_result(one),
    );
    bb2.body.push(
        InstrNode::new(Inst::Overflow {
            op: OverflowOp::AddOverflow,
            ty: Ty::I32,
            lhs: load_body,
            rhs: one,
        })
        .with_result(sum)
        .with_result(flag),
    );
    bb2.body.push(
        InstrNode::new(Inst::MakeAggregate {
            ty: match variant {
                None => Ty::Tuple(vec![Ty::I32, Ty::Bool]),
                Some(_) => Ty::Enum(trust_ir::EnumId::new(0)),
            },
            variant,
            fields: vec![sum, flag],
        })
        .with_result(tuple),
    );
    bb2.body.push(
        InstrNode::new(Inst::ExtractField { ty: Ty::Bool, aggregate: tuple, field: 1 })
            .with_result(read_flag),
    );
    if assert_flag {
        bb2.body.push(
            InstrNode::new(Inst::Const { ty: Ty::Bool, value: Constant::Bool(false) })
                .with_result(false_const),
        );
        bb2.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Eq,
                ty: Ty::Bool,
                lhs: read_flag,
                rhs: false_const,
            })
            .with_result(negated),
        );
        bb2.body.push(InstrNode::new(Inst::Assert {
            cond: negated,
            kind: trust_ir::AssertKind::Unspecified,
            site: None,
        }));
    }
    bb2.body.push(InstrNode::new(Inst::Br { target: BlockId::new(4), args: vec![] }));

    // The sum's read-back lands in the assert's successor, as it does in real MIR.
    let mut bb4 = Block::new(BlockId::new(4));
    bb4.body.push(
        InstrNode::new(Inst::ExtractField { ty: Ty::I32, aggregate: tuple, field: 0 })
            .with_result(read_sum),
    );
    bb4.body.push(store(read_sum));
    bb4.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));

    let mut bb3 = Block::new(BlockId::new(3));
    bb3.body.push(load(load_exit));
    bb3.body.push(InstrNode::new(Inst::Return { values: vec![load_exit] }));

    let mut function =
        Function::new(FuncId::new(0), "demo::counting_packed", FuncTyId::new(0), BlockId::new(0));
    function.blocks = vec![bb0, bb1, bb2, bb3, bb4];
    (function, [tuple, sum, flag])
}

/// BMC-LANE-1 respelled the checked-arithmetic pack from `Undef` + `InsertField`
/// to the complete constructor `MakeAggregate`. The coverage gate and the
/// encoder's field map must follow the flag and the sum through it, or the
/// loop-carried postcondition lane refuses every checked function the bridge
/// emits (the shape that shipped this gate inert once already). The controls: an
/// unasserted flag (`overflowing_add`) stays refused, and an enum constructor's
/// lanes, which are its variant's payload only (lane `i` is field `i + 1`), are
/// never read as fields.
#[test]
fn the_coverage_gate_follows_the_overflow_flag_through_the_complete_constructor() {
    let (real, [tuple, sum, flag]) = postcondition_goal_counting_loop_packed(None, true);
    assert!(
        super::function_unbounded_int_arithmetic_is_faithful(&real),
        "the flag is asserted false through `MakeAggregate`/`ExtractField`, so the checked add \
         traps on overflow and the unbounded model is a sound over-approximation"
    );
    let frame = super::ChcDataflowFrame::build(&real, &[]);
    assert_eq!(
        frame.cells.len(),
        1,
        "the accumulator stays promotable beside the pack: `MakeAggregate` is an enumerated \
         read, not an opaque instruction that disqualifies every cell"
    );
    assert_eq!(frame.resolve_field(tuple, 0), Some(sum), "lane 0 of the pack is the sum");
    assert_eq!(frame.resolve_field(tuple, 1), Some(flag), "lane 1 of the pack is the flag");
    assert_eq!(frame.resolve_field(tuple, 2), None, "there is no lane 2");

    let (unasserted, _) = postcondition_goal_counting_loop_packed(None, false);
    assert!(
        !super::function_unbounded_int_arithmetic_is_faithful(&unasserted),
        "an unasserted overflow flag means execution continues wrapped — refuse"
    );

    let (enum_lanes, [payload, _, _]) = postcondition_goal_counting_loop_packed(Some(0), true);
    assert!(
        !super::function_unbounded_int_arithmetic_is_faithful(&enum_lanes),
        "an enum constructor's lanes are its variant's payload, so `ExtractField(e, 1)` is \
         lane 0 (the sum), not the flag: the flag does not resolve, so the gate cannot show \
         it traps"
    );
    let frame = super::ChcDataflowFrame::build(&enum_lanes, &[]);
    assert_eq!(
        frame.resolve_field(payload, 0),
        None,
        "field 0 of an enum value is its tag, which is no lane of the constructor"
    );
    assert_eq!(
        frame.resolve_field(payload, 1),
        None,
        "an enum constructor is never a field map: resolving field 1 to lane 1 (the flag) \
         would be off by one"
    );
}

/// End to end through the encoder: the packed loop is admitted by the
/// postcondition lane, and the goal edge is built over it exactly as over the
/// unpacked fixture (one goal edge, the obligation's negated conclusion).
/// Without the `MakeAggregate` arms the coverage gate refuses it and the lane
/// returns `None`, so this is the regression pin for the respelling.
#[test]
fn the_postcondition_goal_lane_admits_the_packed_checked_add() {
    let vc = serde_json::json!({
        "kind": "unary",
        "op": "not",
        "expr": {
            "kind": "binary",
            "op": "ge",
            "lhs": { "kind": "var", "name": "_0", "sort": { "kind": "int" } },
            "rhs": { "kind": "int_const", "value": "0" },
        },
    });
    let (function, _) = postcondition_goal_counting_loop_packed(None, true);
    let (_relations, rules, _vars) = super::trust_mc_dataflow_chc_for_function(
        &function,
        super::ChcErrorMode::PostconditionGoal,
        Some(&super::ChcPostconditionGoal { vc: &vc, bindings: &[] }),
    )
    .expect("encoder runs")
    .expect("the packed checked add traps on overflow, so the coverage gate admits it");
    let error_rules: Vec<_> = rules
        .as_array()
        .expect("rules array")
        .iter()
        .filter(|rule| rule["head"]["name"] == "error")
        .collect();
    assert_eq!(error_rules.len(), 1, "exactly one goal edge: {error_rules:?}");
    let rendered = serde_json::to_string(&error_rules[0]["body"]).expect("serializable");
    assert!(rendered.contains("\"not\""), "the goal edge carries ¬Q: {rendered}");
    assert!(
        rendered.contains("_cell_v10"),
        "the goal speaks the promoted accumulator's own column: {rendered}"
    );
    assert_copy_free(&rules, "PostconditionGoal (packed)");

    let (unasserted, _) = postcondition_goal_counting_loop_packed(None, false);
    assert!(
        super::trust_mc_dataflow_chc_for_function(
            &unasserted,
            super::ChcErrorMode::PostconditionGoal,
            Some(&super::ChcPostconditionGoal { vc: &vc, bindings: &[] }),
        )
        .expect("encoder runs")
        .is_none(),
        "a wrapping accumulator is refused by the lane, never encoded"
    );
}

/// **THE `Inconclusive` DEFECT.** `ay-chc`'s proof-grade `solve_pdr_proof` runs no
/// `ClauseInliner` preprocessing — deliberately, because `preserve_original_clauses`
/// keeps the invariant over the caller's exact clauses so the replay seal can
/// re-check it. The fold, however, names every intermediate SSA value, so it used
/// to ship rules like
///
/// ```text
///   bb2(v1, bb1_cell_v10) :- bb1(v1, bb1_cell_v10),
///                            v3 = bb1_cell_v10, v4 = (v3 < v1), v4
/// ```
///
/// where `v3` carries nothing. Measured on the real `f_loop` system: with those
/// copies present PDR returns `Unknown(Inconclusive)`; with ONLY them substituted
/// — `v6 = 1`, the dead overflow predicate and the rest left untouched — PDR
/// returns `Safe` carrying the invariant `c >= 0`. So a var-to-var copy surviving
/// into an emitted rule is not untidy, it is the difference between a proof and
/// no proof.
#[test]
fn no_emitted_rule_ships_a_variable_to_variable_copy() {
    for (mode, goal) in
        [(super::ChcErrorMode::Structural, None), (super::ChcErrorMode::ArithmeticSafetyOnly, None)]
    {
        let Some((_relations, rules, _vars)) = super::trust_mc_dataflow_chc_for_function(
            &postcondition_goal_counting_loop(),
            mode,
            goal,
        )
        .expect("encoder runs") else {
            continue;
        };
        assert_copy_free(&rules, &format!("{mode:?}"));
    }
    let vc = serde_json::json!({
        "kind": "unary",
        "op": "not",
        "expr": {
            "kind": "binary",
            "op": "ge",
            "lhs": { "kind": "var", "name": "_0", "sort": { "kind": "int" } },
            "rhs": { "kind": "int_const", "value": "0" },
        },
    });
    let (_relations, rules, _vars) = super::trust_mc_dataflow_chc_for_function(
        &postcondition_goal_counting_loop(),
        super::ChcErrorMode::PostconditionGoal,
        Some(&super::ChcPostconditionGoal { vc: &vc, bindings: &[] }),
    )
    .expect("encoder runs")
    .expect("admitted");
    assert_copy_free(&rules, "PostconditionGoal");
}

fn assert_copy_free(rules: &serde_json::Value, label: &str) {
    for rule in rules.as_array().expect("rules array") {
        let empty = Vec::new();
        for constraint in rule["body"]["constraints"].as_array().unwrap_or(&empty) {
            if constraint["op"] != "eq" {
                continue;
            }
            let (lhs, rhs) = (&constraint["lhs"], &constraint["rhs"]);
            assert!(
                !(lhs["kind"] == "var" && rhs["kind"] == "var"),
                "{label}: a var-to-var copy survived into an emitted rule, which is what makes \
                 proof-grade PDR return Inconclusive: {constraint}"
            );
        }
    }
}

/// The goal edge exists, sits on the RETURN block, and binds the VC's return
/// place to the value the function actually returns. Without that binding the
/// VC's `_0` is a free variable and `¬Q` is satisfiable for free, so no
/// postcondition could ever be discharged here.
#[test]
fn the_postcondition_goal_edge_binds_the_return_place_to_the_returned_value() {
    let function = postcondition_goal_counting_loop();
    let vc = serde_json::json!({
        "kind": "unary",
        "op": "not",
        "expr": {
            "kind": "binary",
            "op": "ge",
            "lhs": { "kind": "var", "name": "_0", "sort": { "kind": "int" } },
            "rhs": { "kind": "int_const", "value": "0" },
        },
    });
    let (_relations, rules, vars) = super::trust_mc_dataflow_chc_for_function(
        &function,
        super::ChcErrorMode::PostconditionGoal,
        Some(&super::ChcPostconditionGoal { vc: &vc, bindings: &[] }),
    )
    .expect("encoder runs")
    .expect("the counting loop is checked arithmetic, so the coverage gate admits it");

    let error_rules: Vec<_> = rules
        .as_array()
        .expect("rules array")
        .iter()
        .filter(|rule| rule["head"]["name"] == "error")
        .collect();
    assert_eq!(error_rules.len(), 1, "exactly one goal edge, at the return block: {error_rules:?}");
    let body = &error_rules[0]["body"];
    let rendered = serde_json::to_string(body).expect("serializable");
    // The return place is COLLAPSED into the encoder's own name for the returned
    // value, not carried alongside it. That substitution is what makes the goal
    // solvable: left as a chain of copy equalities, neither single-engine PDR nor
    // the adaptive portfolio converged on the real `f_loop` system in ~13 minutes,
    // while the collapsed form is proved SAFE.
    assert!(
        !rendered.contains("\"_0\""),
        "`_0` must be substituted away, not left as a copy chain: {rendered}"
    );
    // ... and the rule-level copy collapse takes it one step further, onto the
    // block relation's OWN column, because an anchored name (one the relation
    // carries) is always preferred as the class representative. That is the form
    // proof-grade PDR can generalize on.
    assert!(
        rendered.contains("_cell_v10"),
        "the goal must speak the block relation's own column: {rendered}"
    );
    assert!(
        rendered.contains("\"not\""),
        "the goal edge must carry the obligation's negated conclusion: {rendered}"
    );
    // No structural edges: an unrelated panic must not block a postcondition proof.
    assert!(
        !rendered.contains("unreachable terminator"),
        "PostconditionGoal emits no structural error edges: {rendered}"
    );
    assert!(
        vars.iter().any(|var| var["name"] == "v1"),
        "the encoder's own namespace is still declared: {vars:?}"
    );
}

/// A function that never returns a value has no goal edge, and `error` would be
/// unreachable VACUOUSLY — a false SAFE for whatever postcondition was
/// redirected. Fall back to the flattened path instead.
#[test]
fn a_postcondition_goal_with_no_return_edge_falls_back() {
    use trust_ir::{Block, BlockId, FuncId, FuncTyId, Function, Inst, InstrNode, Ty, ValueId};

    let n = ValueId::new(1);
    let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32);
    bb0.body.push(InstrNode::new(Inst::Br { target: BlockId::new(1), args: vec![] }));
    let mut bb1 = Block::new(BlockId::new(1));
    bb1.body.push(InstrNode::new(Inst::Br { target: BlockId::new(0), args: vec![] }));
    let mut function =
        Function::new(FuncId::new(0), "demo::diverges", FuncTyId::new(0), BlockId::new(0));
    function.blocks.push(bb0);
    function.blocks.push(bb1);

    let vc = serde_json::json!({ "kind": "bool_const", "value": true });
    assert!(
        super::trust_mc_dataflow_chc_for_function(
            &function,
            super::ChcErrorMode::PostconditionGoal,
            Some(&super::ChcPostconditionGoal { vc: &vc, bindings: &[] }),
        )
        .expect("encoder runs")
        .is_none(),
        "no return block means no goal edge, which would prove `error` unreachable for free"
    );
    // And with no goal at all, likewise.
    assert!(
        super::trust_mc_dataflow_chc_for_function(
            &postcondition_goal_counting_loop(),
            super::ChcErrorMode::PostconditionGoal,
            None,
        )
        .expect("encoder runs")
        .is_none(),
        "a PostconditionGoal encoding with no VC to place is not a proof of anything"
    );
}

/// The exact BV→Int fragment, positively and negatively. The mapping is the
/// UNSIGNED image; anything whose Int reading could differ from its bit-vector
/// reading on ANY input must decline — `bv_add` WRAPS (the eight-cardinal
/// false-verify class), `bv_slt` reads the signed image, casts re-interpret.
#[test]
fn bv_goal_vc_expressions_translate_exactly_or_decline() {
    let bv_var = |name: &str| serde_json::json!({ "kind": "var", "name": name, "sort": { "kind": "bit_vec", "width": 64 } });
    let bv_const =
        |value: &str| serde_json::json!({ "kind": "bit_vec_const", "value": value, "width": 64 });

    // bv_ult(x, c) -> lt(x:int, c:int) with the unsigned constant value.
    let translated = super::trust_mc_goal_vc_bv_expr_to_int(&serde_json::json!({
        "kind": "binary", "op": "bv_ult", "lhs": bv_var("x"),
        "rhs": bv_const("18446744073709551615"),
    }))
    .expect("unsigned compare is in the exact fragment");
    assert_eq!(
        translated,
        serde_json::json!({
            "kind": "binary", "op": "lt",
            "lhs": { "kind": "var", "name": "x", "sort": { "kind": "int" } },
            "rhs": { "kind": "int_const", "value": "18446744073709551615" },
        })
    );

    // eq over a bool var and a translated compare keeps its structure.
    let translated = super::trust_mc_goal_vc_bv_expr_to_int(&serde_json::json!({
        "kind": "binary", "op": "eq",
        "lhs": { "kind": "var", "name": "_4", "sort": { "kind": "bool" } },
        "rhs": { "kind": "binary", "op": "bv_ule", "lhs": bv_var("x"), "rhs": bv_var("n") },
    }))
    .expect("bool eq over translated children is in the fragment");
    assert_eq!(translated["rhs"]["op"], "le");

    // A pure Int/Bool subtree passes through UNCHANGED (identity lane).
    let pure = serde_json::json!({
        "kind": "binary", "op": "add",
        "lhs": { "kind": "var", "name": "a", "sort": { "kind": "int" } },
        "rhs": { "kind": "int_const", "value": "1" },
    });
    assert_eq!(super::trust_mc_goal_vc_bv_expr_to_int(&pure).expect("identity"), pure);

    // Declines: wrapping arithmetic, signed compares, casts, width overflow.
    for declined in [
        serde_json::json!({ "kind": "binary", "op": "bv_add", "lhs": bv_var("x"), "rhs": bv_const("1") }),
        serde_json::json!({ "kind": "binary", "op": "bv_sub", "lhs": bv_var("x"), "rhs": bv_const("1") }),
        serde_json::json!({ "kind": "binary", "op": "bv_mul", "lhs": bv_var("x"), "rhs": bv_var("n") }),
        serde_json::json!({ "kind": "binary", "op": "bv_slt", "lhs": bv_var("x"), "rhs": bv_var("n") }),
        serde_json::json!({ "kind": "binary", "op": "bv_sle", "lhs": bv_var("x"), "rhs": bv_var("n") }),
        serde_json::json!({ "kind": "unary", "op": "bv_not", "expr": bv_var("x") }),
        serde_json::json!({ "kind": "unary", "op": "int_to_bv", "width": 64,
            "expr": { "kind": "var", "name": "a", "sort": { "kind": "int" } } }),
        serde_json::json!({ "kind": "unary", "op": "bv_to_int", "signed": false, "expr": bv_var("x") }),
        // A 64-bit literal spelling a value 64 bits cannot hold.
        serde_json::json!({ "kind": "binary", "op": "bv_ult", "lhs": bv_var("x"),
            "rhs": { "kind": "bit_vec_const", "value": "18446744073709551616", "width": 64 } }),
    ] {
        assert_eq!(
            super::trust_mc_goal_vc_bv_expr_to_int(&declined),
            None,
            "must decline, not shift semantics: {declined}"
        );
    }
}

/// Every translated `W`-bit variable carries `0 <= x <= 2^W - 1` in the
/// translated constraint — the domain the `int` sort loses structurally, and
/// exactly what the merge design demands ("map each BV var into the Int domain
/// WITH its range constraint").
#[test]
fn bv_goal_translation_carries_the_width_range_of_every_variable() {
    let constraint = super::TrustMcTypedChcConstraint {
        vars: vec![
            serde_json::json!({ "name": "x", "sort": { "kind": "bit_vec", "width": 8 } }),
            serde_json::json!({ "name": "b", "sort": { "kind": "bool" } }),
        ],
        constraint: serde_json::json!({
            "kind": "binary", "op": "bv_ult",
            "lhs": { "kind": "var", "name": "x", "sort": { "kind": "bit_vec", "width": 8 } },
            "rhs": { "kind": "bit_vec_const", "value": "7", "width": 8 },
        }),
    };
    let (translated, vars) =
        super::trust_mc_goal_vc_bv_to_int(&constraint).expect("in the exact fragment");
    let rendered = serde_json::to_string(&translated).expect("serializable");
    assert!(
        rendered.contains(r#""value":"255""#) && rendered.contains(r#""op":"ge""#),
        "the 8-bit variable must carry its 0..=255 range: {rendered}"
    );
    assert_eq!(
        vars[0],
        serde_json::json!({ "name": "x", "sort": { "kind": "int" } }),
        "the declaration is re-sorted to int"
    );
    assert_eq!(vars[1]["sort"]["kind"], "bool", "non-BV declarations pass through");

    // An array declaration (which may embed BV elements) declines the whole VC.
    let with_array = super::TrustMcTypedChcConstraint {
        vars: vec![serde_json::json!({ "name": "a", "sort": { "kind": "array",
            "index": { "kind": "int" }, "element": { "kind": "bit_vec", "width": 8 } } })],
        constraint: constraint.constraint.clone(),
    };
    assert!(super::trust_mc_goal_vc_bv_to_int(&with_array).is_none());
}

/// End-to-end over the encoder: the REAL shape of the reference loop —
/// `fn count_to(n: u64) -> u64 ensures result == n` — with its BV-domain VC
/// translated, the parameter BOUND, and the emitted system SORT-COHERENT
/// (every variable reference agrees with its declaration; no `bit_vec`
/// anywhere). This is the system the consumer used to reject with
/// "variable reference `bb2_cell_v6` has sort BitVec(64), expected Int".
#[test]
fn the_bv_goal_system_is_sort_coherent_and_binds_the_parameter() {
    let function = postcondition_goal_counting_loop_typed(trust_ir::Ty::U64, trust_ir::ICmpOp::Ult);
    // The route-log VC shape for `ensures result == n`, reduced to its load-
    // bearing conjuncts: guard eq, exit branch, return binding, negated post.
    let bv64 = || serde_json::json!({ "kind": "bit_vec", "width": 64 });
    let var = |name: &str| serde_json::json!({ "kind": "var", "name": name, "sort": bv64() });
    let vc = super::TrustMcTypedChcConstraint {
        vars: vec![
            serde_json::json!({ "name": "_0", "sort": bv64() }),
            serde_json::json!({ "name": "_2#s0_0_s4_1", "sort": bv64() }),
            serde_json::json!({ "name": "_4", "sort": { "kind": "bool" } }),
            serde_json::json!({ "name": "n", "sort": bv64() }),
        ],
        constraint: serde_json::json!({
            "kind": "binary", "op": "and",
            "lhs": {
                "kind": "binary", "op": "and",
                "lhs": {
                    "kind": "binary", "op": "eq",
                    "lhs": { "kind": "var", "name": "_4", "sort": { "kind": "bool" } },
                    "rhs": { "kind": "binary", "op": "bv_ult",
                             "lhs": var("_2#s0_0_s4_1"), "rhs": var("n") },
                },
                "rhs": { "kind": "unary", "op": "not",
                         "expr": { "kind": "var", "name": "_4", "sort": { "kind": "bool" } } },
            },
            "rhs": {
                "kind": "binary", "op": "and",
                "lhs": { "kind": "binary", "op": "eq", "lhs": var("_0"), "rhs": var("_2#s0_0_s4_1") },
                "rhs": { "kind": "unary", "op": "not",
                         "expr": { "kind": "binary", "op": "eq", "lhs": var("_0"), "rhs": var("n") } },
            },
        }),
    };
    assert!(
        super::chc_return_values_are_unsigned_of_width(&function, 64),
        "the u64 loop returns a u64"
    );
    let (translated, goal_vars) =
        super::trust_mc_goal_vc_bv_to_int(&vc).expect("the reference VC is in the exact fragment");
    let bindings = vec![("n".to_string(), trust_ir::ValueId::new(1))];
    let goal = super::ChcPostconditionGoal { vc: &translated, bindings: &bindings };
    let (_relations, rules, encoder_vars) = super::trust_mc_dataflow_chc_for_function(
        &function,
        super::ChcErrorMode::PostconditionGoal,
        Some(&goal),
    )
    .expect("encoder runs")
    .expect("checked u64 arithmetic is admitted");

    // Merge exactly as the shared builder does, then check GLOBAL coherence.
    let mut declared: std::collections::BTreeMap<String, serde_json::Value> =
        std::collections::BTreeMap::new();
    for var in encoder_vars.iter().chain(goal_vars.iter()) {
        let name = var["name"].as_str().expect("declared name").to_string();
        declared.entry(name).or_insert_with(|| var["sort"].clone());
    }
    fn check_refs(
        node: &serde_json::Value,
        declared: &std::collections::BTreeMap<String, serde_json::Value>,
    ) {
        match node {
            serde_json::Value::Object(map) => {
                if map.get("kind").and_then(|kind| kind.as_str()) == Some("var") {
                    let name = map["name"].as_str().expect("var name");
                    let sort = &map["sort"];
                    assert_eq!(
                        Some(sort),
                        declared.get(name),
                        "reference to `{name}` disagrees with its declaration"
                    );
                    assert_ne!(sort["kind"], "bit_vec", "no BV survives into the merged system");
                }
                for value in map.values() {
                    check_refs(value, declared);
                }
            }
            serde_json::Value::Array(values) => {
                for value in values {
                    check_refs(value, declared);
                }
            }
            _ => {}
        }
    }
    check_refs(&rules, &declared);

    // The goal edge speaks the ENCODER's names: the bound parameter column and
    // the collapsed return cell, with the free VC spellings substituted away.
    let error_rule = rules
        .as_array()
        .expect("rules")
        .iter()
        .find(|rule| rule["head"]["name"] == "error")
        .expect("one goal edge");
    let rendered = serde_json::to_string(error_rule).expect("serializable");
    assert!(
        !rendered.contains("\"n\"") && !rendered.contains("_2#s0_0_s4_1"),
        "the VC parameter/local spellings must be substituted into encoder columns: {rendered}"
    );
    assert!(
        rendered.contains("\"v1\""),
        "the bound parameter must appear as the encoder's own column: {rendered}"
    );
    assert!(
        rendered.contains("18446744073709551615"),
        "the width ranges must land on the goal edge: {rendered}"
    );

    // And the normalization (what the shared builder actually emits): the
    // linear block chain inlines to ONE loop relation + `error`, the
    // clause-local guard chains are eliminated, and the final declaration
    // table matches every reference. This is the exact shape probed Safe under
    // strict `solve_pdr_proof` (the multi-predicate or chain-bearing forms
    // probe Unknown(Inconclusive)).
    let (relations, rules, vars) =
        super::chc_normalize_postcondition_goal_system(_relations, rules)
            .expect("normalization holds on the reference system");
    let relation_names: Vec<&str> = relations
        .as_array()
        .expect("relations")
        .iter()
        .filter_map(|relation| relation["name"].as_str())
        .collect();
    assert!(relation_names.contains(&"error"), "{relation_names:?}");
    assert_eq!(
        relation_names.len(),
        2,
        "the linear chain must inline to error + one loop relation: {relation_names:?}"
    );
    assert_eq!(rules.as_array().expect("rules").len(), 3, "init + back edge + goal: {rules}");
    let rendered = serde_json::to_string(&rules).expect("serializable");
    assert!(
        !rendered.contains("\"v9\"") && !rendered.contains("\"v12\""),
        "clause-local Bool definition chains must be eliminated: {rendered}"
    );
    let mut declared2: std::collections::BTreeMap<String, serde_json::Value> =
        std::collections::BTreeMap::new();
    for var in vars.iter() {
        declared2.insert(var["name"].as_str().expect("name").to_string(), var["sort"].clone());
    }
    check_refs(&rules, &declared2);
    // The INIT rule (no body relation) carries the unsigned entry-param range —
    // what turns the needed invariant conjunctive; probed load-bearing for
    // strict PDR.
    let init = rules
        .as_array()
        .expect("rules")
        .iter()
        .find(|rule| rule.pointer("/body/relation").is_none())
        .expect("an init rule");
    let init_rendered = serde_json::to_string(init).expect("serializable");
    assert!(
        init_rendered.contains("18446744073709551615"),
        "the unsigned entry-param range must land on the init rule: {init_rendered}"
    );
}

/// The defined-local eliminator, directly: the bridge's guard chain
/// `v12 = (v11 = v9), v9 = (c < n), ¬v11, ¬v12` must fold to the direct
/// guard, and a rule whose constraints fold to `⊥` is FROZEN (kept
/// unsatisfiable), never dropped — dropping the last goal edge would hand the
/// obligation to the trivially-safe route.
#[test]
fn defined_rule_locals_are_eliminated_soundly() {
    let bool_var =
        |name: &str| serde_json::json!({ "kind": "var", "name": name, "sort": { "kind": "bool" } });
    let int_var =
        |name: &str| serde_json::json!({ "kind": "var", "name": name, "sort": { "kind": "int" } });
    let rule = serde_json::json!({
        "head": { "name": "bb1", "args": [int_var("n"), int_var("c2")] },
        "body": {
            "relation": { "name": "bb1", "args": [int_var("n"), int_var("c")] },
            "constraints": [
                { "kind": "binary", "op": "eq",
                  "lhs": { "kind": "binary", "op": "eq", "lhs": bool_var("v11"), "rhs": bool_var("v9") },
                  "rhs": bool_var("v12") },
                { "kind": "binary", "op": "eq",
                  "lhs": { "kind": "binary", "op": "lt", "lhs": int_var("c"), "rhs": int_var("n") },
                  "rhs": bool_var("v9") },
                { "kind": "unary", "op": "not", "expr": bool_var("v11") },
                { "kind": "unary", "op": "not", "expr": bool_var("v12") },
                { "kind": "binary", "op": "eq",
                  "lhs": { "kind": "binary", "op": "add", "lhs": int_var("c"), "rhs": { "kind": "int_const", "value": "1" } },
                  "rhs": int_var("c2") },
            ],
        },
    });
    let out = super::chc_eliminate_defined_rule_locals(rule);
    let rendered = serde_json::to_string(&out).expect("serializable");
    assert!(
        !rendered.contains("v9") && !rendered.contains("v11") && !rendered.contains("v12"),
        "every clause-local Bool must be eliminated: {rendered}"
    );
    assert!(rendered.contains("\"lt\""), "the direct guard must survive: {rendered}");
    assert!(rendered.contains("\"add\""), "the interface definition must survive: {rendered}");

    // ⊥ freeze: `v ∧ ¬v` folds to false and the rule stays present.
    let contradictory = serde_json::json!({
        "head": { "name": "error" },
        "body": {
            "relation": { "name": "bb1", "args": [int_var("n")] },
            "constraints": [
                bool_var("g"),
                { "kind": "unary", "op": "not", "expr": bool_var("g") },
            ],
        },
    });
    let out = super::chc_eliminate_defined_rule_locals(contradictory);
    assert_eq!(
        out.pointer("/body/constraints").and_then(|c| c.as_array()).map(Vec::len),
        Some(1),
        "{out}"
    );
    assert_eq!(out.pointer("/body/constraints/0/value"), Some(&serde_json::json!(false)), "{out}");
}

/// The linear-chain inliner, directly: a forwarding relation with one
/// definition and one use unfolds into the use; a relation with TWO defining
/// rules (the loop header) or the `error` relation never inlines; and a name
/// shared by the two clauses is alpha-renamed apart rather than conflated.
#[test]
fn linear_relation_chains_inline_with_alpha_renaming() {
    let int_var =
        |name: &str| serde_json::json!({ "kind": "var", "name": name, "sort": { "kind": "int" } });
    let mut relations = vec![
        serde_json::json!({ "name": "error" }),
        serde_json::json!({ "name": "mid", "arg_sorts": [{ "kind": "int" }] }),
        serde_json::json!({ "name": "loophead", "arg_sorts": [{ "kind": "int" }] }),
    ];
    // loophead(x) :- (init);  mid(t) :- loophead(x), t = x + 1, aux = x;
    // loophead(y) :- mid(y), aux = y  — `aux` is spelled in BOTH clauses.
    let mut rules = vec![
        serde_json::json!({
            "head": { "name": "loophead", "args": [int_var("x")] },
            "body": { "constraints": [] },
        }),
        serde_json::json!({
            "head": { "name": "mid", "args": [int_var("t")] },
            "body": {
                "relation": { "name": "loophead", "args": [int_var("x")] },
                "constraints": [
                    { "kind": "binary", "op": "eq",
                      "lhs": { "kind": "binary", "op": "add", "lhs": int_var("x"), "rhs": { "kind": "int_const", "value": "1" } },
                      "rhs": int_var("t") },
                    { "kind": "binary", "op": "le", "lhs": int_var("aux"), "rhs": int_var("x") },
                ],
            },
        }),
        serde_json::json!({
            "head": { "name": "loophead", "args": [int_var("y")] },
            "body": {
                "relation": { "name": "mid", "args": [int_var("y")] },
                "constraints": [
                    { "kind": "binary", "op": "ge", "lhs": int_var("aux"), "rhs": int_var("y") },
                ],
            },
        }),
    ];
    let mut counter = 0;
    assert!(super::chc_inline_linear_relation(&mut relations, &mut rules, &mut counter));
    assert_eq!(rules.len(), 2, "{rules:?}");
    assert!(
        !relations.iter().any(|relation| relation["name"] == "mid"),
        "the forwarding relation is gone: {relations:?}"
    );
    let merged = rules
        .iter()
        .find(|rule| {
            rule["body"]["relation"]["name"] == "loophead" && rule["head"]["name"] == "loophead"
        })
        .expect("merged back edge");
    let rendered = serde_json::to_string(merged).expect("serializable");
    assert!(
        rendered.contains("aux$i") && rendered.contains("\"aux\""),
        "the defining clause's `aux` must be renamed apart from the using clause's: {rendered}"
    );
    // `t` (the interface var) was substituted by `y`.
    assert!(!rendered.contains("\"t\""), "{rendered}");

    // No further inline: `loophead` has two defining rules, `error` never.
    assert!(!super::chc_inline_linear_relation(&mut relations, &mut rules, &mut counter));
}

/// The signed-image seam stays CLOSED: a signed return (or a width mismatch)
/// refuses the BV merge, because the encoder's Int model of a signed value is
/// the SIGNED value while the VC's BV image is UNSIGNED — identifying them
/// would drop real violating states from the error rule (the false-PROVE
/// direction).
#[test]
fn a_signed_or_mismatched_return_declines_the_bv_goal_merge() {
    let signed = postcondition_goal_counting_loop(); // i32 fixture
    assert!(!super::chc_return_values_are_unsigned_of_width(&signed, 32));
    let unsigned = postcondition_goal_counting_loop_typed(trust_ir::Ty::U64, trust_ir::ICmpOp::Ult);
    assert!(super::chc_return_values_are_unsigned_of_width(&unsigned, 64));
    assert!(
        !super::chc_return_values_are_unsigned_of_width(&unsigned, 32),
        "a width mismatch is a different machine quantity, not a rounding detail"
    );
}

/// Parameter bindings are emitted only under the full image-agreement gate:
/// unsigned + exact width on the BV lane, and never for a local the body
/// writes or aliases (the bare VC name denotes the ENTRY value only then).
#[test]
fn goal_param_bindings_require_image_agreement_and_an_untouched_local() {
    use trust_types::{LocalDecl, Place, Rvalue, SourceSpan, Statement, VerifiableFunction};

    let u64_ty = trust_types::Ty::Int { width: 64, signed: false };
    let mk_func = |stmts: Vec<Statement>| VerifiableFunction {
        name: "count_to".to_string(),
        def_path: "demo::count_to".to_string(),
        span: SourceSpan::default(),
        body: trust_types::VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: u64_ty.clone(), name: None },
                LocalDecl { index: 1, ty: u64_ty.clone(), name: Some("n".to_string()) },
            ],
            blocks: vec![trust_types::BasicBlock {
                id: trust_types::BlockId(0),
                stmts,
                terminator: trust_types::Terminator::Return,
            }],
            arg_count: 1,
            return_ty: u64_ty.clone(),
            datatype_defs: Default::default(),
        },
        contracts: Vec::new(),
        preconditions: Vec::new(),
        postconditions: Vec::new(),
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let function = postcondition_goal_counting_loop_typed(trust_ir::Ty::U64, trust_ir::ICmpOp::Ult);
    let bv_vars =
        vec![serde_json::json!({ "name": "n", "sort": { "kind": "bit_vec", "width": 64 } })];

    // Clean body, u64 param, bv64 VC var: binds to entry param v1.
    let clean = mk_func(Vec::new());
    assert_eq!(
        super::trust_mc_goal_param_bindings(&clean, &function, &bv_vars),
        vec![("n".to_string(), trust_ir::ValueId::new(1))]
    );

    // A body that WRITES the param local voids the entry-value reading.
    let written = mk_func(vec![Statement::Assign {
        place: Place::local(1),
        rvalue: Rvalue::Use(trust_types::Operand::Constant(trust_types::ConstValue::Uint(0, 64))),
        span: SourceSpan::default(),
    }]);
    assert!(super::trust_mc_goal_param_bindings(&written, &function, &bv_vars).is_empty());

    // Taking the param's address voids it too (a hidden write channel).
    let aliased = mk_func(vec![Statement::Assign {
        place: Place::local(0),
        rvalue: Rvalue::Ref { mutable: true, place: Place::local(1) },
        span: SourceSpan::default(),
    }]);
    assert!(super::trust_mc_goal_param_bindings(&aliased, &function, &bv_vars).is_empty());

    // A SIGNED trust-ir param must not merge with an unsigned BV image.
    let signed_function = postcondition_goal_counting_loop(); // i32 params
    assert!(
        super::trust_mc_goal_param_bindings(
            &clean,
            &signed_function,
            &[serde_json::json!({ "name": "n", "sort": { "kind": "bit_vec", "width": 32 } })],
        )
        .is_empty()
    );

    // Width mismatch (u64 param, bv32 VC var): no binding.
    assert!(
        super::trust_mc_goal_param_bindings(
            &clean,
            &function,
            &[serde_json::json!({ "name": "n", "sort": { "kind": "bit_vec", "width": 32 } })],
        )
        .is_empty()
    );

    // Int-sorted VC var over an integer param: the Int-lane binding.
    assert_eq!(
        super::trust_mc_goal_param_bindings(
            &clean,
            &function,
            &[serde_json::json!({ "name": "n", "sort": { "kind": "int" } })],
        ),
        vec![("n".to_string(), trust_ir::ValueId::new(1))]
    );
}

/// A VC variable spelled like an encoder column (`v3`, `bb2_cell_v6`) would
/// silently conflate with it in the name-keyed merge — reachable input, since a
/// user can write `let v1 = …;` — so the enrichment must detect and decline.
#[test]
fn vc_names_colliding_with_the_encoder_namespace_are_detected() {
    let collide = |name: &str| {
        super::trust_mc_goal_vc_var_names_collide_with_encoder(&[
            serde_json::json!({ "name": name, "sort": { "kind": "int" } }),
        ])
    };
    assert!(collide("v3"));
    assert!(collide("v0"));
    assert!(collide("bb2_cell_v6"));
    assert!(!collide("n"));
    assert!(!collide("_0"));
    assert!(!collide("_2#s0_0_s4_1"));
    assert!(!collide("value"));
    assert!(!collide("vx1"));
    assert!(!collide("bbq_cell_v1"));
}

/// **THE FREE-BRANCH-GUARD DEFECT.** The fold modeled no boolean instruction:
/// `Copy` and `BinOp` were gated on `ty.is_integer()` and there was no `UnOp`
/// arm, so any boolean not produced directly by `ICmp` was havoc'd — and a
/// `CondBr` guard is exactly such a value. The emitted system for the real
/// bridge lowering of `while i < n` was
///
/// ```text
///   bb4(c)     :- bb1(v0, c), v9 = c, v8 = (v9 lt v0), v11
///   bb2(v0, c) :- bb1(v0, c), v9 = c, v8 = (v9 lt v0), not(v11)
/// ```
///
/// with the comparison `v8` DEAD and the branch turning on a free `v11` that no
/// rule defines. Both edges were unconditionally enabled, so `i < n` constrained
/// nothing and the CFG was a nondeterministic choice.
///
/// The fixture below is deliberately shaped like the BRIDGE and not like
/// `bridge_shaped_counting_loop`, which wires `ICmp` straight into `CondBr` and
/// therefore could never have caught this: the real lowering interposes a
/// `UnOp::Not` (which is why the loop-BODY edge carries `not(guard)` rather than
/// `guard`), and that `Not` was the unmodeled link.
#[test]
fn a_negated_branch_guard_is_connected_to_the_comparison_it_came_from() {
    use trust_ir::{
        Block, BlockId, FuncId, FuncTyId, Function, ICmpOp, Inst, InstrNode, Ty, ValueId,
    };

    let n = ValueId::new(1);
    let i = ValueId::new(2);
    let cmp = ValueId::new(3);
    let negated = ValueId::new(4);

    let mut bb0 = Block::new(BlockId::new(0)).with_param(n, Ty::I32).with_param(i, Ty::I32);
    bb0.body.push(
        InstrNode::new(Inst::ICmp { op: ICmpOp::Slt, ty: Ty::I32, lhs: i, rhs: n })
            .with_result(cmp),
    );
    // The link the fold used to drop.
    bb0.body.push(
        InstrNode::new(Inst::UnOp { op: trust_ir::UnOp::Not, ty: Ty::Bool, operand: cmp })
            .with_result(negated),
    );
    bb0.body.push(InstrNode::new(Inst::CondBr {
        cond: negated,
        then_target: BlockId::new(1),
        then_args: vec![],
        else_target: BlockId::new(2),
        else_args: vec![],
    }));

    let mut function =
        Function::new(FuncId::new(0), "demo::guarded", FuncTyId::new(0), BlockId::new(0));
    function.blocks.push(bb0);
    function.blocks.push(Block::new(BlockId::new(1)));
    function.blocks.push(Block::new(BlockId::new(2)));

    let block = &function.blocks[0];
    let frame = super::ChcDataflowFrame::build(&function, &[]);
    let mut var_decls = super::ChcVarDecls::default();
    let relation_args = frame.relation_arg_exprs(block, &mut var_decls);
    let fold = super::chc_fold_block_body(block, &frame, &mut var_decls);
    let grounded = dataflow_grounded_vars(&relation_args, &fold.constraints);

    // The decisive assertion: the value the branch turns on is DEFINED, not free.
    // Without the `UnOp` fold arm this name is absent and both edges are enabled.
    assert!(
        grounded.contains(&super::chc_value_var_name(negated)),
        "the branch guard must be grounded in the comparison it came from, or the CFG is \
         modeled as a nondeterministic choice and `i < n` constrains nothing: {grounded:?}"
    );
    // ... and it is grounded THROUGH the comparison, not by accident.
    assert!(
        grounded.contains(&super::chc_value_var_name(cmp)),
        "the comparison itself must be grounded: {grounded:?}"
    );
}

/// Trust (NET-POISON GATE, 2026-08-25): the bundle-poison drop loop's success
/// metric is "how many `[trust-absent-callee-assumption]` rows does the ROOT
/// own", and `root_owned_absent_callee_rows` is that metric.
///
/// It must (a) count ONLY root-owned rows — a member-owned row is exactly what
/// the loop is trying to drop, so counting it would make the gate compare the
/// wrong population — and (b) map each owner `FuncId` through the member list
/// the module was LOWERED FROM. The loop's own note records that comparing
/// against the pre-filter list instead misattributed a poison row to an
/// already-dropped member; the gate inherits that hazard and is pinned here.
///
/// The behaviour this guards, measured on `trust_sha2::sha256::Core256::update`:
/// dropping the poisoned member `compress` made the ROOT own 2 NEW rows
/// (`absent callee Core256::compress`), taking root-owned rows 6 -> 8 while
/// evicting a 727-instruction body that lowers perfectly well. A drop that
/// raises this number is relocating the poison, not removing it.
#[test]
fn root_owned_absent_callee_rows_counts_only_the_root_through_its_own_member_list() {
    const ABSENT: &str = "[trust-absent-callee-assumption] call to absent callee \
                          `demo::gone` (body not in the lowered bundle) may panic";

    let (base, _, _) = native_trust_ir_compiler_function();
    let member = |path: &str| {
        let mut function = base.clone();
        function.def_path = path.to_string();
        function
    };

    let mut module = trust_ir::Module::new("demo");
    let mut push = |id: u32, owner: Option<u32>, description: &str| {
        let mut obligation = trust_ir::ProofObligation::new(
            trust_ir::ProofId::new(id),
            trust_ir::ObligationKind::PanicFreedom,
            trust_ir::ProofStatus::Pending,
            description,
        );
        if let Some(owner) = owner {
            obligation = obligation.with_function(trust_ir::FuncId::new(owner));
        }
        module.proof_obligations.push(obligation);
    };
    push(0, Some(0), ABSENT); // root-owned absent row
    push(1, Some(1), ABSENT); // MEMBER-owned absent row — must not be counted
    push(2, Some(1), ABSENT); // and a second one, same member
    push(3, Some(0), "ordinary panic-freedom row, not an absent callee");
    push(4, None, ABSENT); // unscoped legacy row — no owner, cannot be attributed

    let members = [member("demo::root"), member("demo::callee")];

    assert_eq!(
        root_owned_absent_callee_rows(&module, &members, "demo::root"),
        1,
        "only the ROOT's own absent-callee row may count toward the gate"
    );

    // (b) the SAME module read against a member list that no longer contains the
    // callee: index 1 now resolves to nothing, so its two rows stay uncounted
    // rather than sliding onto whichever function occupies that slot.
    let after_drop = [member("demo::root")];
    assert_eq!(
        root_owned_absent_callee_rows(&module, &after_drop, "demo::root"),
        1,
        "owners must map through the list the module was lowered from"
    );

    // Negative control: a list whose slot 1 IS the root (the misattribution the
    // loop's note warns about) would count 3 — proving the mapping is load
    // bearing and this test can fail.
    let misattributed = [member("demo::root"), member("demo::root")];
    assert_eq!(
        root_owned_absent_callee_rows(&module, &misattributed, "demo::root"),
        3,
        "sanity: the member list really is what decides attribution"
    );
}

// Trust: a previously bundled body cannot regain a total summary merely
// because its own fail-closed obligation caused the poison loop to evict it.
fn poison_eviction_summary_fixture(transitive: bool) -> trust_ir_bridge::NativeVerificationBundle {
    use trust_types::{BasicBlock, BlockId, LocalDecl, Place, Terminator, Ty,
        UnwindEdge, VerifiableBody, VerifiableFunction};
    // Trust: Native row validation needs real source spans before the credit assertions.
    let function = |name: &str, callee: &str, line: u32| VerifiableFunction {
        name: name.rsplit("::").next().unwrap().into(),
        def_path: name.into(),
        span: native_trust_ir_test_span(line),
        body: VerifiableBody {
            locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        func: callee.into(), args: vec![], dest: Place::local(0),
                        target: Some(BlockId(1)), span: native_trust_ir_test_span(line + 1),
                        atomic: None, is_foreign: false, is_unsafe_sig: false,
                        callee_identity: Some(bundled_assert_test_identity(callee)),
                        callee_key: None, unwind: UnwindEdge::Unreachable,
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            arg_count: 0, return_ty: Ty::Unit, datatype_defs: Default::default(),
        },
        contracts: vec![], preconditions: vec![], postconditions: vec![],
        spec: Default::default(), tuple_layouts: Default::default(),
    };
    let credited = "core::poison_fixture::credited";
    let root = function("demo::poison_root", if transitive { "demo::middle" } else { credited }, 1);
    let mut functions = vec![root.clone()];
    if transitive { functions.push(function("demo::middle", credited, 11)); }
    functions.push(function(credited, "dep::unverified_body", 21));
    let compiler_contracts = trust_types::CompilerContractBundle::new(vec![]);
    let mut bundle = trust_mir_extract::function_to_verifier_api_bundle(&root, &compiler_contracts, &[]);
    ensure_default_trust_mc_function_obligation(&root, &mut bundle).expect("default native row");
    let ledger = bundled_assert_test_ledger(&functions);
    let totals: FxHashSet<String> = [credited.into()].into_iter().collect();
    build_native_trust_ir_bundle_from_verifiable_functions(
        &root, &mut bundle, functions, &ledger,
        &FxHashSet::default(), &FxHashSet::default(), &FxHashSet::default(),
        &FxHashSet::default(), &totals, &FxHashSet::default(), &FxHashSet::default(),
        &FxHashSet::default(), &FxHashSet::default(),
        &trust_ir_bridge::CallReachWithdrawals::default(),
        None, None, &trust_ir_bridge::InstanceHypothesisSites::default(),
        &trust_ir_bridge::CompilerAllocGrowPins::default(), None, &[], &[], None,
        &mut None, &mut PanicFreedomFoldAttestation::default(), &mut None,
        &mut Vec::new(), false, None, None, &mut None,
    ).expect("the diagnostic bundle must lower").expect("default native row retains the bundle")
}

#[test]
fn poison_eviction_cannot_recredit_a_direct_callee_as_compiler_total() {
    let native = poison_eviction_summary_fixture(false);
    assert!(native.module.functions.iter().any(|function| {
        function.blocks.iter().flat_map(|block| &block.body)
            .any(|node| matches!(node.inst, trust_ir::Inst::Assert { .. }))
    }), "removing a poisoned body must not erase its reachable panic marker via total credit");
}

#[test]
fn poison_eviction_cannot_recredit_a_transitive_callee_as_compiler_total() {
    // Trust (POISON-EVICTION-FALSE-PROOF-1): `middle` calls the poisoned body
    // through an edge, so the body is not evicted at all: it keeps its own
    // fail-closed marker, and `middle`'s call is neither withdrawn nor recredited.
    let native = poison_eviction_summary_fixture(true);
    assert!(native.module.functions.iter().any(|function| function.name == "middle"));
    let credited = native.module.functions.iter().find(|function| function.name == "credited")
        .expect("a body a retained caller reaches by an edge must not be evicted");
    assert!(credited.blocks.iter().flat_map(|block| &block.body)
        .any(|node| matches!(node.inst, trust_ir::Inst::Assert { .. })),
        "the charged body must keep its own fail-closed marker");
}

// Trust (POISON-EVICTION-FALSE-PROOF-1): one-call bodies for the poison loop. Each
// entry is `(def_path, callee, identity_of)`: the call names `identity_of`'s
// identity, or none. Entry 0 is the root. `destructors` are the admitted
// destructor members.
fn poison_loop_fixture(
    calls: &[(&str, &str, Option<&str>)],
    destructors: &[&str],
) -> trust_ir_bridge::NativeVerificationBundle {
    use trust_types::{BasicBlock, BlockId, LocalDecl, Place, Terminator, Ty,
        UnwindEdge, VerifiableBody, VerifiableFunction};
    let functions: Vec<VerifiableFunction> = calls.iter().enumerate().map(|(index, call)| {
        let (path, callee, identity_of) = *call;
        let line = 1 + 10 * index as u32;
        VerifiableFunction {
            name: path.rsplit("::").next().unwrap().into(),
            def_path: path.into(),
            span: native_trust_ir_test_span(line),
            body: VerifiableBody {
                locals: vec![LocalDecl { index: 0, ty: Ty::Unit, name: None }],
                blocks: vec![
                    BasicBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            func: callee.into(), args: vec![], dest: Place::local(0),
                            target: Some(BlockId(1)), span: native_trust_ir_test_span(line + 1),
                            atomic: None, is_foreign: false, is_unsafe_sig: false,
                            callee_identity: identity_of.map(bundled_assert_test_identity),
                            callee_key: None, unwind: UnwindEdge::Unreachable,
                        },
                    },
                    BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count: 0, return_ty: Ty::Unit, datatype_defs: Default::default(),
            },
            contracts: vec![], preconditions: vec![], postconditions: vec![],
            spec: Default::default(), tuple_layouts: Default::default(),
        }
    }).collect();
    let root = functions[0].clone();
    let compiler_contracts = trust_types::CompilerContractBundle::new(vec![]);
    let mut bundle =
        trust_mir_extract::function_to_verifier_api_bundle(&root, &compiler_contracts, &[]);
    ensure_default_trust_mc_function_obligation(&root, &mut bundle).expect("default native row");
    let ledger = bundled_assert_test_ledger(&functions);
    let destructors: FxHashSet<String> = destructors.iter().map(|path| (*path).into()).collect();
    build_native_trust_ir_bundle_from_verifiable_functions(
        &root, &mut bundle, functions, &ledger,
        &FxHashSet::default(), &FxHashSet::default(), &FxHashSet::default(),
        &FxHashSet::default(), &FxHashSet::default(), &FxHashSet::default(),
        &FxHashSet::default(), &FxHashSet::default(), &destructors,
        &trust_ir_bridge::CallReachWithdrawals::default(),
        None, None, &trust_ir_bridge::InstanceHypothesisSites::default(),
        &trust_ir_bridge::CompilerAllocGrowPins::default(), None, &[], &[], None,
        &mut None, &mut PanicFreedomFoldAttestation::default(), &mut None,
        &mut Vec::new(), false, None, None, &mut None,
    ).expect("the diagnostic bundle must lower").expect("default native row retains the bundle")
}

fn poison_loop_keeps(native: &trust_ir_bridge::NativeVerificationBundle, name: &str) -> bool {
    native.module.functions.iter().any(|function| {
        function.name == name
            && function.blocks.iter().flat_map(|block| &block.body)
                .any(|node| matches!(node.inst, trust_ir::Inst::Assert { .. }))
    })
}

#[test]
fn poison_eviction_keeps_a_body_named_only_by_a_total_sentinel() {
    // The measured false proof's shape: the root reaches the poisoned body by no
    // edge, only through the extractor's total sentinel, whose claim the body's
    // rows qualify. Evicting it left no row anywhere in the module.
    let native = poison_loop_fixture(&[
        ("demo::fmt_root", trust_types::total_call_summaries::TRUST_TOTAL_CLONE_SENTINEL,
            Some("core::fmt_fixture::finisher")),
        ("core::fmt_fixture::finisher", "dep::unverified_body", Some("dep::unverified_body")),
    ], &[]);
    assert!(poison_loop_keeps(&native, "finisher"),
        "a body a retained credit arm names must keep its fail-closed rows");
}

#[test]
fn poison_eviction_still_drops_a_body_no_retained_body_reaches() {
    let native = poison_loop_fixture(&[
        ("demo::lone_root", "dep::root_callee", Some("dep::root_callee")),
        ("demo::unreached", "dep::unverified_body", Some("dep::unverified_body")),
    ], &[]);
    assert!(native.module.functions.iter().all(|function| function.name != "unreached"),
        "control: a poisoned body nothing retained reaches is still evicted");
}

#[test]
fn poison_eviction_keeps_an_admitted_destructor_body() {
    // Nothing calls a destructor: a drop reaches it, and the bridge credits its
    // ADT's drop glue because the body is in the bundle.
    let destructor = "<demo::Bomb as core::ops::Drop>::drop";
    let native = poison_loop_fixture(&[
        ("demo::drop_root", "dep::root_callee", Some("dep::root_callee")),
        (destructor, "dep::unverified_body", Some("dep::unverified_body")),
    ], &[destructor]);
    assert!(poison_loop_keeps(&native, "drop"),
        "a destructor body whose drop the bridge credits must not be evicted");
}

#[test]
fn poison_eviction_drops_a_body_reached_only_through_a_format_dispatch_row() {
    // The dispatch arm keeps the call's own may-panic row, so the body under it
    // carries no claim: evicting it loses nothing, and it is evicted.
    let native = poison_loop_fixture(&[
        ("demo::format_root", "alloc::fmt::format", Some("alloc::fmt::format")),
        ("alloc::fmt::format", "dep::unverified_body", Some("dep::unverified_body")),
    ], &[]);
    assert!(native.module.functions.iter().all(|function| function.name != "format"),
        "a body reached only through a call with its own fail-closed row may be evicted");
    // The published module's rows are reset to the verifier-api bundle, so read the
    // lowered IR: the root's one call is the dispatch arm's `Assert(false)`.
    assert!(poison_loop_keeps(&native, "format_root"),
        "the root's dispatch call keeps its own fail-closed marker");
}

// ---------------------------------------------------------------------------
// Bundled-member identity: source population READS the owner, never re-stamps it.
// ---------------------------------------------------------------------------

/// One bound row whose owner the caller chooses, plus the exact three inputs
/// `populate_native_trust_ir_proof_sources` takes beside the module.
///
/// The row's `FuncId` is deliberately NOT the root's: the whole question these
/// tests ask is whether a non-root attribution survives this pass.
fn native_proof_source_population_fixture(
    owner: Option<u32>,
) -> (
    trust_ir::Module,
    trust_verifier_api::TrustContractBundle,
    Vec<PendingNativeTrustIrBinding>,
    trust_verifier_api::CanonicalObligationSemanticDigestIndex,
) {
    let mut module = trust_ir::Module::new("demo");
    let mut proof_obligation = trust_ir::ProofObligation::new(
        trust_ir::ProofId::new(0),
        trust_ir::ObligationKind::PanicFreedom,
        trust_ir::ProofStatus::Pending,
        "a bundled member's own assertion (public verifier obligation vc:demo:member:0)",
    );
    if let Some(owner) = owner {
        proof_obligation = proof_obligation.with_function(trust_ir::FuncId::new(owner));
    }
    module.proof_obligations.push(proof_obligation);

    let mut bundle = trust_verifier_api::TrustContractBundle::empty(
        "bundle-member-owner",
        trust_verifier_api::BundleSubject::Function {
            crate_name: "demo".to_string(),
            path: "demo::root".to_string(),
        },
    );
    bundle.obligations.push(trust_verifier_api::TrustObligation {
        obligation_id: "vc:demo:member:0".to_string(),
        kind: trust_verifier_api::ObligationKind::Assertion,
        contract_id: None,
        proof_item_id: None,
        source: native_trust_ir_test_source_location(11),
        description: "a bundled member's own assertion".to_string(),
        required_strength: None,
        summary_facts: Vec::new(),
        metadata: Vec::new(),
    });
    let requested = bundle.obligations.clone();
    let semantic_digests = bundle
        .canonical_obligation_semantic_digest_index_sha256(&requested)
        .expect("fixture bundle must digest");

    let bindings = vec![PendingNativeTrustIrBinding {
        obligation_index: 0,
        verifier_suite: "trust-mc",
        proof_obligation_id: trust_ir::ProofId::new(0),
    }];
    (module, bundle, bindings, semantic_digests)
}

/// FAIL-CLOSED (bundled-member identity): source population may READ the owner
/// the append seam resolved from the row's own typed context. It may never
/// re-stamp it.
///
/// This is the coverage whose absence let that seam ship as DEAD CODE.
/// `populate_native_trust_ir_proof_sources` took a scalar root `FuncId` and
/// assigned it to every bound row unconditionally, and it runs AFTER the append
/// loop — so `.with_function(owner.function_id)` was overwritten for every row
/// on every compilation. With only the root scope constructed today both values
/// are equal, which is exactly why the seam's conservation result
/// (LOST=0/GAINED=0) could not distinguish a working seam from a no-op: no
/// measurement over root-only input can. Only a row carrying a NON-root owner
/// discriminates, which is what this test supplies.
///
/// Mutation control: restoring the overwrite must turn this red.
#[test]
fn native_proof_source_population_preserves_the_append_seam_owner() {
    let (mut module, bundle, bindings, semantic_digests) =
        native_proof_source_population_fixture(Some(1));

    populate_native_trust_ir_proof_sources(&mut module, &bundle, &bindings, &semantic_digests)
        .expect("an attributed row must populate its source identity");

    let row = &module.proof_obligations[0];
    // The row was really VISITED. Without this the owner assertion below would
    // pass just as well on a population pass that skipped the row entirely —
    // which is the same class of mistake as reading a no-op as a green.
    let source = row.source.as_ref().expect("source population must have run on this row");
    assert_eq!(
        source.public.as_ref().map(|public| public.obligation_id.as_str()),
        Some("vc:demo:member:0"),
        "the visited row must carry its own public identity"
    );
    assert_eq!(
        row.function,
        Some(trust_ir::FuncId::new(1)),
        "source population must READ the append seam's owner, never overwrite it with the root"
    );
}

/// FAIL-CLOSED (bundled-member identity): a bound row that reached source
/// population with no owning body is REFUSED.
///
/// The overwrite this replaces made every such row a ROOT row silently. An
/// unattributed row is an unresolved owner, not a root one, and publishing it
/// under the subject's identity is the exact laundering slice 0 removes.
#[test]
fn native_proof_source_population_refuses_an_unattributed_row() {
    let (mut module, bundle, bindings, semantic_digests) =
        native_proof_source_population_fixture(None);

    let err =
        populate_native_trust_ir_proof_sources(&mut module, &bundle, &bindings, &semantic_digests)
            .expect_err("a row with no owning body must be refused, not silently rooted");
    assert!(err.contains("no owning body"), "{err}");
    assert!(err.contains("proof obligation 0"), "{err}");

    let row = &module.proof_obligations[0];
    assert!(row.function.is_none(), "the refusal must not attribute the row to anything");
    assert!(row.source.is_none(), "the refusal must precede this row's source write");
}

// ---------------------------------------------------------------------------
// Bundled-member Assert admission: private rows may not disappear at reset.
// ---------------------------------------------------------------------------

fn bundled_assert_test_identity(name: &str) -> trust_types::CalleeIdentity {
    let canonical = name.rsplit("::").next().unwrap_or(name);
    let digest = canonical.bytes().fold(0xcbf2_9ce4_8422_2325_u64, |state, byte| {
        state.wrapping_mul(0x100_0000_01b3).wrapping_add(u64::from(byte))
    });
    trust_types::CalleeIdentity {
        stable_crate_id: 0x6275_6e64_6c65_642d,
        def_index: digest as u32,
        substs_digest: [digest, digest.rotate_left(29)],
    }
}

fn bundled_assert_test_function_with_calls(
    name: &str,
    def_path: &str,
    callees: &[&str],
) -> trust_types::VerifiableFunction {
    let mut blocks = Vec::new();
    for (index, callee) in callees.iter().enumerate() {
        blocks.push(trust_types::BasicBlock {
            id: trust_types::BlockId(index),
            stmts: Vec::new(),
            terminator: trust_types::Terminator::Call {
                func: (*callee).to_string(),
                args: vec![
                    trust_types::Operand::Constant(trust_types::ConstValue::Uint(8, 8)),
                    trust_types::Operand::Constant(trust_types::ConstValue::Uint(2, 8)),
                ],
                dest: trust_types::Place::local(0),
                target: Some(trust_types::BlockId(index + 1)),
                span: native_trust_ir_test_span(300 + index as u32),
                atomic: None,
                is_foreign: false,
                is_unsafe_sig: false,
                callee_identity: Some(bundled_assert_test_identity(callee)),
                callee_key: None,
                unwind: trust_types::UnwindEdge::Unreachable,
            },
        });
    }
    blocks.push(trust_types::BasicBlock {
        id: trust_types::BlockId(callees.len()),
        stmts: Vec::new(),
        terminator: trust_types::Terminator::Return,
    });
    trust_types::VerifiableFunction {
        name: name.to_string(),
        def_path: def_path.to_string(),
        span: native_trust_ir_test_span(299),
        body: trust_types::VerifiableBody {
            locals: vec![trust_types::LocalDecl {
                index: 0,
                ty: trust_types::Ty::u8(),
                name: Some("ret".into()),
            }],
            blocks,
            arg_count: 0,
            return_ty: trust_types::Ty::u8(),
            datatype_defs: Default::default(),
        },
        contracts: Vec::new(),
        preconditions: Vec::new(),
        postconditions: Vec::new(),
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

fn bundled_assert_test_ledger(
    members: &[trust_types::VerifiableFunction],
) -> BundledMemberSourceIdentityLedger {
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    for member in members.iter().skip(1) {
        record_bundled_member_source_identity(
            &mut ledger,
            member,
            Some(bundled_assert_test_identity(&member.name)),
            // The existing gate tests exercise the FOREIGN path — the class the
            // gate exists for — so the helper records non-local provenance.
            false,
            // ... and a foreign def is not the monomorphization question either.
            false,
            // Not a caller-bundle question: no member here was verified as its own root.
            false,
            // Trust (2026-09-29): not an authentic sysroot body — the runtime-checked
            // disposition is exercised by its own tests.
            false,
        )
        .expect("synthetic member source must serialize");
    }
    ledger
}

fn bundled_assert_test_gate(
    root: &trust_types::VerifiableFunction,
    members: &[trust_types::VerifiableFunction],
    vcs: &[VerificationCondition],
) -> Result<(), String> {
    let ledger = bundled_assert_test_ledger(members);
    ensure_bundled_member_asserts_exactly_charged(
        root,
        members,
        &ledger,
        vcs,
        &FxHashSet::default(),
    )
}

/// Trust (2026-10-02, census-vcgen-hang): the `Vec`-forwarder gate
/// (`vec_index_forwarder::charge_vec_index_forwarders`) regenerates the root's
/// owned-`Vec` index row at EVERY root call site of a forwarder. Unscoped, each
/// regeneration rebuilt the root's whole-function statement-version oracle:
/// O(sites x body), minutes past the 120 s budget on aterm-census
/// `run_lock_order_census` (1114 blocks, 24 sites), inside native bundle
/// construction, where nothing polled the deadline. Pinned at the gate, both
/// halves: one VC-gen memo scope for the batch (ONE oracle for every site, where
/// the same replays unscoped build one per site), and a forwarder REFUSED, not
/// replayed, once the function's deadline has passed.
#[test]
fn vec_index_forwarder_gate_replays_under_one_scope_and_stops_at_the_deadline() {
    const INDEX: &str = "<std::vec::Vec<u32> as core::ops::index::Index<usize>>::index";
    const SITES: usize = 8;
    let usize_ty = || trust_types::Ty::Int { width: 64, signed: false };
    let mut locals = vec![
        trust_types::LocalDecl { index: 0, ty: trust_types::Ty::Unit, name: Some("ret".into()) },
        trust_types::LocalDecl {
            index: 1,
            ty: trust_types::Ty::Ref {
                mutable: false,
                inner: Box::new(trust_types::Ty::adt("std::vec::Vec<u32>", vec![])),
            },
            name: Some("v".into()),
        },
        trust_types::LocalDecl { index: 2, ty: usize_ty(), name: Some("i".into()) },
    ];
    // `fn root(v: &Vec<u32>, i: usize)`: SITES calls `v[i]`, one per block, each
    // through its own index temp and destination, every call naming the forwarder
    // by name AND by its compiler-authenticated identity.
    let mut blocks = Vec::new();
    for k in 0..SITES {
        let index_temp = locals.len();
        locals.push(trust_types::LocalDecl { index: index_temp, ty: usize_ty(), name: None });
        let dest = locals.len();
        locals.push(trust_types::LocalDecl {
            index: dest,
            ty: trust_types::Ty::Ref {
                mutable: false,
                inner: Box::new(trust_types::Ty::Int { width: 32, signed: false }),
            },
            name: None,
        });
        blocks.push(trust_types::BasicBlock {
            id: trust_types::BlockId(k),
            stmts: vec![trust_types::Statement::Assign {
                place: trust_types::Place::local(index_temp),
                rvalue: trust_types::Rvalue::Use(trust_types::Operand::Copy(
                    trust_types::Place::local(2),
                )),
                span: native_trust_ir_test_span(400 + k as u32),
            }],
            terminator: trust_types::Terminator::Call {
                func: INDEX.to_string(),
                args: vec![
                    trust_types::Operand::Copy(trust_types::Place::local(1)),
                    trust_types::Operand::Copy(trust_types::Place::local(index_temp)),
                ],
                dest: trust_types::Place::local(dest),
                target: Some(trust_types::BlockId(k + 1)),
                span: native_trust_ir_test_span(400 + k as u32),
                atomic: None,
                is_foreign: false,
                is_unsafe_sig: false,
                callee_identity: Some(bundled_assert_test_identity(INDEX)),
                callee_key: None,
                unwind: trust_types::UnwindEdge::Unreachable,
            },
        });
    }
    blocks.push(trust_types::BasicBlock {
        id: trust_types::BlockId(SITES),
        stmts: Vec::new(),
        terminator: trust_types::Terminator::Return,
    });
    let root = trust_types::VerifiableFunction {
        name: "root".to_string(),
        def_path: "demo::root".to_string(),
        span: native_trust_ir_test_span(399),
        body: trust_types::VerifiableBody {
            locals,
            blocks,
            arg_count: 2,
            return_ty: trust_types::Ty::Unit,
            datatype_defs: Default::default(),
        },
        contracts: Vec::new(),
        preconditions: Vec::new(),
        postconditions: Vec::new(),
        spec: Default::default(),
        tuple_layouts: Default::default(),
    };
    let forwarder = bundled_assert_test_function_with_calls(INDEX, INDEX, &[]);
    let members = [root.clone(), forwarder.clone()];
    let mut ledger = bundled_assert_test_ledger(&members);
    vec_index_forwarder::attach_vec_index_forwarder_for_test(
        &mut ledger,
        &forwarder,
        vec_index_forwarder::VecIndexForwarderKind::Index,
    );
    let key = bundled_member_source_identity_key(&forwarder).expect("synthetic member serializes");

    // The root's inventory: its own owned-Vec index row at every site, regenerated
    // UNSCOPED here, which is also the control for the counter below.
    trust_vcgen::reset_analysis_memo_stats();
    let vcs: Vec<VerificationCondition> = (0..SITES)
        .map(|k| {
            let (kind, body) =
                trust_vcgen::owned_vec_scalar_index_row(&root, trust_types::BlockId(k))
                    .expect("every site is an owned-Vec scalar index row");
            VerificationCondition {
                kind,
                function: trust_types::Symbol::intern("demo::root"),
                location: native_trust_ir_test_span(400 + k as u32),
                formula: trust_types::Formula::Bool(true),
                contract_metadata: None,
                obligation: Some(trust_types::ObligationRecord {
                    body,
                    wrappers: Vec::new(),
                    subject: None,
                    width: None,
                }),
            }
        })
        .collect();
    let unscoped_oracles = trust_vcgen::analysis_memo_stats().entry_versions_computed;
    assert!(
        unscoped_oracles >= SITES as u64,
        "control: unscoped replays build one oracle per site ({unscoped_oracles} for {SITES})"
    );

    // The gate, no deadline in force: every site replayed and matched, one oracle.
    trust_vcgen::reset_analysis_memo_stats();
    let mut charges =
        vec_index_forwarder::charge_vec_index_forwarders(&root, &members, &ledger, &vcs)
            .expect("the gate runs");
    let gate_oracles = trust_vcgen::analysis_memo_stats().entry_versions_computed;
    assert_eq!(
        charges.verdicts.remove(&key),
        Some(Ok(())),
        "ANTI-VACUITY: the forwarder's every root site must be replayed and matched"
    );
    assert_eq!(gate_oracles, 1, "the gate must replay all {SITES} sites under ONE memo scope");

    // The function's deadline has passed: the forwarder is refused before a replay.
    let _budget = trust_types::verify_budget::VerifyBudgetGuard::install(
        Some(std::time::Instant::now()),
        u64::MAX,
    );
    trust_vcgen::reset_analysis_memo_stats();
    let mut charges =
        vec_index_forwarder::charge_vec_index_forwarders(&root, &members, &ledger, &vcs)
            .expect("the gate runs");
    let refused = charges.verdicts.remove(&key).expect("the forwarder is judged");
    let reason = refused.expect_err("a passed deadline must refuse the forwarder");
    assert!(
        reason.contains(NATIVE_BUNDLE_DEADLINE_DECLINE)
            && reason.contains("while the root's owned-Vec index rows were regenerated"),
        "refused for the wrong reason: {reason}"
    );
    assert_eq!(
        trust_vcgen::analysis_memo_stats().entry_versions_computed,
        0,
        "no row may be regenerated past the deadline"
    );
}

/// The 90f22093e9 local-member repair, both directions.
///
/// A LOCAL Assert-bearing member is exempt from the charging gate (the
/// universal-root policy verifies it as its own root; its Asserts are charged
/// there), so the gate admits it with NO caller-side charge rows at all. The
/// SAME member recorded as foreign must still refuse — and a member whose
/// provenance paths DISAGREE about locality must refuse too, because the
/// exemption composes fail-closed (`def_is_local &=`). If the exemption is
/// ever widened to foreign members, the second and third arms go red — that is
/// the false-proof class the gate closes and the exact `Wrapping<u8>` canary.
#[test]
fn bundled_member_assert_gate_local_exemption_is_local_only() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let members = [root.clone(), member.clone()];

    let record = |ledger: &mut BundledMemberSourceIdentityLedger, local: bool| {
        record_bundled_member_source_identity(
            ledger,
            &member,
            Some(bundled_assert_test_identity(&member.name)),
            local,
            // This test is about the LOCALITY conjunct; hold the
            // monomorphization one at its exempting value so the two are
            // measured independently. `..._local_but_generic_is_not_exempt`
            // below moves this one instead.
            false,
            // Not a caller-bundle question: no member here was verified as its own root.
            false,
            // Trust (2026-09-29): not an authentic sysroot body — the runtime-checked
            // disposition is exercised by its own tests.
            false,
        )
        .expect("synthetic member source must serialize")
    };

    // Local: admitted with zero caller-side VCs.
    let mut local_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut local_ledger, true);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &local_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect("a LOCAL Assert-bearing member must be exempt from the charging gate");

    // Foreign: the same member with no charge rows must refuse.
    let mut foreign_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut foreign_ledger, false);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &foreign_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect_err("a FOREIGN Assert-bearing member with no caller charge must refuse");

    // Disagreeing provenance: fail closed, gate stays on.
    let mut mixed_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut mixed_ledger, true);
    record(&mut mixed_ledger, false);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &mixed_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect_err("disagreeing locality provenance must keep the member gated");
}

/// Trust (BMC-LANE-1, 2026-11-09): the bridge's R107 exemption set is decided by the
/// member ledger on the RESOLVED body, never by a printed name (hostile review 4, F1:
/// a root built `--crate-name core` prints `core::…` and was exempted by name).
#[test]
fn compiler_authenticated_sysroot_members_is_the_ledger_verdict_only() {
    let root = bundled_assert_test_function_with_calls("root", "core::root", &["wrap"]);
    let authentic = exact_bundled_div_assert_member("wrap", "core::wrap");
    let impostor = exact_bundled_div_assert_member("wrap", "mydep::wrap");
    let local = exact_bundled_div_assert_member("local", "core::local");
    let mixed = exact_bundled_div_assert_member("mixed", "core::mixed");
    // Hostile review 5, F4: one path recorded it foreign, another local, both
    // authentic (a sysroot build's own crate is authentic). It is not foreign.
    let split = exact_bundled_div_assert_member("split", "core::split");
    // Two bodies under one def path: only the first is authenticated.
    let shared = exact_bundled_div_assert_member("shared_a", "core::shared");
    let shared_twin = exact_bundled_div_assert_member("shared_b", "core::shared");
    // A member printed with the root's def path, itself authenticated.
    let root_twin = exact_bundled_div_assert_member("root_twin", "core::root");
    let unrecorded = exact_bundled_div_assert_member("unrecorded", "core::unrecorded");

    let record = |ledger: &mut BundledMemberSourceIdentityLedger,
                  member: &trust_types::VerifiableFunction,
                  local: bool,
                  authentic: bool| {
        record_bundled_member_source_identity(
            ledger,
            member,
            Some(bundled_assert_test_identity(&member.name)),
            local,
            false,
            false,
            authentic,
        )
        .expect("synthetic member source must serialize")
    };
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    // The root is recorded as an authentic foreign body: index zero is still no member.
    record(&mut ledger, &root, false, true);
    record(&mut ledger, &authentic, false, true);
    record(&mut ledger, &impostor, false, false);
    record(&mut ledger, &local, true, true);
    record(&mut ledger, &mixed, false, true);
    record(&mut ledger, &mixed, false, false);
    record(&mut ledger, &split, false, true);
    record(&mut ledger, &split, true, true);
    record(&mut ledger, &shared, false, true);
    record(&mut ledger, &root_twin, false, true);

    let functions = [
        root.clone(),
        authentic.clone(),
        impostor,
        local,
        mixed,
        split,
        shared,
        shared_twin,
        root_twin,
        unrecorded,
    ];
    let members = compiler_authenticated_sysroot_members(&functions, &ledger)
        .expect("synthetic member sources must serialize");
    assert_eq!(
        members,
        FxHashSet::from_iter(["core::wrap".to_string()]),
        "only the foreign member every path authenticated, under a def path no \
         unauthenticated function shares, may be exempt"
    );

    // An empty ledger exempts nothing, whatever the names print.
    let none = compiler_authenticated_sysroot_members(
        &functions,
        &BundledMemberSourceIdentityLedger::default(),
    )
    .expect("synthetic member sources must serialize");
    assert!(none.is_empty(), "an unrecorded member is never exempt: {none:?}");

    // A bundle of the root alone exempts nothing, though the ledger authenticates it.
    let alone = compiler_authenticated_sysroot_members(&[root.clone()], &ledger)
        .expect("synthetic member sources must serialize");
    assert!(alone.is_empty(), "the root is never a member: {alone:?}");

    // Hostile review 5, F3: the verdict is on the exact BODY. A member with the
    // authenticated member's name and def path but another body is not that member,
    // so a lookup on (name, def path) alone would exempt it.
    let mut body_twin = authentic.clone();
    body_twin.body.locals[1].name = Some("lhs_twin".into());
    let twin = compiler_authenticated_sysroot_members(&[root, body_twin], &ledger)
        .expect("synthetic member sources must serialize");
    assert!(twin.is_empty(), "another body under an authenticated name is charged: {twin:?}");
}

/// Trust (BMC-LANE-1 hostile review 5, F4): a `StepBy` constructor qualification
/// needs EVERY admitting path to have recorded the member foreign. It read
/// `def_is_local`, which is ANDed toward local, so a member one path recorded local
/// and another foreign read as foreign and qualified.
#[test]
fn step_by_qualification_refuses_a_member_any_path_recorded_local() {
    let member = exact_bundled_div_assert_member("step_by", "core::iter::Iterator::step_by");
    let identity = bundled_assert_test_identity(&member.name);
    let qualification = || step_by_constructor::ConstructorQualification {
        identity,
        role: step_by_constructor::ConstructorMember::IteratorStepBy,
        no_drop_blocks: Vec::new(),
    };
    let ledger_of = |localities: &[bool]| {
        let mut ledger = BundledMemberSourceIdentityLedger::default();
        for &local in localities {
            record_bundled_member_source_identity(
                &mut ledger,
                &member,
                Some(identity),
                local,
                false,
                false,
                false,
            )
            .expect("synthetic member source must serialize");
        }
        ledger
    };
    let mut foreign = ledger_of(&[false, false]);
    step_by_constructor::record_qualification(&mut foreign, &member, qualification())
        .expect("a member every path recorded foreign qualifies");
    for localities in [[false, true], [true, false], [true, true]] {
        let mut ledger = ledger_of(&localities);
        assert!(
            step_by_constructor::record_qualification(&mut ledger, &member, qualification())
                .is_err(),
            "paths {localities:?}: a member any path recorded local never qualifies"
        );
    }
}

/// `fn root(p: *const u8) -> NonNull<u8> { wrap_ptr(p) }`, and `wrap_ptr`, a
/// member at `member_def_path` whose body is the transmute `_0 = _1 as NonNull<u8>`:
/// the shape R107 charges unless the compiler authenticated the member.
fn r107_forwarding_fixture(
    member_def_path: &str,
) -> (trust_types::VerifiableFunction, trust_types::VerifiableFunction) {
    let raw_u8 =
        || trust_types::Ty::RawPtr { mutable: false, pointee: Box::new(trust_types::Ty::u8()) };
    let nonnull_u8 = || {
        trust_types::Ty::adt(
            "core::ptr::non_null::NonNull",
            vec![("pointer".to_string(), raw_u8())],
        )
    };
    let function = |name: &str, def_path: &str, line: u32, block: trust_types::BasicBlock| {
        let mut blocks = vec![block];
        if blocks[0].stmts.is_empty() {
            blocks.push(trust_types::BasicBlock {
                id: trust_types::BlockId(1),
                stmts: Vec::new(),
                terminator: trust_types::Terminator::Return,
            });
        }
        trust_types::VerifiableFunction {
            name: name.to_string(),
            def_path: def_path.to_string(),
            span: native_trust_ir_test_span(line),
            body: trust_types::VerifiableBody {
                locals: vec![
                    trust_types::LocalDecl { index: 0, ty: nonnull_u8(), name: None },
                    trust_types::LocalDecl { index: 1, ty: raw_u8(), name: Some("p".into()) },
                ],
                blocks,
                arg_count: 1,
                return_ty: nonnull_u8(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    };
    let root = function(
        "root",
        "demo::root",
        340,
        trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: Vec::new(),
            terminator: trust_types::Terminator::Call {
                func: "wrap_ptr".to_string(),
                args: vec![trust_types::Operand::Copy(trust_types::Place::local(1))],
                dest: trust_types::Place::local(0),
                target: Some(trust_types::BlockId(1)),
                span: native_trust_ir_test_span(341),
                atomic: None,
                is_foreign: false,
                is_unsafe_sig: false,
                callee_identity: Some(bundled_assert_test_identity("wrap_ptr")),
                callee_key: None,
                unwind: trust_types::UnwindEdge::Unreachable,
            },
        },
    );
    let member = function(
        "wrap_ptr",
        member_def_path,
        350,
        trust_types::BasicBlock {
            id: trust_types::BlockId(0),
            stmts: vec![trust_types::Statement::Assign {
                place: trust_types::Place::local(0),
                rvalue: trust_types::Rvalue::Cast(
                    trust_types::Operand::Copy(trust_types::Place::local(1)),
                    nonnull_u8(),
                ),
                span: native_trust_ir_test_span(351),
            }],
            terminator: trust_types::Terminator::Return,
        },
    );
    (root, member)
}

/// The native bundle builder's lowering of the `r107_forwarding_fixture` bundle under
/// a ledger that recorded the member once with `provenance` (`(local, authentic)`), or
/// not at all.
fn r107_forwarding_build(
    member_def_path: &str,
    provenance: Option<(bool, bool)>,
) -> Result<Option<trust_ir_bridge::NativeVerificationBundle>, String> {
    let (root, member) = r107_forwarding_fixture(member_def_path);
    let compiler_contracts = trust_types::CompilerContractBundle::new(Vec::new());
    let mut bundle =
        trust_mir_extract::function_to_verifier_api_bundle(&root, &compiler_contracts, &[]);
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    if let Some((local, authentic)) = provenance {
        record_runtime_check_provenance(&mut ledger, &member, local, authentic);
    }
    build_native_trust_ir_bundle_from_verifiable_functions(
        &root,
        &mut bundle,
        vec![root.clone(), member],
        &ledger,
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(), // bundled_destructor_members: none
        &trust_ir_bridge::CallReachWithdrawals::default(), // call_reach_open_callees: no withdrawals
        None,
        None, // borrow_reach_scope: no scoped conjunct 3 on the test seam
        &trust_ir_bridge::InstanceHypothesisSites::default(),
        &trust_ir_bridge::CompilerAllocGrowPins::default(), // Trust: no grow pins
        None,
        &[],
        &[],
        None,
        &mut None,
        &mut PanicFreedomFoldAttestation::default(),
        &mut None,
        &mut Vec::new(),
        false,
        None,      // no query/HIR source carry on this fixture
        None,      // no private query-bound source reference on this fixture
        &mut None, // no source reference side table on this fixture
    )
}

/// The `(ICmp, Assert)` counts of the one bundled member (every function but `root`).
fn r107_member_charge(native: &trust_ir_bridge::NativeVerificationBundle) -> (usize, usize) {
    let lowered: Vec<_> =
        native.module.functions.iter().filter(|function| function.name != "root").collect();
    let [member] = lowered.as_slice() else {
        panic!("one bundled member, got {:?}", native.module.functions)
    };
    let nodes = || member.blocks.iter().flat_map(|block| block.body.iter());
    (
        nodes().filter(|node| matches!(node.inst, trust_ir::Inst::ICmp { .. })).count(),
        nodes().filter(|node| matches!(node.inst, trust_ir::Inst::Assert { .. })).count(),
    )
}

/// Trust (BMC-LANE-1 hostile review 5, F3): the R107 sysroot-member set reaches the
/// bridge through the native bundle builder, from the member ledger, and nothing else
/// exempts. A member the ledger authenticates as a foreign `core` body lowers with no
/// `!= 0` charge. Under every other verdict (a foreign body that is not authentic core,
/// a local body, no ledger entry) the same member keeps its `(1, 1)` charge. That
/// unkinded Assert does not refuse the bundle: it joins the whole-function
/// panic-freedom aggregate, and its being unlinked is what withholds a printing
/// program's `std-print-dispatch` attestation (`panic_freedom_fold_is_exclusive_for`).
/// The bridge's test seam alone could not see a builder that stopped forwarding the
/// set.
///
/// This reaches the instance-hypothesis entry: no test can mint the paired-condvar
/// crate certificate that selects the compiler-context entry production takes, whose
/// forwarding the e2e program r09's `std-print-dispatch` row pins
/// (docs/DECISION_QUEUE.md BMC-LANE-1, hostile review 5).
#[test]
fn r107_sysroot_member_set_reaches_the_bridge_from_the_ledger() {
    let member_path = "core::ptr::non_null::NonNull::<u8>::wrap_ptr";
    let exempt = r107_forwarding_build(member_path, Some((false, true)))
        .expect("an authenticated std member's transmute is std's obligation")
        .expect("the root's call binds a native bundle");
    assert_eq!(r107_member_charge(&exempt), (0, 0), "the authenticated member is not charged");

    for (provenance, shape) in [
        (Some((false, false)), "a foreign body that is not authentic core"),
        (Some((true, true)), "a local body"),
        (None, "a member absent from the ledger"),
    ] {
        let charged = r107_forwarding_build(member_path, provenance)
            .unwrap_or_else(|err| panic!("{shape}: the bundle is kept: {err}"))
            .unwrap_or_else(|| panic!("{shape}: the root's call binds a native bundle"));
        assert_eq!(r107_member_charge(&charged), (1, 1), "{shape} is charged");
    }
}

/// Trust (generics, 2026-09-13): being LOCAL is not sufficient for the exemption —
/// the bundled body must also BE the body the member's own root run verified.
///
/// The exemption's justification is "the universal-root policy verifies every
/// eligible local body as its own root in the same compile, so a local member's
/// Asserts are charged to the member's own run". That is exact for a local
/// NON-generic member. It is false for a per-instance member: the own-root run of a
/// local generic is over the POLYMORPHIC body, whose type parameters the producer
/// erased to `Ty::Unit`. An Assert that exists only at a concrete instantiation — a
/// bounds, overflow or layout check whose operands become concrete only there — is
/// absent from that run, so exempting the instance charges it to NOBODY, which is
/// the exact false-proof class this gate exists to close.
///
/// This test is written BEFORE the lane that admits such members, so the guard can
/// never be briefly open. It must keep failing closed if that lane lands.
#[test]
fn bundled_member_assert_gate_local_but_generic_is_not_exempt() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let members = [root.clone(), member.clone()];

    let record = |ledger: &mut BundledMemberSourceIdentityLedger, requires_mono: bool| {
        record_bundled_member_source_identity(
            ledger,
            &member,
            Some(bundled_assert_test_identity(&member.name)),
            true,
            requires_mono,
            // Not a caller-bundle question: no member here was verified as its own root.
            false,
            // Trust (2026-09-29): not an authentic sysroot body — the runtime-checked
            // disposition is exercised by its own tests.
            false,
        )
        .expect("synthetic member source must serialize")
    };

    // Control: local and NOT requiring monomorphization — the pre-existing
    // exemption, unchanged. Without this the test below could pass for the wrong
    // reason (e.g. a member that is gated for some unrelated cause).
    let mut mono_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut mono_ledger, false);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &mono_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect("a LOCAL non-generic Assert-bearing member must stay exempt");

    // The new conjunct: local, but the def requires monomorphization.
    let mut generic_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut generic_ledger, true);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &generic_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect_err(
        "a LOCAL member whose def requires monomorphization must NOT be exempt: its own \
         root run is over the parameter-erased body, so an Assert that exists only at a \
         concrete instantiation would be charged to nobody",
    );

    // Composition is fail-closed in the opposite polarity to locality: if ANY
    // admitting path says the def requires monomorphization, the gate stays on.
    let mut mixed_ledger = BundledMemberSourceIdentityLedger::default();
    record(&mut mixed_ledger, false);
    record(&mut mixed_ledger, true);
    ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &mixed_ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect_err("disagreeing monomorphization provenance must keep the member gated");
}

// ---------------------------------------------------------------------------
// Trust (2026-09-29): the runtime-checked std-member disposition of the gate.
// A member refused as a COMPLETENESS gap, foreign, whose body is an AUTHENTIC
// sysroot crate's, is kept and recorded; every other refusal still refuses the
// whole bundle. See `RuntimeCheckedStdMember`.
// ---------------------------------------------------------------------------

/// `exact_bundled_div_assert_member` with its Div replaced by an `Overflow(Add)`
/// Assert over an `Add`: refused by the bridge as `AssertKindOutsideLane`.
fn kind_refused_overflow_member(name: &str, def_path: &str) -> trust_types::VerifiableFunction {
    let mut member = exact_bundled_div_assert_member(name, def_path);
    let trust_types::Terminator::Assert { msg, .. } = &mut member.body.blocks[0].terminator else {
        panic!("the fixture's entry block ends in its Assert");
    };
    *msg = trust_types::AssertMessage::Overflow(trust_types::BinOp::Add);
    let trust_types::Statement::Assign { rvalue, .. } = &mut member.body.blocks[1].stmts[0] else {
        panic!("the fixture's success block computes its operation");
    };
    let trust_types::Rvalue::BinaryOp(op, ..) = rvalue else {
        panic!("the fixture's operation is a binary op");
    };
    *op = trust_types::BinOp::Add;
    assert!(matches!(
        trust_ir_bridge::bundled_member_assert_admission(&member),
        trust_ir_bridge::BundledMemberAssertAdmission::Refused {
            class: trust_ir_bridge::MemberAssertRefusalClass::AssertKindOutsideLane,
            ..
        }
    ));
    member
}

/// `exact_bundled_div_assert_member` dividing by a ZERO constant: refused by the
/// bridge as `Other` (a guaranteed trap is a defect, not a completeness gap).
fn other_refused_zero_divisor_member(
    name: &str,
    def_path: &str,
) -> trust_types::VerifiableFunction {
    let mut member = exact_bundled_div_assert_member(name, def_path);
    let trust_types::Statement::Assign { rvalue, .. } = &mut member.body.blocks[1].stmts[0] else {
        panic!("the fixture's success block computes its operation");
    };
    let trust_types::Rvalue::BinaryOp(_, _, divisor) = rvalue else {
        panic!("the fixture's operation is a binary op");
    };
    *divisor = trust_types::Operand::Constant(trust_types::ConstValue::Uint(0, 8));
    assert!(matches!(
        trust_ir_bridge::bundled_member_assert_admission(&member),
        trust_ir_bridge::BundledMemberAssertAdmission::Refused {
            class: trust_ir_bridge::MemberAssertRefusalClass::Other,
            ..
        }
    ));
    member
}

fn record_runtime_check_provenance(
    ledger: &mut BundledMemberSourceIdentityLedger,
    member: &trust_types::VerifiableFunction,
    local: bool,
    authentic: bool,
) {
    record_bundled_member_source_identity(
        ledger,
        member,
        Some(bundled_assert_test_identity(&member.name)),
        local,
        false,
        false,
        authentic,
    )
    .expect("synthetic member source must serialize");
}

fn runtime_check_gate(
    root: &trust_types::VerifiableFunction,
    members: &[trust_types::VerifiableFunction],
    ledger: &BundledMemberSourceIdentityLedger,
) -> Result<BundledMemberAssertGate, String> {
    ensure_bundled_member_asserts_exactly_charged_with_charges(
        root,
        members,
        ledger,
        &[],
        &FxHashSet::default(),
    )
}

/// The one admitting shape: KIND refusal, foreign, authentic sysroot body. The
/// bundle is kept, the member is recorded ONCE, and nothing is charged for it.
#[test]
fn runtime_checked_std_member_is_kept_only_for_an_authentic_foreign_completeness_gap() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["sum_closure"]);
    let member = kind_refused_overflow_member("sum_closure", "core::iter::sum::{closure#0}");
    let members = [root.clone(), member.clone()];
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut ledger, &member, false, true);
    let gate = runtime_check_gate(&root, &members, &ledger)
        .expect("an authentic foreign std member's completeness gap keeps the bundle");
    assert!(gate.own_charges.is_empty(), "the kept member is charged to no caller-side row");
    assert_eq!(
        gate.runtime_checked_std_members,
        vec![RuntimeCheckedStdMember {
            def_path: "core::iter::sum::{closure#0}".into(),
            class: trust_ir_bridge::MemberAssertRefusalClass::AssertKindOutsideLane,
            reason: "member Assert kind `Overflow(Add)` is outside the exact Div/Rem/BoundsCheck lane",
        }]
    );
    // A member reached twice is recorded once (dedupe by `def_path`).
    let twice = [root.clone(), member.clone(), member.clone()];
    let gate = runtime_check_gate(&root, &twice, &ledger).expect("still kept");
    assert_eq!(gate.runtime_checked_std_members.len(), 1);
}

/// Every conjunct is fail-closed: not authentic, local, `Other`, a ledger miss,
/// and a tolerated member followed by an `Other` refusal all refuse the bundle.
#[test]
fn runtime_checked_std_member_refuses_every_other_shape() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["sum_closure"]);
    let member = kind_refused_overflow_member("sum_closure", "core::iter::sum::{closure#0}");
    let members = [root.clone(), member.clone()];

    // (KIND, NOT authentic): a `--crate-name core` impostor's body.
    let mut impostor = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut impostor, &member, false, false);
    let err = runtime_check_gate(&root, &members, &impostor)
        .err()
        .expect("a non-authentic body's refused Assert must refuse the bundle");
    assert!(err.contains("refused Assert-bearing member `core::iter::sum::{closure#0}`"), "{err}");

    // (KIND, local but generic — the only local member the exemption above does
    // not already skip): its own root run owns its Asserts, never this row.
    let mut local = BundledMemberSourceIdentityLedger::default();
    record_bundled_member_source_identity(
        &mut local,
        &member,
        Some(bundled_assert_test_identity(&member.name)),
        true,
        true,
        false,
        true,
    )
    .expect("synthetic member source must serialize");
    assert!(
        runtime_check_gate(&root, &members, &local).is_err(),
        "a LOCAL member is never kept under the std disposition"
    );

    // (`Other`, authentic): an integrity/defect refusal is never tolerated.
    let zero = other_refused_zero_divisor_member("sum_closure", "core::iter::sum::{closure#0}");
    let zero_members = [root.clone(), zero.clone()];
    let mut other = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut other, &zero, false, true);
    assert!(
        runtime_check_gate(&root, &zero_members, &other).is_err(),
        "an `Other` refusal refuses the bundle even for an authentic body"
    );

    // Ledger miss: no provenance, no disposition.
    assert!(
        runtime_check_gate(&root, &members, &BundledMemberSourceIdentityLedger::default()).is_err(),
        "a member absent from the ledger counts as not authentic"
    );

    // Tolerated FIRST, then an `Other` refusal: scanning continues, and the later
    // refusal refuses the whole bundle.
    let root2 =
        bundled_assert_test_function_with_calls("root", "demo::root", &["sum_closure", "zero"]);
    let zero2 = other_refused_zero_divisor_member("zero", "core::zero");
    let both = [root2.clone(), member.clone(), zero2.clone()];
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut ledger, &member, false, true);
    record_runtime_check_provenance(&mut ledger, &zero2, false, true);
    let err = runtime_check_gate(&root2, &both, &ledger)
        .err()
        .expect("a later `Other` refusal still refuses the bundle");
    assert!(err.contains("`core::zero`"), "{err}");
}

/// The plain wrapper has no way to publish the rows the disposition owes, so it
/// must refuse a bundle whose admission rests on it (C8).
#[test]
fn the_plain_gate_refuses_a_bundle_that_owes_runtime_checked_rows() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["sum_closure"]);
    let member = kind_refused_overflow_member("sum_closure", "core::iter::sum::{closure#0}");
    let members = [root.clone(), member.clone()];
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut ledger, &member, false, true);
    assert!(runtime_check_gate(&root, &members, &ledger).is_ok());
    let err = ensure_bundled_member_asserts_exactly_charged(
        &root,
        &members,
        &ledger,
        &[],
        &FxHashSet::default(),
    )
    .expect_err("the plain gate cannot publish the member row");
    assert!(err.contains("needs a caller that publishes its row"), "{err}");
}

/// Authenticity composes fail-closed across the two recording lanes (`&=`): one
/// admitting path that says "not authentic" refuses the disposition.
#[test]
fn runtime_checked_std_member_authenticity_composes_fail_closed() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["sum_closure"]);
    let member = kind_refused_overflow_member("sum_closure", "core::iter::sum::{closure#0}");
    let members = [root.clone(), member.clone()];
    let mut agree = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut agree, &member, false, true);
    record_runtime_check_provenance(&mut agree, &member, false, true);
    assert!(runtime_check_gate(&root, &members, &agree).is_ok());
    for (first, second) in [(true, false), (false, true)] {
        let mut split = BundledMemberSourceIdentityLedger::default();
        record_runtime_check_provenance(&mut split, &member, false, first);
        record_runtime_check_provenance(&mut split, &member, false, second);
        assert!(
            runtime_check_gate(&root, &members, &split).is_err(),
            "disagreeing authenticity ({first}, {second}) must refuse"
        );
    }
    // Trust (BMC-LANE-1 hostile review 5, F4): and locality, toward NOT foreign. The
    // disposition read `!def_is_local`, which is ANDed toward local, so one path that
    // recorded the member local and one foreign read as foreign and kept the bundle. A
    // sysroot build's own crate is authentic (`crate_is_compiler_resident_sysroot`).
    for (first, second) in [(true, false), (false, true)] {
        let mut split = BundledMemberSourceIdentityLedger::default();
        record_runtime_check_provenance(&mut split, &member, first, true);
        record_runtime_check_provenance(&mut split, &member, second, true);
        assert!(
            runtime_check_gate(&root, &members, &split).is_err(),
            "disagreeing locality ({first}, {second}) must refuse"
        );
    }
}

/// C2: the builder records the member list the moment the gate admits it, and
/// NO later exit clears it — the `Ok(None)` no-bindings exit included. A verdict
/// built on the kept bundle can never lose the rows it owes. Stale content from a
/// previous body is cleared at entry, never inherited.
fn build_with_runtime_checked_member(
    root_calls: &[&str],
) -> (Result<Option<trust_ir_bridge::NativeVerificationBundle>, String>, Vec<RuntimeCheckedStdMember>)
{
    let root = bundled_assert_test_function_with_calls("root", "demo::root", root_calls);
    let member = kind_refused_overflow_member("sum_closure", "core::iter::sum::{closure#0}");
    let compiler_contracts = trust_types::CompilerContractBundle::new(Vec::new());
    let mut bundle =
        trust_mir_extract::function_to_verifier_api_bundle(&root, &compiler_contracts, &[]);
    let trust_ir_functions = vec![root.clone(), member.clone()];
    let mut ledger = BundledMemberSourceIdentityLedger::default();
    record_runtime_check_provenance(&mut ledger, &member, false, true);
    let mut kept = vec![RuntimeCheckedStdMember {
        def_path: "stale::previous".into(),
        class: trust_ir_bridge::MemberAssertRefusalClass::GuardedOrNonEntryPrefix,
        reason: "stale",
    }];
    let outcome = build_native_trust_ir_bundle_from_verifiable_functions(
        &root,
        &mut bundle,
        trust_ir_functions,
        &ledger,
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(), // bundled_destructor_members: none
        &trust_ir_bridge::CallReachWithdrawals::default(), // call_reach_open_callees: no withdrawals
        None,
        None, // borrow_reach_scope: no scoped conjunct 3 on the test seam
        &trust_ir_bridge::InstanceHypothesisSites::default(),
        &trust_ir_bridge::CompilerAllocGrowPins::default(), // Trust: no grow pins
        None,
        &[],
        &[],
        None,
        &mut None,
        &mut PanicFreedomFoldAttestation::default(),
        &mut None,
        &mut kept,
        false,
        None, // no query/HIR source carry on this fixture
        None, // no private query-bound source reference on this fixture
        &mut None, // no source reference side table on this fixture
    );
    (outcome, kept)
}

#[test]
fn the_builder_keeps_the_runtime_checked_list_on_every_exit() {
    let paths = |kept: &[RuntimeCheckedStdMember]| {
        kept.iter().map(|member| member.def_path.clone()).collect::<Vec<_>>()
    };
    // A root that CALLS the member: the synthesized panic-freedom row binds, so
    // the builder returns a bundle.
    let (outcome, kept) = build_with_runtime_checked_member(&["sum_closure"]);
    assert!(
        matches!(outcome, Ok(Some(_))),
        "a root calling the member binds its panic-freedom row: {:?}",
        outcome.as_ref().map(Option::is_some)
    );
    assert_eq!(paths(&kept), ["core::iter::sum::{closure#0}"]);
    // A root that binds NO public obligation: the builder takes its `Ok(None)`
    // exit, which clears every OTHER out-parameter — and must not clear this one.
    let (outcome, kept) = build_with_runtime_checked_member(&[]);
    assert!(
        matches!(outcome, Ok(None)),
        "this fixture binds no public obligation, so the builder takes its `Ok(None)` exit: {:?}",
        outcome.as_ref().map(Option::is_some)
    );
    assert_eq!(
        paths(&kept),
        ["core::iter::sum::{closure#0}"],
        "the list the gate recorded survives the `Ok(None)` exit, and the stale entry does not"
    );
}

fn exact_bundled_div_assert_member(name: &str, def_path: &str) -> trust_types::VerifiableFunction {
    let span = native_trust_ir_test_span(320);
    trust_types::VerifiableFunction {
        name: name.to_string(),
        def_path: def_path.to_string(),
        span: span.clone(),
        body: trust_types::VerifiableBody {
            locals: vec![
                trust_types::LocalDecl {
                    index: 0,
                    ty: trust_types::Ty::u8(),
                    name: Some("ret".into()),
                },
                trust_types::LocalDecl {
                    index: 1,
                    ty: trust_types::Ty::u8(),
                    name: Some("lhs".into()),
                },
                trust_types::LocalDecl {
                    index: 2,
                    ty: trust_types::Ty::u8(),
                    name: Some("rhs".into()),
                },
                trust_types::LocalDecl {
                    index: 3,
                    ty: trust_types::Ty::Bool,
                    name: Some("is_zero".into()),
                },
            ],
            blocks: vec![
                trust_types::BasicBlock {
                    id: trust_types::BlockId(0),
                    stmts: Vec::new(),
                    terminator: trust_types::Terminator::Assert {
                        cond: trust_types::Operand::Copy(trust_types::Place::local(3)),
                        expected: false,
                        msg: trust_types::AssertMessage::DivisionByZero,
                        target: trust_types::BlockId(1),
                        span: span.clone(),
                        unwind: trust_types::UnwindEdge::Unreachable,
                    },
                },
                trust_types::BasicBlock {
                    id: trust_types::BlockId(1),
                    stmts: vec![trust_types::Statement::Assign {
                        place: trust_types::Place::local(0),
                        rvalue: trust_types::Rvalue::BinaryOp(
                            trust_types::BinOp::Div,
                            trust_types::Operand::Copy(trust_types::Place::local(1)),
                            trust_types::Operand::Copy(trust_types::Place::local(2)),
                        ),
                        span: span.clone(),
                    }],
                    terminator: trust_types::Terminator::Return,
                },
            ],
            arg_count: 2,
            return_ty: trust_types::Ty::u8(),
            datatype_defs: Default::default(),
        },
        contracts: Vec::new(),
        preconditions: Vec::new(),
        postconditions: Vec::new(),
        spec: Default::default(),
        tuple_layouts: Default::default(),
    }
}

fn bundled_assert_test_summary(
    member: &trust_types::VerifiableFunction,
    callee: &str,
) -> trust_vcgen::FunctionSummary {
    let trust_ir_bridge::BundledMemberAssertAdmission::Derived { param_names, requires } =
        trust_ir_bridge::bundled_member_assert_admission(member)
    else {
        panic!("synthetic member must derive its complete Assert population");
    };
    let param_types = (1..=member.body.arg_count)
        .map(|index| {
            member
                .body
                .locals
                .iter()
                .find(|local| local.index == index)
                .expect("synthetic formal local exists")
                .ty
                .clone()
        })
        .collect();
    let mut summary = trust_vcgen::FunctionSummary::new(callee)
        .with_param_names(param_names)
        .with_param_types(param_types);
    for require in requires {
        summary = summary.with_precondition(require);
    }
    summary
}

fn bundled_assert_exact_precondition_vcs(
    root: &trust_types::VerifiableFunction,
    member: &trust_types::VerifiableFunction,
) -> Vec<VerificationCondition> {
    let mut summaries = trust_vcgen::SummaryDatabase::new();
    summaries.insert(bundled_assert_test_summary(member, &member.name));
    if member.def_path != member.name {
        summaries.insert(bundled_assert_test_summary(member, &member.def_path));
    }
    trust_vcgen::generate_callsite_precondition_vcs(root, &summaries)
        .into_iter()
        .filter(|vc| {
            matches!(
                &vc.kind,
                VcKind::Precondition { callee }
                    if callee == &member.name || callee == &member.def_path
            )
        })
        .collect()
}

#[test]
fn bundled_member_assert_gate_accepts_exact_multi_call_cardinality() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member", "member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let vcs = bundled_assert_exact_precondition_vcs(&root, &member);
    assert_eq!(vcs.len(), 2);
    assert_eq!(bundled_assert_test_gate(&root, &[root.clone(), member], &vcs), Ok(()));
}

#[test]
fn bundled_member_assert_gate_rejects_missing_wrong_and_extra_rows() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let members = [root.clone(), member];
    let exact = bundled_assert_exact_precondition_vcs(&root, &members[1]);

    let missing = bundled_assert_test_gate(&root, &members, &[])
        .expect_err("a missing charge must refuse the bundle");
    assert!(missing.contains("expected 1 exact caller-side precondition row(s), found 0"));

    let mut wrong = exact.clone();
    wrong[0].kind = VcKind::Precondition { callee: "other".to_string() };
    assert!(
        bundled_assert_test_gate(&root, &members, &wrong)
            .expect_err("a wrong-callee row cannot charge the member")
            .contains("found 0")
    );

    let extra = [exact[0].clone(), exact[0].clone()];
    assert!(
        bundled_assert_test_gate(&root, &members, &extra)
            .expect_err("an extra row makes the correspondence ambiguous")
            .contains("found 2")
    );
}

#[test]
fn bundled_member_assert_gate_rejects_formula_span_and_duplicate_callsite_forgery() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member", "member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let members = [root.clone(), member];
    let exact = bundled_assert_exact_precondition_vcs(&root, &members[1]);
    assert_eq!(exact.len(), 2);

    let mut wrong_formula = exact.clone();
    wrong_formula[0].formula = match exact[0].formula {
        Formula::Bool(true) => Formula::Bool(false),
        _ => Formula::Bool(true),
    };
    assert!(
        bundled_assert_test_gate(&root, &members, &wrong_formula)
            .expect_err("cardinality cannot authenticate an unrelated formula")
            .contains("formula/source identity")
    );

    let mut wrong_span = exact.clone();
    wrong_span[0].location.line_start += 100;
    wrong_span[0].location.line_end += 100;
    assert!(
        bundled_assert_test_gate(&root, &members, &wrong_span)
            .expect_err("a row from another source site cannot charge this call")
            .contains("formula/source identity")
    );

    let duplicated_first = [exact[0].clone(), exact[0].clone()];
    assert!(
        bundled_assert_test_gate(&root, &members, &duplicated_first)
            .expect_err("a duplicate first-site row cannot replace the second site's row")
            .contains("formula/source identity")
    );
}

#[test]
fn bundled_member_assert_gate_requires_member_and_call_concrete_identity() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member", "member"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let members = [root.clone(), member];
    let exact = bundled_assert_exact_precondition_vcs(&root, &members[1]);
    let ledger = bundled_assert_test_ledger(&members);

    let mut absent = root.clone();
    let trust_types::Terminator::Call { callee_identity, .. } =
        &mut absent.body.blocks[0].terminator
    else {
        unreachable!();
    };
    *callee_identity = None;
    let absent_members = [absent.clone(), members[1].clone()];
    assert!(
        ensure_bundled_member_asserts_exactly_charged(
            &absent,
            &absent_members,
            &ledger,
            &exact,
            &FxHashSet::default(),
        )
        .expect_err("a display name is not fallback proof identity")
        .contains("carries no compiler-authenticated concrete identity")
    );

    let mut conflicting = root.clone();
    let trust_types::Terminator::Call { callee_identity, .. } =
        &mut conflicting.body.blocks[1].terminator
    else {
        unreachable!();
    };
    *callee_identity = Some(bundled_assert_test_identity("different-member"));
    let conflicting_members = [conflicting.clone(), members[1].clone()];
    assert!(
        ensure_bundled_member_asserts_exactly_charged(
            &conflicting,
            &conflicting_members,
            &ledger,
            &exact,
            &FxHashSet::default(),
        )
        .expect_err("same-key duplicate calls must still agree on concrete body identity")
        .contains("does not match the exact extracted member source")
    );

    assert!(
        ensure_bundled_member_asserts_exactly_charged(
            &root,
            &members,
            &BundledMemberSourceIdentityLedger::default(),
            &exact,
            &FxHashSet::default(),
        )
        .expect_err("the member body itself needs compiler-owned provenance")
        .contains("exact extracted source has no unique")
    );
}

#[test]
fn bundled_member_regeneration_is_stable_with_unrelated_summaries() {
    let root = bundled_assert_test_function_with_calls("root", "demo::root", &["member", "other"]);
    let member = exact_bundled_div_assert_member("member", "demo::member");
    let minimal = bundled_assert_exact_precondition_vcs(&root, &member);
    assert_eq!(minimal.len(), 1);

    let mut full = trust_vcgen::SummaryDatabase::new();
    full.insert(bundled_assert_test_summary(&member, "member"));
    full.insert(
        trust_vcgen::FunctionSummary::new("other")
            .with_param_names(vec!["lhs".into(), "rhs".into()])
            .with_precondition(Formula::Bool(true)),
    );
    let all = trust_vcgen::generate_callsite_precondition_vcs(&root, &full);
    let full_member = all
        .iter()
        .filter(|vc| matches!(&vc.kind, VcKind::Precondition { callee } if callee == "member"))
        .collect::<Vec<_>>();
    assert_eq!(full_member.len(), minimal.len());
    assert!(
        minimal
            .iter()
            .zip(full_member)
            .all(|(expected, actual)| exact_bundled_member_precondition_vc(expected, actual)),
        "unrelated summary entries must not perturb a derived member's exact row"
    );
    assert_eq!(bundled_assert_test_gate(&root, &[root.clone(), member], &all), Ok(()));
}

